INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 1, '木兰花·城上风光莺语乱', 'songci-sc-2', '城上风光莺语乱，城下烟波春拍岸。绿杨芳草几时休？泪眼愁肠先已断。
情怀渐觉成衰晚，鸾镜朱颜惊暗换。昔年多病厌芳尊，今日芳尊惟恐浅。', '城上春光烂漫，黄莺的叫声乱成一片；城下烟波浩渺，春水拍打着堤岸。绿杨芳草年年如此，什么时候才有个了结？我泪眼愁肠，早已断尽。
心情渐渐感到衰颓迟暮，对镜一照，惊见红润的容颜暗暗换了模样。从前多病，见了酒杯就厌烦；如今却只怕杯中的酒太浅。', 'public-domain'),
  ('songci300', 2, '苏幕遮·碧云天', 'songci-sc-3', '碧云天，黄叶地，秋色连波，波上寒烟翠。山映斜阳天接水，芳草无情，更在斜阳外。
黯乡魂，追旅思。夜夜除非，好梦留人睡。明月楼高休独倚，酒入愁肠，化作相思泪。', '碧蓝的天，枯黄的地，秋色连着水波，波上笼着翠色的寒烟。远山映着斜阳，水天相接；无情的芳草，一直铺到斜阳之外。
思乡的心黯然销魂，羁旅的愁绪缠着不放，除非夜夜有好梦留人安睡。明月当空，不要独自倚在高楼上；酒入愁肠，只会化作相思的眼泪。', 'public-domain'),
  ('songci300', 3, '御街行·纷纷坠叶飘香砌', 'songci-sc-4', '纷纷坠叶飘香砌。夜寂静，寒声碎。真珠帘卷玉楼空，天淡银河垂地。年年今夜，月华如练，长是人千里。
愁肠已断无由醉。酒未到，先成泪。残灯明灭枕头欹，谙尽孤眠滋味。都来此事，眉间心上，无计相回避。', '纷纷飘落的树叶堆在带香气的台阶上。夜很静，细碎的寒声不断。珍珠帘卷起，玉楼空寂，天色清淡，银河低垂到地面。年年今夜，月光像白练一样明净，而人总是远隔千里。
愁肠已经断尽，无从借酒麻醉；酒还没到嘴边，先化成了泪。残灯忽明忽暗，斜靠着枕头，孤独失眠的滋味尝了个够。算来这份愁思，无论在眉间还是心上，都没有办法回避。', 'public-domain'),
  ('songci300', 4, '渔家傲·塞下秋来风景异', 'poems-cz9-18', '塞下秋来风景异，衡阳雁去无留意。
四面边声连角起，千嶂里，长烟落日孤城闭。
浊酒一杯家万里，燕然未勒归无计。
羌管悠悠霜满地，人不寐，将军白发征夫泪。', '边塞的秋天一来，风景就大不相同，大雁向衡阳飞去，毫不留恋。四面八方的边声随着号角响起，重重山峦之中，长烟升腾，落日低垂，孤城紧闭。一杯浊酒遥寄万里之外的家乡，可是边患未平、功业未成，归乡无从谈起。羌笛悠悠，寒霜满地，人们难以入睡，将军白了头发，征夫流下眼泪。', 'school'),
  ('songci300', 5, '千秋岁·数声鶗鴂', 'songci-sc-6', '数声鶗鴂，又报芳菲歇。惜春更选残红折。雨轻风色暴，梅子青时节。永丰柳，无人尽日花飞雪。
莫把幺弦拨，怨极弦能说。天不老，情难绝。心似双丝网，中有千千结。夜过也，东窗未白凝残月。', '几声杜鹃啼叫，又报告春天已经过去。因惜春，我特意挑一枝残花折下。雨点轻而风力猛，正是梅子发青的时节。永丰坊的柳树无人过问，整日飘着如雪的柳絮。
不要拨动那根细弦，怨到极处时，琴弦会把心事都说出来。天不会老，情也难断绝。心像双丝结成的网，中间有千千万万个结。夜已经过去了，东窗未白，只留着一弯残月。', 'public-domain'),
  ('songci300', 6, '菩萨蛮·哀筝一弄湘江曲', 'songci-sc-7', '哀筝一弄湘江曲，声声写尽湘波绿。纤指十三弦，细将幽恨传。
当筵秋水慢，玉柱斜飞雁。弹到断肠时，春山眉黛低。', '古筝哀怨地弹起一支湘江曲，声声都化作湘江的绿水。纤细的手指按着十三根弦，细细地把深藏的幽恨传出来。
筵席上，她的目光像秋水一样缓缓流动，弦柱像斜飞的雁行。弹到最伤心的地方，双眉微低，像笼着春山的黛色。', 'public-domain'),
  ('songci300', 7, '醉垂鞭·双蝶绣罗裙', 'songci-sc-8', '双蝶绣罗裙，东池宴，初相见。朱粉不深匀，闲花淡淡春。
细看诸处好，人人道，柳腰身。昨日乱山昏，来时衣上云。', '罗裙上绣着一对蝴蝶，那是在东池的宴席上初次相见。脸上的脂粉抹得很淡，像闲花淡淡地开着，自有一段春意。
细细看去，处处都好；人人都说，她的腰身像柳枝一样细。昨日黄昏乱山模糊，她来时衣上仿佛带着云彩。', 'public-domain'),
  ('songci300', 8, '一丛花·伤高怀远几时穷', 'songci-sc-9', '伤高怀远几时穷？无物似情浓。离愁正引千丝乱，更东陌、飞絮濛濛。嘶骑渐遥，征尘不断，何处认郎踪？
双鸳池沼水溶溶，南北小桡通。梯横画阁黄昏后，又还是、斜月帘栊。沉恨细思，不如桃杏，犹解嫁东风。', '登高伤怀、思念远人，什么时候才到尽头？没有什么比情更浓的东西了。离愁正引得千丝万缕纷乱，何况东边路上，飞絮迷蒙。嘶鸣的马越走越远，扬起的尘土不断，我到哪里去认他的行踪？
池水溶溶，有双鸳鸯嬉戏，南北的小船相通。黄昏后，画阁上梯子横放着，又还是那一钩斜月照着窗帘。深恨之中细细想来，还不如桃花杏花——它们还懂得嫁给东风。', 'public-domain'),
  ('songci300', 9, '天仙子·水调数声持酒听', 'songci-sc-10', '水调数声持酒听，午醉醒来愁未醒。送春春去几时回？临晚镜，伤流景，往事后期空记省。
沙上并禽池上暝，云破月来花弄影。重重帘幕密遮灯，风不定，人初静，明日落红应满径。', '端着酒听了几声《水调》，午间醉倒，醒来后愁还没醒。送走了春天，春天什么时候再回来？傍晚对镜，感伤时光流逝，往事与日后的约期都白白记在心里。
沙上成双的水鸟栖息，池边天色昏暝；云开月出，花在月下摆弄影子。层层帘幕密密遮住灯光，风还在吹，人刚刚静下来，料想明天落花该铺满小径了。', 'public-domain'),
  ('songci300', 10, '青门引·乍暖还轻冷', 'songci-sc-11', '乍暖还轻冷，风雨晚来方定。庭轩寂寞近清明，残花中酒，又是去年病。
楼头画角风吹醒，入夜重门静。那堪更被明月，隔墙送过秋千影。', '天气刚刚转暖，又有些微冷；风雨到傍晚才停。庭院冷清，将近清明，对着残花喝闷酒，又犯去年一样的病。
城楼上的画角声被风吹来，把人吹醒；入夜后重重门户一片寂静。更叫人受不了的是，明月还把隔墙那边的秋千影子送了过来。', 'public-domain'),
  ('songci300', 11, '生查子·含羞整翠鬟', 'songci-sc-12', '含羞整翠鬟，得意频相顾。雁柱十三弦，一一春莺语。
娇云容易飞，梦断知何处？深院锁黄昏，阵阵芭蕉雨。', '她含着羞整理乌黑的鬓发，又得意地频频回头。筝上十三根弦、十三根雁柱，一声声都像春天的黄莺在啼。
娇美的云彩容易飘散，梦断之后不知人在何处。深深的院落锁住了黄昏，只听见一阵阵雨打芭蕉。', 'public-domain'),
  ('songci300', 12, '浣溪沙·一曲新词酒一杯', 'songci-sc-13', '一曲新词酒一杯，去年天气旧亭台。夕阳西下几时回？
无可奈何花落去，似曾相识燕归来。小园香径独徘徊。', '唱一支新填的词，饮一杯酒，天气还是去年的天气，亭台还是旧日的亭台。夕阳西下，什么时候才能回来？
花儿落去，谁也无可奈何；燕子归来，好像是旧时相识。我独自在小园的花径上徘徊。', 'public-domain'),
  ('songci300', 13, '浣溪沙·一向年光有限身', 'songci-sc-14', '一向年光有限身，等闲离别易销魂。酒筵歌席莫辞频。
满目山河空念远，落花风雨更伤春。不如怜取眼前人。', '一年的时光有限，人的身体也有限，寻常的离别最叫人伤感。酒席歌筵，不要嫌它太频繁。
满眼山河，白白地思念远方；落花风雨，更添伤春之情。不如好好珍惜眼前的人。', 'public-domain'),
  ('songci300', 14, '清平乐·红笺小字', 'songci-sc-15', '红笺小字，说尽平生意。鸿雁在云鱼在水，惆怅此情难寄。
斜阳独倚西楼，遥山恰对帘钩。人面不知何处，绿波依旧东流。', '红色信笺上写满小字，把平生的心意都说了。可鸿雁在高云、游鱼在水底，这份情意无处寄送，只令人惆怅。
斜阳里独自倚着西楼，远山正对着帘钩。那张熟悉的脸不知去了哪里，只有绿波依旧向东流去。', 'public-domain'),
  ('songci300', 15, '清平乐·金风细细', 'songci-sc-16', '金风细细，叶叶梧桐坠。绿酒初尝人易醉，一枕小窗浓睡。
紫薇朱槿花残，斜阳却照阑干。双燕欲归时节，银屏昨夜微寒。', '秋风细细地吹，梧桐叶一片片落下。新酿的酒初尝容易醉，在小窗下枕着睡了一场。
紫薇和朱槿都已凋残，斜阳又照在栏杆上。正是双燕将要南归的时节，昨夜银屏后已有些微寒。', 'public-domain'),
  ('songci300', 16, '木兰花·燕鸿过后莺归去', 'songci-sc-17', '燕鸿过后莺归去，细算浮生千万绪。长于春梦几多时，散似秋云无觅处。
闻琴解佩神仙侣，挽断罗衣留不住。劝君莫作独醒人，烂醉花间应有数。', '燕子大雁先后北去南来，黄莺也归去了；细算这一生，千头万绪。相聚比起春梦来能长多少？一散开就像秋云，无处可寻。
不论是闻琴知音的卓文君，还是解佩相赠的神女，扯断了罗衣也留不住。劝你不要做独醒的人，在花丛中痛饮大醉，也是命中注定。', 'public-domain'),
  ('songci300', 17, '木兰花·绿杨芳草长亭路', 'songci-sc-18', '绿杨芳草长亭路，年少抛人容易去。楼头残梦五更钟，花底离愁三月雨。
无情不似多情苦，一寸还成千万缕。天涯地角有穷时，只有相思无尽处。', '绿杨芳草，长亭古道，年少的人轻易离我而去。楼头的残梦被五更的钟声惊醒，花下的离愁像三月的细雨。
无情不像有情那样苦，一寸相思还会化成千万缕。天涯地角总有尽头，只有相思没有尽头。', 'public-domain'),
  ('songci300', 18, '木兰花·池塘水绿风微暖', 'songci-sc-19', '池塘水绿风微暖，记得玉真初见面。重头歌韵响铮琮，入破舞腰红乱旋。
玉钩阑下香阶畔，醉后不知斜日晚。当时共我赏花人，点检如今无一半。', '池塘水绿，微风送暖，记得初见她的那一天。她重头唱来，歌声铮琮动听；入破时舞动腰肢，红裙旋转纷乱。
在玉钩栏杆下、香阶旁边，醉后不觉太阳已经西斜。当年与我一同赏花的人，如今数一数，不到一半了。', 'public-domain'),
  ('songci300', 19, '踏莎行·碧海无波', 'songci-sc-20', '碧海无波，瑶台有路。思量便合双飞去。当时轻别意中人，山长水远知何处。
绮席凝尘，香闺掩雾。红笺小字凭谁附？高楼目尽欲黄昏，梧桐叶上萧萧雨。', '碧海没有波浪，瑶台自有道路，想来本应双双飞去。当初轻易离别了心上人，如今山长水远，不知她在何处。
华美的席上积了尘，闺房笼着雾。写了小字的红笺，还能托谁送去？在高楼上望尽天涯，天色将晚，梧桐叶上已响起萧萧的雨声。', 'public-domain'),
  ('songci300', 20, '踏莎行·小径红稀', 'songci-sc-21', '小径红稀，芳郊绿遍，高台树色阴阴见。春风不解禁杨花，濛濛乱扑行人面。
翠叶藏莺，朱帘隔燕，炉香静逐游丝转。一场愁梦酒醒时，斜阳却照深深院。', '小路上花已稀少，郊野芳草绿遍，高台的树色在朦胧中显出。春风不懂得管束杨花，让它迷迷蒙蒙地乱扑行人的脸。
绿叶里藏着黄莺，红帘外隔着燕子，炉香静静地随着游丝旋转。一场愁梦酒醒的时候，斜阳正照着深深的庭院。', 'public-domain'),
  ('songci300', 21, '蝶恋花·六曲阑干偎碧树', 'songci-sc-332', '六曲阑干偎碧树，杨柳风轻，展尽黄金缕。谁把钿筝移玉柱？穿帘海燕双飞去。
满眼游丝兼落絮，红杏开时，一霎清明雨。浓睡觉来莺乱语，惊残好梦无寻处。', '六曲栏杆围着碧绿的树，杨柳风轻，柳条已绽出金黄的嫩丝。是谁把钿筝的玉柱移换，弹出新调？燕子穿过帘幕双双飞去。
满眼是游丝和飞絮，红杏开时，一场清明的急雨。浓睡醒来，莺声乱啼，惊破了我的好梦，再也无处寻觅。', 'public-domain'),
  ('songci300', 22, '凤箫吟·锁离愁', 'songci-sc-23', '锁离愁，连绵无际，来时陌上初熏。绣帏人念远，暗垂珠露，泣送征轮。长行长在眼，更重重、远水孤云。但望极楼高，尽日目断王孙。
销魂。池塘别后，曾行处、绿妒轻裙。恁时携素手，乱花飞絮里，缓步香茵。朱颜空自改，向年年、芳意长新。遍绿野，嬉游醉眼，莫负青春。', '芳草锁住离愁，连绵无边；来时路上，草香初起。绣帘中的人思念远行的人，暗暗垂下露珠般的泪，哭着送走远行的车轮。车马走远了，仍在眼中，更有重重远水和孤云。只能登上高楼极目远望，整日望到看不见行人。
伤心啊。池塘一别之后，她走过的地方，绿草都嫉妒她轻软的罗裙。那时牵着她的素手，在乱花飞絮中缓步走在香草地上。如今红颜白白地改变，而芳草年年依旧新绿。让它绿遍原野吧，纵情游乐、醉眼相看，不要辜负了青春。', 'public-domain'),
  ('songci300', 23, '木兰花·东城渐觉风光好', 'songci-sc-24', '东城渐觉风光好，縠皱波纹迎客棹。绿杨烟外晓寒轻，红杏枝头春意闹。
浮生长恨欢娱少，肯爱千金轻一笑。为君持酒劝斜阳，且向花间留晚照。', '城东的风光渐渐好起来，像绉纱一样的水波迎着游船。绿杨笼在轻烟里，清晨的寒意很轻；红杏枝头上，春意热闹非凡。
人生浮沉，常恨欢乐太少，怎肯吝惜千金而看轻一笑？我为你端着酒去劝斜阳：暂且留在花间，多照一会儿吧。', 'public-domain'),
  ('songci300', 24, '采桑子·群芳过后西湖好', 'songci-sc-25', '群芳过后西湖好，狼籍残红。飞絮濛濛，垂柳阑干尽日风。
笙歌散尽游人去，始觉春空。垂下帘栊，双燕归来细雨中。', '百花凋谢之后，西湖反而更好看：落花狼藉，柳絮迷蒙，垂柳拂着栏杆，整天吹着风。
笙歌散尽，游人离去，这才觉得春天空了。放下帘子，看一双燕子在细雨中归来。', 'public-domain'),
  ('songci300', 25, '诉衷情·清晨帘幕卷轻霜', 'songci-sc-26', '清晨帘幕卷轻霜，呵手试梅妆。都缘自有离恨，故画作远山长。
思往事，惜流芳，易成伤。拟歌先敛，欲笑还颦，最断人肠。', '清晨卷起帘幕，外面落着轻霜；呵暖手，试着画梅花妆。都因为心中自有离恨，所以把眉画得像远山一样长。
回想往事，惋惜流逝的芳华，最容易伤心。想唱歌先收起笑意，要笑又皱起眉头，最叫人断肠。', 'public-domain'),
  ('songci300', 26, '踏莎行·候馆梅残', 'songci-sc-27', '候馆梅残，溪桥柳细，草薰风暖摇征辔。离愁渐远渐无穷，迢迢不断如春水。
寸寸柔肠，盈盈粉泪，楼高莫近危阑倚。平芜尽处是春山，行人更在春山外。', '驿馆旁梅花凋残，溪桥边柳丝细长，草香风暖，他摇着马缰上路。离愁随着路程渐远而无穷无尽，像春水一样迢迢不断。
一寸寸柔肠，一行行粉泪；楼虽高，也别靠近栏杆去倚。平坦的原野尽头是春山，而远行的人还在春山之外。', 'public-domain'),
  ('songci300', 27, '蝶恋花·庭院深深深几许', 'songci-sc-28', '庭院深深深几许？杨柳堆烟，帘幕无重数。玉勒雕鞍游冶处，楼高不见章台路。
雨横风狂三月暮。门掩黄昏，无计留春住。泪眼问花花不语，乱红飞过秋千去。', '庭院深深，深到什么程度？杨柳堆着烟雾，帘幕一层又一层。他骑着玉勒雕鞍的马在外游乐，我登上高楼也望不见那条章台路。
风狂雨横，正是三月将尽。黄昏掩上门，也没有办法把春天留住。含着泪问花，花不回答；纷乱的落花飘过秋千飞走了。', 'public-domain'),
  ('songci300', 28, '蝶恋花·谁道闲情抛弃久', 'songci-sc-29', '谁道闲情抛弃久？每到春来，惆怅还依旧。日日花前常病酒，不辞镜里朱颜瘦。
河畔青芜堤上柳，为问新愁，何事年年有？独立小桥风满袖，平林新月人归后。', '谁说闲愁已经被抛下很久了？每到春天来，惆怅还是老样子。天天在花前喝醉，也不推辞镜子里红颜一天天消瘦。
河畔的青草、堤上的柳树，我问它们：新的愁为什么年年都有？我独自站在小桥上，风吹满衣袖；平展的树林上升起新月，人已归去。', 'public-domain'),
  ('songci300', 29, '蝶恋花·几日行云何处去', 'songci-sc-333', '几日行云何处去？忘却归来，不道春将暮。百草千花寒食路，香车系在谁家树？
泪眼倚楼频独语，双燕来时，陌上相逢否？撩乱春愁如柳絮，依依梦里无寻处。', '那片游云几日之间飘到哪里去了？忘了回来，也不管春天将尽。寒食路旁百草千花，你的香车系在了谁家的树上？
含泪倚楼，一再自言自语：双燕飞来时，路上可曾遇见他？撩乱的春愁像柳絮一样纷飞，只能在依稀的梦里，却也无处可寻。', 'public-domain'),
  ('songci300', 30, '木兰花·别后不知君远近', 'songci-sc-334', '别后不知君远近，触目凄凉多少闷。渐行渐远渐无书，水阔鱼沉何处问？
夜深风竹敲秋韵，万叶千声皆是恨。故敧单枕梦中寻，梦又不成灯又烬。', '分别以后不知你走得多远，满眼凄凉，说不尽的烦闷。你越走越远，越远越没有书信，水面辽阔、鱼儿深沉，到哪里去打听？
夜深了，风吹竹林敲出秋声，万叶千声都是怨恨。我斜靠着孤枕想在梦里寻你，梦没有做成，灯又烧成了灰。', 'public-domain'),
  ('songci300', 31, '浪淘沙·把酒祝东风', 'songci-sc-32', '把酒祝东风，且共从容。垂杨紫陌洛城东。总是当时携手处，游遍芳丛。
聚散苦匆匆，此恨无穷。今年花胜去年红。可惜明年花更好，知与谁同！', '举酒向东风祝愿：暂且从容一些。洛阳城东的垂杨大道上，都是当年我们携手同游、走遍花丛的地方。
聚散总是匆匆，这恨没有尽头。今年的花比去年红；可惜明年花更好，又知道能与谁一同观赏！', 'public-domain'),
  ('songci300', 32, '青玉案·一年春事都来几', 'songci-sc-33', '一年春事都来几？早过了、三之二。绿暗红嫣浑可事，绿杨庭院，暖风帘幕，有个人憔悴。
买花载酒长安市，又争似、家山见桃李。不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。', '一年的春事算起来有多少？早已过了三分之二。绿荫浓、红花艳，都还算好景；绿杨的庭院，暖风吹动帘幕，可有一个人憔悴着。
在长安城里买花载酒，又怎比得上在家乡看桃李。东风吹落客子的泪也不算白吹——相思难以表达，梦魂没有凭据，只有回去才是正理。', 'public-domain'),
  ('songci300', 33, '曲玉管·陇首云飞', 'songci-sc-34', '陇首云飞，江边日晚，烟波满目凭阑久。一望关河萧索，千里清秋，忍凝眸。杳杳神京，盈盈仙子，别来锦字终难偶。断雁无凭，冉冉飞下汀洲，思悠悠。
暗想当初，有多少、幽欢佳会，岂知聚散难期，翻成雨恨云愁。阻追游。每登山临水，惹起平生心事，一场消黯，永日无言，却下层楼。', '山顶云飞，江边日落，满眼烟波，我倚着栏杆站了很久。望出去关山河川一片萧索，千里清秋，怎忍心一直看下去。遥远的京城，那位盈盈的佳人，别后连书信也难得相通。失群的孤雁没有凭据，缓缓飞下汀洲，我的思念悠悠无尽。
暗自回想当初，有多少幽会欢聚，哪里知道聚散难以预期，反而变成云雨般的愁恨。想追寻旧游而不可得。每次登山临水，都惹起平生心事，一场黯然消魂，整天说不出一句话，只好走下高楼。', 'public-domain'),
  ('songci300', 34, '雨霖铃·寒蝉凄切', 'songci-sc-35', '寒蝉凄切，对长亭晚，骤雨初歇。都门帐饮无绪，留恋处、兰舟催发。执手相看泪眼，竟无语凝噎。念去去、千里烟波，暮霭沉沉楚天阔。
多情自古伤离别，更那堪、冷落清秋节！今宵酒醒何处？杨柳岸、晓风残月。此去经年，应是良辰好景虚设。便纵有千种风情，更与何人说？', '寒蝉叫得凄切，面对长亭，已是傍晚，一阵急雨刚停。在京城门外设帐饯别，毫无心绪；正留恋时，船上催着出发。握着手互相看着泪眼，竟哽噎得说不出一句话。想到这一去，千里烟波，暮霭沉沉，楚地天空辽阔。
自古多情的人最伤离别，更哪堪在这冷落的清秋时节！今夜酒醒时人在何处？只有杨柳岸边、晓风残月。这一去经年累月，良辰美景也都形同虚设。纵然有千种风情，又向谁诉说？', 'public-domain'),
  ('songci300', 35, '蝶恋花·伫倚危楼风细细', 'songci-sc-36', '伫倚危楼风细细，望极春愁，黯黯生天际。草色烟光残照里，无言谁会凭阑意。
拟把疏狂图一醉，对酒当歌，强乐还无味。衣带渐宽终不悔，为伊消得人憔悴。', '久立在高楼上，微风细细；望到天边，春愁黯然从那里生出。草色与烟光笼在残照里，我默默无言，谁能懂得我倚栏的心意。
本想放纵一场，图个一醉；对着酒唱歌，勉强作乐还是没滋味。衣带渐渐宽松也始终不悔，为了她，人瘦了也值得。', 'public-domain'),
  ('songci300', 36, '采莲令·月华收', 'songci-sc-37', '月华收，云淡霜天曙。西征客、此时情苦。翠娥执手送临歧，轧轧开朱户。千娇面、盈盈伫立，无言有泪，断肠争忍回顾。
一叶兰舟，便恁急桨凌波去。贪行色、岂知离绪，万般方寸，但饮恨、脉脉同谁语。更回首、重城不见，寒江天外，隐隐两三烟树。', '月华收尽，云淡霜天，天将破晓。西行的旅人，此时心里最苦。她握着我的手送到岔路口，朱红门户轧轧打开。千娇百媚的脸，盈盈地站着，说不出话，只有泪；我肝肠寸断，怎忍回头再看。
一叶兰舟，就这样飞快地划桨凌波而去。只顾着赶路，哪里懂得离愁别绪；千般滋味堵在心口，只能含恨，脉脉之情向谁诉说。再回头，重重城郭已看不见，寒江之外，天边隐隐只有两三株烟树。', 'public-domain'),
  ('songci300', 37, '浪淘沙慢·梦觉透窗风一线', 'songci-sc-38', '梦觉透窗风一线，寒灯吹息。那堪酒醒，又闻空阶，夜雨频滴。嗟因循、久作天涯客。负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。
愁极，再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被。岂暂时疏散，费伊心力。殢云尤雨，有万般千种，相怜相惜。
恰到如今，天长漏永，无端自家疏隔。知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。', '梦醒时一线风透进窗来，把寒灯吹灭了。更难受的是酒醒之后，又听见空台阶上夜雨滴滴答答。可叹我因循蹉跎，长久在外做天涯客，辜负了佳人多少盟誓，竟忍心把从前的欢会，一下子翻成忧愁。
愁到极处，再三追想：在洞房深处，有好几次饮罢歌残，香暖的鸳鸯被里。哪里是暂时的分别，实在费了她的心力。那时如云似雨，千种万般，互相怜惜。
到了如今，天长夜永，无缘无故地自己疏远了。不知何时才能重新拥着那如云的情态，愿在低垂的帷幕、贴身的枕上，轻轻地细细说给她听：在江乡的每一夜，我数着寒更思念你。', 'public-domain'),
  ('songci300', 38, '定风波·自春来', 'songci-sc-39', '自春来、惨绿愁红，芳心是事可可。日上花梢，莺穿柳带，犹压香衾卧。暖酥消、腻云亸，终日厌厌倦梳裹。无那，恨薄情一去，音书无个。
早知恁么，悔当初、不把雕鞍锁。向鸡窗、只与蛮笺象管，拘束教吟课。镇相随，莫抛躲，针线闲拈伴伊坐。和我，免使年少，光阴虚过。', '自从春天来了，绿叶凄惨、红花含愁，我心里对什么事都提不起劲。太阳升上花梢，黄莺在柳条间穿飞，我还赖在香被里躺着。肌肤消瘦，鬓发松垂，整天懒懒地不愿梳妆。无可奈何，只恨那薄情的人一去，连一封信也没有。
早知如此，后悔当初没有把他的马鞍锁住。让他在书房里，只用纸笔，拘着让他吟诗作文。要一直相随，不许躲开；闲时拈着针线陪他坐着。与我在一起，免得把这青春的年少光阴白白虚度。', 'public-domain'),
  ('songci300', 39, '少年游·长安古道马迟迟', 'songci-sc-40', '长安古道马迟迟，高柳乱蝉嘶。夕阳岛外，秋风原上，目断四天垂。
归云一去无踪迹，何处是前期？狎兴生疏，酒徒萧索，不似少年时。', '长安古道上，马儿慢吞吞地走，高柳上乱蝉嘶鸣。夕阳在岛屿之外，秋风起在原野上，望到天边，四面天幕低垂。
归云一去没有踪迹，从前的约期又在哪里？冶游的兴致已生疏，酒友也已零落，再不像少年时候了。', 'public-domain'),
  ('songci300', 40, '戚氏·晚秋天', 'songci-sc-41', '晚秋天，一霎微雨洒庭轩。槛菊萧疏，井梧零乱，惹残烟。凄然，望江关，飞云黯淡夕阳闲。当时宋玉悲感，向此临水与登山。远道迢递，行人凄楚，倦听陇水潺湲。正蝉吟败叶，蛩响衰草，相应喧喧。
孤馆度日如年，风露渐变，悄悄至更阑。长天净，绛河清浅，皓月婵娟。思绵绵，夜永对景，那堪屈指，暗想从前。未名未禄，绮陌红楼，往往经岁迁延。
帝里风光好，当年少日，暮宴朝欢。况有狂朋怪侣，遇当歌对酒竞留连。别来迅景如梭，旧游似梦，烟水程何限。念利名、憔悴长萦绊。追往事、空惨愁颜。漏箭移、稍觉轻寒。渐呜咽、画角数声残。对闲窗畔，停灯向晓，抱影无眠。', '晚秋天气，一阵小雨洒在庭院。栏杆旁的菊花稀疏，井边的梧桐零乱，惹起残烟。心里凄然，望向江关，飞云黯淡，夕阳悠闲。当年宋玉的悲感，正是在这样的地方临水登山。远路迢迢，行人凄楚，听厌了陇头流水的潺潺声。正当蝉在败叶间鸣，蟋蟀在衰草里叫，相互应和，一片喧闹。
独宿孤馆，度日如年；风露渐渐变冷，悄悄到了更深夜尽。长空澄净，银河清浅，皓月美好。思绪绵绵，长夜对着这景致，怎堪扳着指头回想从前。没有功名，没有俸禄，只在绮陌红楼里，往往一混就是一年。
京城风光好，当年年少时，朝朝暮暮宴饮欢乐。何况有一群狂放的朋友，遇到当歌对酒的场合就争着留连。别来光阴快得像梭子，旧游如梦，烟水茫茫，路程哪里有个尽头。想那名利，把人熬得憔悴，长久地缠住不放。追想往事，只是白白地满面愁惨。漏箭移动，渐渐觉得有些轻寒。画角声渐次呜咽，几声之后断了。对着闲窗，熄了灯守到天亮，抱着影子无法入睡。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 41, '夜半乐·冻云黯淡天气', 'songci-sc-42', '冻云黯淡天气，扁舟一叶，乘兴离江渚。渡万壑千岩，越溪深处。怒涛渐息，樵风乍起，更闻商旅相呼。片帆高举。泛画鹢、翩翩过南浦。
望中酒旆闪闪，一簇烟村，数行霜树。残日下、渔人鸣榔归去。败荷零落，衰杨掩映，岸边两两三三，浣纱游女。避行客、含羞笑相语。
到此因念，绣阁轻抛，浪萍难驻。叹后约丁宁竟何据。惨离怀、空恨岁晚归期阻。凝泪眼、杳杳神京路。断鸿声远长天暮。', '寒云黯淡的天气，一叶小舟乘兴离开江边。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，顺风忽然吹起，又听见商旅互相招呼。一片船帆高高扬起，画着鹢鸟的船翩翩驶过南浦。
远望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰柳掩映，岸边三三两两，是浣纱的游女。她们避开行人，含羞地笑着说话。
看到这里，就想起自己轻易抛下了绣阁，像浮萍一样漂泊难停。可叹临别时千叮万嘱的约期，究竟有什么凭据。离怀凄惨，白白怨恨岁暮归期受阻。含着泪眼，望那遥远的京城路。孤雁声远去，长天已暮。', 'public-domain'),
  ('songci300', 42, '玉蝴蝶·望处雨收云断', 'songci-sc-43', '望处雨收云断，凭阑悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻、苹花渐老，月露冷、梧叶飘黄。遣情伤。故人何在，烟水茫茫。
难忘。文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘。念双燕、难凭远信，指暮天、空识归航。黯相望。断鸿声里，立尽斜阳。', '望去雨收云散，我静静地倚着栏杆，目送秋光。晚景萧疏，足以触动宋玉那样的悲凉。水风轻，苹花渐渐老去；月露冷，梧桐叶飘黄。惹人伤情的是：故人在哪里？只见烟水茫茫。
难以忘怀。当年的文期酒会，多少次辜负了风月，星霜屡屡变换。海阔山遥，不知哪里才是潇湘。想托双燕，又难以递送远信；指着暮天，白白辨认归帆。黯然相望，在孤雁声中，一直站到斜阳落尽。', 'public-domain'),
  ('songci300', 43, '八声甘州·对潇潇暮雨洒江天', 'songci-sc-44', '对潇潇暮雨洒江天，一番洗清秋。渐霜风凄紧，关河冷落，残照当楼。是处红衰翠减，苒苒物华休。惟有长江水，无语东流。
不忍登高临远，望故乡渺邈，归思难收。叹年来踪迹，何事苦淹留？想佳人妆楼颙望，误几回、天际识归舟。争知我，倚阑干处，正恁凝愁。', '面对着潇潇暮雨洒遍江天，一番雨把清秋洗得更净。霜风渐渐凄紧，关河冷落，残阳照在楼上。到处红花衰败、绿叶凋减，美好的景物渐渐消歇。只有长江水，默默地向东流。
不忍登高望远，望故乡渺茫遥远，归思难以收住。可叹这些年来的行踪，为什么苦苦滞留他乡？想那佳人正在妆楼上抬头凝望，多少次把天边的船误认作我的归舟。她怎知道，我在倚栏的地方，正这样凝着愁。', 'public-domain'),
  ('songci300', 44, '迷神引·一叶扁舟轻帆卷', 'songci-sc-45', '一叶扁舟轻帆卷，暂泊楚江南岸。孤城暮角，引胡笳怨。水茫茫，平沙雁、旋惊散。烟敛寒林簇，画屏展。天际遥山小，黛眉浅。
旧赏轻抛，到此成游宦。觉客程劳，年光晚。异乡风物，忍萧索、当愁眼。帝城赊，秦楼阻，旅魂乱。芳草连空阔，残照满。佳人无消息，断云远。', '一片轻帆卷起，小舟暂泊在楚江南岸。孤城响起暮角，引出胡笳哀怨。江水茫茫，平沙上的大雁转眼被惊散。烟雾收敛，寒林成簇，像展开的画屏。天边的远山很小，像浅浅的黛眉。
轻易抛下了从前的欢赏，到这里做了游宦。觉得客途劳顿，年光已晚。异乡的风物，怎忍心在这愁眼前一片萧索。京城遥远，秦楼阻隔，旅人的心魂纷乱。芳草连着辽阔的天空，残照洒满。佳人没有消息，像断云一样远去了。', 'public-domain'),
  ('songci300', 45, '竹马子·登孤垒荒凉', 'songci-sc-46', '登孤垒荒凉，危亭旷望，静临烟渚。对雌霓挂雨，雄风拂槛，微收烦暑。渐觉一叶惊秋，残蝉噪晚，素商时序。览景想前欢，指神京，非雾非烟深处。
向此成追感，新愁易积，故人难聚。凭高尽日凝伫。赢得消魂无语。极目霁霭霏微，暝鸦零乱，萧索江城暮。南楼画角，又送残阳去。', '登上荒凉的孤垒，在高亭上远望，静静地面对烟雾中的洲渚。只见雌霓挂着雨，大风拂着栏杆，稍稍收去了闷热。渐渐觉得一片落叶惊动了秋意，残蝉在傍晚噪鸣，已是秋天的时序。看着这景致想起从前的欢乐，遥指京城，在非雾非烟的深处。
在这里生出追怀之感，新愁容易堆积，故人难以相聚。登高整日凝立，只落得黯然无语。极目望去，雨后的云气迷蒙，暮鸦零乱，江城的黄昏一片萧索。南楼上的画角，又把残阳送走了。', 'public-domain'),
  ('songci300', 46, '桂枝香·登临送目', 'poems-gz10-18', '登临送目，正故国晚秋，天气初肃。
千里澄江似练，翠峰如簇。
归帆去棹残阳里，背西风，酒旗斜矗。
彩舟云淡，星河鹭起，画图难足。
念往昔，繁华竞逐，叹门外楼头，悲恨相续。
千古凭高对此，谩嗟荣辱。
六朝旧事随流水，但寒烟衰草凝绿。
至今商女，时时犹唱，后庭遗曲。', '登上高处向远处眺望，正是故都金陵的晚秋时节，天气开始变得肃杀。千里澄澈的长江像一条白练，青翠的山峰像箭簇一样聚集。江中归来的船帆和离去的船桨沐浴在残阳里，背着西风，酒旗斜斜地竖着。彩绘的船只在淡云中，银河般的长江上白鹭飞起，这样的美景图画也难以画尽。回想往昔，人们竞相追逐繁华，可叹隋兵已临城下，陈后主还在楼头寻欢作乐，悲恨接连不断。千古以来登高凭吊，徒然感叹荣辱兴亡。六朝的旧事已随流水逝去，只剩寒烟衰草凝着一片绿色。至今歌女还时时唱着《玉树后庭花》那亡国之音。', 'school'),
  ('songci300', 47, '千秋岁引·别馆寒砧', 'songci-sc-48', '别馆寒砧，孤城画角，一派秋声入寥廓。东归燕从海上去，南来雁向沙头落。楚台风，庾楼月，宛如昨。
无奈被些名利缚，无奈被他情担阁，可惜风流总闲却。当初谩留华表语，而今误我秦楼约。梦阑时，酒醒后，思量着。', '别馆里的寒砧声，孤城上的画角声，一派秋声散入空阔的天空。东归的燕子从海上飞去，南来的大雁落在沙头。楚王的兰台之风、庾亮的南楼之月，宛然如昨。
无奈被那点名利缠住，无奈被那点人情耽搁，可惜风流都白白闲却了。当初白白留下华表上的话，如今又误了我秦楼的约会。梦醒的时候，酒醒以后，反复思量着。', 'public-domain'),
  ('songci300', 48, '清平乐·留春不住', 'songci-sc-49', '留春不住，费尽莺儿语。满地残红宫锦污，昨夜南园风雨。
小怜初上琵琶，晓来思绕天涯。不肯画堂朱户，春风自在杨花。', '留不住春天，白白费尽黄莺的啼叫。满地落花像弄脏了的宫锦——昨夜南园下了风雨。
小怜刚刚弹起琵琶，天亮时思绪已绕着天涯飞。它不肯待在画堂朱户里，春风中只有杨花自在地飞。', 'public-domain'),
  ('songci300', 49, '临江仙·梦后楼台高锁', 'songci-sc-50', '梦后楼台高锁，酒醒帘幕低垂。去年春恨却来时。落花人独立，微雨燕双飞。
记得小蘋初见，两重心字罗衣。琵琶弦上说相思。当时明月在，曾照彩云归。', '梦醒后楼台高锁，酒醒后帘幕低垂。去年的春恨又在此时涌上心头。落花中我独自站立，微雨里燕子双双飞过。
记得初次见到小蘋时，她穿着绣有两重心字的罗衣。琵琶弦上诉说着相思。当时的明月还在，曾照着她像彩云一样归去。', 'public-domain'),
  ('songci300', 50, '蝶恋花·醉别西楼醒不记', 'songci-sc-51', '醉别西楼醒不记，春梦秋云，聚散真容易。斜月半窗还少睡，画屏闲展吴山翠。
衣上酒痕诗里字，点点行行，总是凄凉意。红烛自怜无好计，夜寒空替人垂泪。', '醉别西楼，醒来已不记得；春梦秋云，聚散真是容易。斜月照进半窗，还是睡不着；画屏闲开着，展开一片吴山的翠色。
衣上的酒痕、诗里的字，点点行行，都是凄凉的意思。红烛自怜没有好办法，在寒夜里白白替人垂泪。', 'public-domain'),
  ('songci300', 51, '蝶恋花·梦入江南烟水路', 'songci-sc-52', '梦入江南烟水路，行尽江南，不与离人遇。睡里消魂无说处，觉来惆怅消魂误。
欲尽此情书尺素，浮雁沉鱼，终了无凭据。却倚缓弦歌别绪，断肠移破秦筝柱。', '梦里走进江南的烟水之路，走遍江南，也没遇上那离别的人。睡梦里的消魂无处诉说，醒来惆怅，才知消魂是误。
想把这份情都写进信里，可雁飞高空、鱼沉水底，终究没有凭据。只好靠着缓弦唱起别绪，唱到断肠，把秦筝的柱子都移破了。', 'public-domain'),
  ('songci300', 52, '鹧鸪天·彩袖殷勤捧玉钟', 'songci-sc-53', '彩袖殷勤捧玉钟，当年拚却醉颜红。舞低杨柳楼心月，歌尽桃花扇底风。
从别后，忆相逢，几回魂梦与君同。今宵剩把银釭照，犹恐相逢是梦中。', '她穿着彩袖殷勤地捧起玉杯，当年我甘愿喝得满脸通红。舞到杨柳楼头的月亮低下去，唱到桃花扇底的清风停息。
自从分别以后，回想相逢，多少回梦魂与你相同。今夜只管举着银灯照了又照，还怕这次相逢也是梦里。', 'public-domain'),
  ('songci300', 53, '生查子·关山魂梦长', 'songci-sc-54', '关山魂梦长，鱼雁音尘少。两鬓可怜青，只为相思老。
归梦碧纱窗，说与人人道：真个别离难，不似相逢好。', '关山阻隔，魂梦悠长；书信稀少，音信难通。两鬓原本可爱的黑发，只因为相思而变白。
梦里回到碧纱窗前，对那人说：离别真是难，不如相逢好。', 'public-domain'),
  ('songci300', 54, '木兰花·秋千院落重帘暮', 'songci-sc-55', '秋千院落重帘暮，彩笔闲来题绣户。墙头丹杏雨余花，门外绿杨风后絮。
朝云信断知何处？应作襄王春梦去。紫骝认得旧游踪，嘶过画桥东畔路。', '秋千院落里重重帘幕垂到黄昏，闲来用彩笔在绣户上题字。墙头的红杏是雨后残花，门外的绿杨是风后飞絮。
朝云般的她音信断绝，不知在哪里？大概随着襄王的春梦去了。紫骝马认得旧日游踪，嘶鸣着跑过画桥东边的路。', 'public-domain'),
  ('songci300', 55, '木兰花·小颦若解愁春暮', 'songci-sc-56', '小颦若解愁春暮，一笑留春春也住。晚红初减谢池花，新翠已遮隋堤树。
谁知错管春残事，到处登临曾费泪。此时金盏直须深，看尽落花能几醉？', '小颦若能懂得为春暮发愁，那么她一笑留春，春天也会停住。晚红刚刚从谢家池边的花上减退，新绿已经遮住隋堤的树。
谁知道白白操心了春残的事，处处登临都曾费了不少眼泪。此时金杯正该斟得深些——看尽落花，还能醉几回？', 'public-domain'),
  ('songci300', 56, '清平乐·留人不住', 'songci-sc-57', '留人不住，醉解兰舟去。一棹碧涛春水路，过尽晓莺啼处。
渡头杨柳青青，枝枝叶叶离情。此后锦书休寄，画楼云雨无凭。', '留不住人，他醉中解开兰舟离去。一桨划进碧涛春水，驶过所有黄莺啼叫的地方。
渡头的杨柳青青，枝枝叶叶都是离情。从今以后不必再寄书信了，画楼里的欢会本来就没有凭据。', 'public-domain'),
  ('songci300', 57, '阮郎归·天边金掌露成霜', 'songci-sc-58', '天边金掌露成霜，云随雁字长。绿杯红袖趁重阳，人情似故乡。
兰佩紫，菊簪黄，殷勤理旧狂。欲将沉醉换悲凉，清歌莫断肠。', '天边仙人掌上的承露盘结了霜，云随着雁行拉得很长。绿杯红袖趁着重阳欢聚，人情的温暖竟像在故乡。
佩上紫色的兰，簪上黄色的菊，殷勤地重理旧日的狂放。想用沉醉换掉悲凉，清歌一曲莫要唱断人肠。', 'public-domain'),
  ('songci300', 58, '阮郎归·旧香残粉似当初', 'songci-sc-59', '旧香残粉似当初，人情恨不如。一春犹有数行书，秋来书更疏。
衾凤冷，枕鸳孤，愁肠待酒舒。梦魂纵有也成虚，那堪和梦无。', '旧日的香气、残余的脂粉还像当初，可人情却恨不如从前。春天还有几行书信，入秋以后信更稀了。
凤被冷，鸳枕孤，愁肠只能等酒来舒展。梦魂纵然有也是空的，更哪堪连梦也没有。', 'public-domain'),
  ('songci300', 59, '六幺令·绿阴春尽', 'songci-sc-60', '绿阴春尽，飞絮绕香阁。晚来翠眉宫样，巧把远山学。一寸狂心未说，已向横波觉。画帘遮匝，新翻曲妙，暗许闲人带偷掐。
前度书多隐语，意浅愁难答。昨夜诗有回文，韵险还慵押。都待笙歌散了，记取来时霎。不消红蜡，闲云归后，月在庭花旧阑角。', '绿荫浓了，春天将尽，飞絮绕着香阁。傍晚时她眉画成宫中的样子，巧妙地学着远山。一寸狂热的心还没说出口，已在眼波里被人察觉。画帘四面遮着，新翻的曲子精妙，暗暗允许闲人偷学指法。
上次来信多藏隐语，用意浅而愁绪难答。昨夜的诗是回文体，韵太险也懒得押。都等笙歌散了，记住她来时的刹那。不必点红蜡——闲云归去之后，月亮还照在庭中花下旧栏杆的角上。', 'public-domain'),
  ('songci300', 60, '御街行·街南绿树春饶絮', 'songci-sc-61', '街南绿树春饶絮，雪满游春路。树头花艳杂娇云，树底人家朱户。北楼闲上，疏帘高卷，直见街南树。
阑干倚尽犹慵去，几度黄昏雨。晚春盘马踏青苔，曾傍绿阴深驻。落花犹在，香屏空掩，人面知何处。', '街南绿树成荫，春天柳絮很多，像雪铺满游春的路。树梢上繁花与娇云相杂，树下有人家的朱门。闲来登上北楼，把疏帘高高卷起，一直望见街南的树。
把栏杆倚遍还懒得离开，几番黄昏都下着雨。晚春时曾骑马踏过青苔，在绿荫下久久停留。如今落花还在，香屏空掩，那张熟悉的脸不知去了何处。', 'public-domain'),
  ('songci300', 61, '虞美人·曲阑干外天如水', 'songci-sc-62', '曲阑干外天如水，昨夜还曾倚。初将明月比佳期，长向月圆时候、望人归。
罗衣着破前香在，旧意谁教改。一春离恨懒调弦，犹有两行闲泪、宝筝前。', '曲栏杆外天色如水，昨夜我还曾倚在这里。起初把明月比作佳期，总在月圆的时候盼望人归来。
罗衣穿破了，从前的香气还在；旧日的情意，是谁教它改的？一春的离恨，懒得去调弦，却还有两行无端的热泪，落在宝筝前面。', 'public-domain'),
  ('songci300', 62, '留春令·画屏天畔', 'songci-sc-63', '画屏天畔，梦回依约，十洲云水。手捻红笺寄人书，写无限、伤春事。
别浦高楼曾漫倚，对江南千里。楼下分流水声中，有当日、凭高泪。', '画屏上远接天边，梦醒时依稀还在十洲的云水之间。手里捻着红笺给人写信，写不尽伤春的心事。
在离别的江边高楼上曾随意倚过，面对着千里江南。楼下分流的水声里，还留着当日登高洒下的眼泪。', 'public-domain'),
  ('songci300', 63, '思远人·红叶黄花秋意晚', 'songci-sc-64', '红叶黄花秋意晚，千里念行客。飞云过尽，归鸿无信，何处寄书得？
泪弹不尽临窗滴，就砚旋研墨。渐写到别来，此情深处，红笺为无色。', '红叶黄花，秋意已晚，我思念千里之外的行人。飞云过尽，归雁也不带信，书信能寄到哪里去？
眼泪弹不尽，临窗滴落，就着砚台随即研墨。渐渐写到别后的事，情深处，红笺都褪了颜色。', 'public-domain'),
  ('songci300', 64, '水调歌头·明月几时有', 'songci-sc-65', '明月几时有？把酒问青天。不知天上宫阙，今夕是何年。我欲乘风归去，又恐琼楼玉宇，高处不胜寒。起舞弄清影，何似在人间。
转朱阁，低绮户，照无眠。不应有恨，何事长向别时圆？人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。', '明月是什么时候才有的？我端起酒杯问青天。不知道天上的宫殿，今夜是哪一年。我想乘风回去，又怕琼楼玉宇太高，受不住那份寒冷。起身起舞，戏弄自己的影子，哪里比得上人间。
月光转过朱红楼阁，低低地照进雕花窗户，照着不能入睡的人。明月不该有什么怨恨，为什么总在离别时团圆？人有悲欢离合，月有阴晴圆缺，这种事自古难以周全。只愿人长久平安，虽隔千里，也能共赏这轮明月。', 'public-domain'),
  ('songci300', 65, '水龙吟·似花还似非花', 'songci-sc-66', '似花还似非花，也无人惜从教坠。抛家傍路，思量却是，无情有思。萦损柔肠，困酣娇眼，欲开还闭。梦随风万里，寻郎去处，又还被、莺呼起。
不恨此花飞尽，恨西园、落红难缀。晓来雨过，遗踪何在？一池萍碎。春色三分，二分尘土，一分流水。细看来，不是杨花，点点是离人泪。', '像花又不像花，也没有人怜惜，任它飘落。它离开枝头、依傍路旁，想来看似无情，其实有情。它缠绕着、折损着柔肠，困倦中娇眼欲开还闭。梦里随着风飘到万里之外，去找那人的去处，却又被黄莺啼醒。
不恨这花飞尽，只恨西园的落花难以再连缀。清晨雨过，它的踪迹在哪里？化作一池碎萍。春色若有三分，二分归了尘土，一分随了流水。细细看来，那不是杨花，一点一点都是离人的泪。', 'public-domain'),
  ('songci300', 66, '念奴娇·大江东去', 'poems-gz10-07', '大江东去，浪淘尽，千古风流人物。
故垒西边，人道是，三国周郎赤壁。
乱石穿空，惊涛拍岸，卷起千堆雪。
江山如画，一时多少豪杰。
遥想公瑾当年，小乔初嫁了，雄姿英发。
羽扇纶巾，谈笑间，樯橹灰飞烟灭。
故国神游，多情应笑我，早生华发。
人生如梦，一尊还酹江月。', '大江浩浩荡荡向东流去，巨浪淘尽了千百年来所有杰出的英雄人物。旧的营垒西边，人们说，那就是三国时周瑜大战赤壁的地方。陡峭的乱石直插云霄，惊人的巨浪拍打着江岸，卷起千万堆雪白的浪花。江山美得像一幅画，一时之间涌现出多少英雄豪杰。遥想当年周瑜，小乔刚刚嫁给他，他英姿勃发。手执羽扇，头戴纶巾，谈笑之间，强敌的战船就灰飞烟灭。神游于三国故地，应该笑我多愁善感，过早地生出白发。人生就像一场梦，还是把一杯酒洒向江中的明月吧。', 'academic'),
  ('songci300', 67, '永遇乐·明月如霜', 'songci-sc-68', '明月如霜，好风如水，清景无限。曲港跳鱼，圆荷泻露，寂寞无人见。紞如三鼓，铿然一叶，黯黯梦云惊断。夜茫茫，重寻无处，觉来小园行遍。
天涯倦客，山中归路，望断故园心眼。燕子楼空，佳人何在？空锁楼中燕。古今如梦，何曾梦觉，但有旧欢新怨。异时对、黄楼夜景，为余浩叹。', '明月如霜，好风如水，清景无边。曲港里鱼跳，圆荷上露珠泻落，寂寞无人看见。三更鼓响，一片落叶铿然，把梦一般的美好惊醒，心中黯然。夜色茫茫，重新寻找已无踪迹，醒来后把小园走了个遍。
我是天涯倦客，望着山中的归路，望断了故园的心眼。燕子楼已空，佳人何在？只白白锁着楼中的燕子。古今如梦，何曾有人梦醒？只有旧欢新怨。日后有人面对黄楼的夜景，也会替我长叹。', 'public-domain'),
  ('songci300', 68, '洞仙歌·冰肌玉骨', 'songci-sc-69', '冰肌玉骨，自清凉无汗。水殿风来暗香满。绣帘开、一点明月窥人，人未寝，欹枕钗横鬓乱。
起来携素手，庭户无声，时见疏星渡河汉。试问夜如何？夜已三更，金波淡、玉绳低转。但屈指、西风几时来，又不道、流年暗中偷换。', '冰一样的肌肤、玉一样的骨，自然清凉无汗。水殿上风吹来，暗暗满是香气。绣帘掀开，一点明月来窥人；人还未睡，斜靠着枕头，金钗横斜、鬓发零乱。
起身牵着她的素手，庭院寂静无声，不时看见稀疏的星子渡过银河。试问夜到什么时辰了？已过三更，月光淡了，玉绳星低低转动。只是扳着手指算西风几时来，却没料到流年已在暗中偷偷换了。', 'public-domain'),
  ('songci300', 69, '卜算子·缺月挂疏桐', 'poems-cz8-28', '缺月挂疏桐，漏断人初静。
谁见幽人独往来，缥缈孤鸿影。
惊起却回头，有恨无人省。
拣尽寒枝不肯栖，寂寞沙洲冷。', '弯弯的月亮挂在稀疏的梧桐树上，漏壶的水已经滴尽，人声刚刚静下来。谁见到幽居的人独自往来，仿佛那缥缈的孤雁的身影。它突然惊起又回过头来，心中有怨恨却无人能理解。它把寒冷的树枝都挑遍了也不肯栖宿，甘愿在寂寞凄冷的沙洲上独宿。', 'academic'),
  ('songci300', 70, '青玉案·三年枕上吴中路', 'songci-sc-71', '三年枕上吴中路。遣黄耳、随君去。若到松江呼小渡。莫惊鸥鹭，四桥尽是，老子经行处。
辋川图上看春暮。常记高人右丞句。作个归期天已许。春衫犹是，小蛮针线，曾湿西湖雨。', '三年梦里都想着回吴中的路。派黄犬随你归去。若到松江叫小渡船，不要惊动鸥鹭；四桥一带，都是我走过的地方。
在《辋川图》上看春暮的景致，常记得王维那样高人写的句子。定下归期，老天已经答应了。身上的春衫还是小蛮亲手缝的，曾被西湖的雨打湿过。', 'public-domain'),
  ('songci300', 71, '临江仙·夜饮东坡醒复醉', 'songci-sc-72', '夜饮东坡醒复醉，归来仿佛三更。家童鼻息已雷鸣，敲门都不应，倚杖听江声。
长恨此身非我有，何时忘却营营？夜阑风静縠纹平。小舟从此逝，江海寄余生。', '夜里在东坡饮酒，醒了又醉，回来时仿佛已三更。家童鼾声如雷，敲门都不应，只好拄着拐杖听江声。
常恨这身子不属于自己，什么时候才能忘掉那些营营碌碌？夜深风静，水面像绉纱一样平。就乘一叶小舟从此远去，把余生寄托在江海之间。', 'public-domain'),
  ('songci300', 72, '定风波·莫听穿林打叶声', 'songci-sc-73', '莫听穿林打叶声，何妨吟啸且徐行。竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生。
料峭春风吹酒醒，微冷，山头斜照却相迎。回首向来萧瑟处，归去，也无风雨也无晴。', '不要去听那穿林打叶的雨声，不妨一边吟诗长啸一边慢慢走。竹杖草鞋比骑马还轻快，怕什么？披一件蓑衣，任凭一生风雨。
料峭的春风吹醒了酒意，有些微冷；山头的斜阳却迎面照来。回头看看方才风雨萧瑟的地方——回去吧，也无所谓风雨，也无所谓晴。', 'public-domain'),
  ('songci300', 73, '江城子·十年生死两茫茫', 'poems-gz11-07', '十年生死两茫茫，不思量，自难忘。
千里孤坟，无处话凄凉。
纵使相逢应不识，尘满面，鬓如霜。
夜来幽梦忽还乡，小轩窗，正梳妆。
相顾无言，惟有泪千行。
料得年年肠断处，明月夜，短松冈。', '你我夫妻诀别已经整整十年，纵然不去刻意思念，也自然是难以忘怀。你的孤坟远在千里，没有地方能与你诉说心中的凄凉。即使相逢你也应该认不出我了，我已风尘满面，两鬓如霜。昨夜在幽幽的梦中忽然回到了故乡，看见你正在小窗前梳妆。我们相视无言，只有泪水流了千行。想来年年令我肝肠寸断的地方，就是那明月之夜、矮松冈上你的坟茔。', 'academic'),
  ('songci300', 74, '木兰花·霜余已失长淮阔', 'songci-sc-76', '霜余已失长淮阔，空听潺潺清颍咽。佳人犹唱醉翁词，四十三年如电抹。
草头秋露流珠滑，三五盈盈还二八。与余同是识翁人，惟有西湖波底月。', '霜降之后，淮河已失了宽阔的气象，只听见清颍河潺潺如咽。歌女还在唱醉翁的词，四十三年像闪电一抹就过去了。
草尖上的秋露像滚动的珠，月儿十五圆满、十六也还圆。与我一样认识醉翁的人，只有西湖水底的月亮。', 'public-domain'),
  ('songci300', 75, '贺新郎·乳燕飞华屋', 'songci-sc-74', '乳燕飞华屋，悄无人、桐阴转午，晚凉新浴。手弄生绡白团扇，扇手一时似玉。渐困倚、孤眠清熟。帘外谁来推绣户？枉教人、梦断瑶台曲。又却是，风敲竹。
石榴半吐红巾蹙。待浮花浪蕊都尽，伴君幽独。秾艳一枝细看取，芳心千重似束。又恐被、秋风惊绿。若待得君来向此，花前对酒不忍触。共粉泪，两簌簌。', '小燕飞过华屋，悄无人声，桐荫转过午后，傍晚凉爽，她刚沐浴过。手里把着生绡白团扇，扇子与手一时都像玉。渐渐困倦，斜倚着独自睡熟。帘外是谁来推绣户？白白教人从瑶台的仙梦里惊醒——却又只是风敲竹子。
石榴花半开，像蹙起的红巾。等那些浮花浪蕊都谢尽，它来陪伴你的幽独。细看那一枝浓艳，芳心千重，像被束住。又怕被秋风惊落绿叶。若等到你来时，面对花前饮酒也不忍触碰；那时花与粉泪，一同簌簌落下。', 'public-domain'),
  ('songci300', 76, '鹧鸪天·黄菊枝头生晓寒', 'songci-sc-78', '黄菊枝头生晓寒，人生莫放酒杯干。风前横笛斜吹雨，醉里簪花倒著冠。
身健在，且加餐，舞裙歌板尽清欢。黄花白发相牵挽，付与时人冷眼看。', '黄菊枝头带着清晨的寒意，人生在世不要让酒杯空着。风前横吹笛子，斜吹着雨；醉里簪花，帽子倒戴着。
身体还康健，就多吃些饭；舞裙歌板，尽情享受清欢。黄花与白发互相牵挽，随世人冷眼看去吧。', 'public-domain'),
  ('songci300', 77, '定风波·万里黔中一漏天', 'songci-sc-79', '万里黔中一漏天，屋居终日似乘船。及至重阳天也霁，催醉，鬼门关外蜀江前。
莫笑老翁犹气岸，君看，几人黄菊上华颠？戏马台南追两谢，驰射，风流犹拍古人肩。', '万里之外的黔中像天漏了一样，整日住在屋里像坐在船上。到了重阳，天也放晴了，就催人喝酒——在鬼门关外的蜀江边。
不要笑老翁还这样意气傲岸，你看，有几个人能把黄菊插上白头？在戏马台南追慕谢瞻、谢灵运；纵马驰射，风流还能与古人并肩。', 'public-domain'),
  ('songci300', 78, '清平乐·春归何处', 'poems-xx6-14', '春归何处？寂寞无行路。
若有人知春去处，唤取归来同住。
春无踪迹谁知？除非问取黄鹂。
百啭无人能解，因风飞过蔷薇。', '春天回到了哪里？一片寂寞，找不到它的踪迹。如果谁知道春天去了哪里，请叫它回来同住。谁知道春天却没有人知道它在何处，除非去问黄鹂。黄鹂百般啼叫，没有人能听懂它的意思，它便随着风势飞过蔷薇花去了。', 'school'),
  ('songci300', 79, '阮郎归·烹茶留客驻金鞍', 'songci-sc-335', '烹茶留客驻金鞍，月斜窗外山。别郎容易见郎难，有人愁远山。
归去后，忆前欢，画屏金博山。一杯春露莫留残，与郎扶玉山。', '煮茶留客，让他的金鞍马停下；月亮斜照窗外，映出远山。离别情郎容易，再见情郎却难，有人对着远山发愁。
回去以后，回想从前的欢会，画屏上画着金博山炉。这一杯春露似的酒不要剩下一点，让我扶你醉倒的身躯。', 'public-domain'),
  ('songci300', 80, '绿头鸭·晚云收', 'songci-sc-82', '晚云收，淡天一片琉璃。烂银盘、来从海底，皓色千里澄辉。莹无尘、素娥淡伫，静可数、丹桂参差。玉露初零，金风未凛，一年无似此佳时。露坐久，疏萤时度，乌鹊正南飞。
瑶台冷，阑干凭暖，欲下迟迟。念佳人、音尘别后，对此应解相思。最关情、漏声正永，暗断肠、花影偷移。料得来宵，清光未减，阴晴天气又争知。共凝恋、如今别后，还是隔年期。人强健，清尊素影，长愿相随。', '晚云收尽，淡淡的天像一片琉璃。银盘般的月亮从海底升起，皎洁的光千里澄明。它晶莹无尘，嫦娥静静地伫立；静得可以数清参差的丹桂。玉露初降，秋风还不冷，一年中没有比这更好的时候。我在露下久坐，疏疏的萤火不时飞过，乌鹊正向南飞。
瑶台清冷，栏杆却倚得暖了，想下去又迟迟不动。想那佳人在别后音信断绝，面对这月色也该懂得相思。最牵动心肠的是漏声正长，暗暗断肠的是花影偷移。料想明夜清光不会减，可阴晴天气又怎么预料？彼此凝恋，如今别后，还得再等一年。只愿人常康健，清酒与素影长久相随。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 81, '蝶恋花·欲减罗衣寒未去', 'songci-sc-83', '欲减罗衣寒未去，不卷珠帘，人在深深处。红杏枝头花几许？啼痕止恨清明雨。
尽日沉烟香一缕，宿酒醒迟，恼破春情绪。飞燕又将归信误，小屏风上西江路。', '想减一件罗衣，寒意还没退去；不卷珠帘，人在深院深处。红杏枝头开了多少花？泪痕里只恨清明时节的雨。
整日只有一缕沉香烟，昨夜的酒醒得迟，搅坏了春天的情绪。飞燕又把归来的信误了，小屏风上画着通往西江的路。', 'public-domain'),
  ('songci300', 82, '踏莎行·雾失楼台', 'songci-sc-84', '雾失楼台，月迷津渡。桃源望断无寻处。可堪孤馆闭春寒，杜鹃声里斜阳暮。
驿寄梅花，鱼传尺素。砌成此恨无重数。郴江幸自绕郴山，为谁流下潇湘去？', '雾遮住了楼台，月色迷失了渡口，望断桃源也找不到。孤馆紧闭，春寒难耐，杜鹃声里斜阳西下。
驿站寄来梅花，鱼腹传来书信，却把这恨堆砌得无法计数。郴江本自绕着郴山流，如今又是为谁流到潇湘去呢？', 'public-domain'),
  ('songci300', 83, '望海潮·梅英疏淡', 'songci-sc-85', '梅英疏淡，冰澌溶泄，东风暗换年华。金谷俊游，铜驼巷陌，新晴细履平沙。长记误随车。正絮翻蝶舞，芳思交加。柳下桃蹊，乱分春色到人家。
西园夜饮鸣笳。有华灯碍月，飞盖妨花。兰苑未空，行人渐老，重来是事堪嗟！烟暝酒旗斜。但倚楼极目，时见栖鸦。无奈归心，暗随流水到天涯。', '梅花稀疏淡了，冰块溶化流去，东风暗暗换了年华。金谷园的名胜、铜驼街的巷陌，新晴时细步走在平沙上。常记得错跟了别人的车。那时柳絮翻飞、蝴蝶飞舞，芳心交杂。柳下桃径，把春色乱分到各家。
西园夜里饮酒吹笳。华灯挡住月亮，飞驰的车盖妨碍看花。兰苑还没有空，行人却渐渐老了，重来这里事事可叹！烟雾昏暝，酒旗斜挂。只能倚楼极目，不时看见栖鸦。无奈归心，暗暗随流水到天涯。', 'public-domain'),
  ('songci300', 84, '八六子·倚危亭', 'songci-sc-86', '倚危亭，恨如芳草，萋萋刬尽还生。念柳外青骢别后，水边红袂分时，怆然暗惊。
无端天与娉婷。夜月一帘幽梦，春风十里柔情。怎奈向、欢娱渐随流水，素弦声断，翠绡香减，那堪片片飞花弄晚，蒙蒙残雨笼晴。正销凝，黄鹂又啼数声。', '倚着高亭，恨像芳草，铲尽了又长出来。想起柳外骑着青骢马分别之后，水边她红袖分手之时，心中怆然暗惊。
上天无端给了她这样的姿容。夜月下一帘幽梦，春风里十里柔情。怎奈欢娱渐渐随流水而去，素弦声断，翠绡香减；哪堪片片飞花在暮色里摆弄，蒙蒙残雨笼着晴光。正消魂凝望，黄鹂又啼了几声。', 'public-domain'),
  ('songci300', 85, '满庭芳·山抹微云', 'songci-sc-87', '山抹微云，天连衰草，画角声断谯门。暂停征棹，聊共引离尊。多少蓬莱旧事，空回首、烟霭纷纷。斜阳外，寒鸦万点，流水绕孤村。
消魂。当此际，香囊暗解，罗带轻分。谩赢得青楼，薄幸名存。此去何时见也？襟袖上、空惹啼痕。伤情处，高城望断，灯火已黄昏。', '山抹着微云，天连着衰草，谯门上的画角声断了。暂且停下征船，姑且一同举杯话别。多少蓬莱旧事，空自回首，只见烟霭纷纷。斜阳之外，寒鸦万点，流水绕着孤村。
消魂。在这时候，暗暗解下香囊，轻轻分开罗带。白白在青楼赢得薄幸的名声。这一去什么时候再见？襟袖上只空留啼痕。最伤情处，望断高城，灯火已在黄昏里。', 'public-domain'),
  ('songci300', 86, '满庭芳·碧水惊秋', 'songci-sc-88', '碧水惊秋，黄云凝暮，败叶零乱空阶。洞房人静，斜月照徘徊。又是重阳近也，几处处、砧杵声催。西窗下，风摇翠竹，疑是故人来。
伤怀。增怅望，新欢易失，往事难猜。问篱边黄菊，知为谁开？谩道愁须殢酒，酒未醒、愁已先回。凭阑久，金波渐转，白露点苍苔。', '碧水惊起秋意，黄云凝着暮色，败叶零乱地落在空台阶上。洞房里人静，斜月照着我徘徊。又快到重阳了，处处响起砧杵声催人。西窗下，风摇翠竹，疑是故人来。
伤怀。更添怅望，新欢容易失去，往事难以猜度。问篱边的黄菊，知道它为谁开？别说愁要靠酒来缠，酒还没醒，愁已先回来了。倚栏久了，月光渐渐移动，白露点着青苔。', 'public-domain'),
  ('songci300', 87, '减字木兰花·天涯旧恨', 'songci-sc-89', '天涯旧恨，独自凄凉人不问。欲见回肠，断尽金炉小篆香。
黛蛾长敛，任是春风吹不展。困倚危楼，过尽飞鸿字字愁。', '天涯旧恨，独自凄凉，无人过问。要看我的回肠，就像金炉里小篆香烧断成灰。
双眉长皱，任凭春风吹也展不开。困倦地倚着高楼，看尽飞鸿，字字都是愁。', 'public-domain'),
  ('songci300', 88, '浣溪沙·漠漠轻寒上小楼', 'songci-sc-90', '漠漠轻寒上小楼，晓阴无赖似穷秋。淡烟流水画屏幽。
自在飞花轻似梦，无边丝雨细如愁。宝帘闲挂小银钩。', '漠漠的轻寒漫上小楼，清晨的阴天无赖得像深秋。淡烟流水，画屏幽静。
自在的飞花轻得像梦，无边的丝雨细得像愁。宝帘闲挂在小银钩上。', 'public-domain'),
  ('songci300', 89, '阮郎归·湘天风雨破寒初', 'songci-sc-91', '湘天风雨破寒初，深沉庭院虚。丽谯吹罢小单于，迢迢清夜徂。
乡梦断，旅魂孤，峥嵘岁又除。衡阳犹有雁传书，郴阳和雁无。', '湘天的风雨冲破寒意之初，深沉的庭院空寂。丽谯楼上吹罢《小单于》，迢迢清夜流去。
乡梦断了，旅魂孤单，年岁峥嵘又到除夕。衡阳还有大雁传书，郴阳连雁也没有。', 'public-domain'),
  ('songci300', 90, '鹧鸪天·枝上流莺和泪闻', 'songci-sc-92', '枝上流莺和泪闻，新啼痕间旧啼痕。一春鱼鸟无消息，千里关山劳梦魂。
无一语，对芳尊，安排肠断到黄昏。甫能炙得灯儿了，雨打梨花深闭门。', '枝上流莺的啼声和着泪听，新的泪痕夹着旧的泪痕。一春没有鱼雁消息，千里关山白白劳烦梦魂。
一句话也没有，对着酒杯，安排着断肠直到黄昏。刚把灯点上，雨就打梨花，只好把门深深关上。', 'public-domain'),
  ('songci300', 91, '江城子·西城杨柳弄春柔', 'songci-sc-93', '西城杨柳弄春柔，动离忧，泪难收。犹记多情、曾为系归舟。碧野朱桥当日事，人不见，水空流。
韶华不为少年留，恨悠悠，几时休？飞絮落花时候、一登楼。便作春江都是泪，流不尽，许多愁。', '西城的杨柳在春风中摆动，牵动离愁，泪水难收。还记得她多情，曾为我系住归来的船。碧野朱桥是当年的旧事，人已不见，只有水空自流。
美好的年华不为少年停留，遗恨悠悠，几时才休？柳絮飘、落花飞的时候，独自登楼。纵使春江都是泪，也流不尽这许多愁。', 'public-domain'),
  ('songci300', 92, '临江仙·谪宦江城无屋买', 'songci-sc-336', '谪宦江城无屋买，残僧野寺相依。松间药臼竹间衣。水穷行到处，云起坐看时。
一个幽禽缘底事，苦来醉耳边啼？月斜西院愈声悲。青山无限好，犹道不如归。', '被贬到江城，没有房屋可买，只能与残僧在野寺里相依。松林间放着药臼，竹林间晾着衣裳。走到水流的尽头，就坐下看云起的时景。
一只幽禽为了什么事，苦苦地在我醉耳边啼叫？月亮斜过西院，叫声越发悲切。青山无限美好，它却还说「不如归去」。', 'public-domain'),
  ('songci300', 93, '水龙吟·问春何苦匆匆', 'songci-sc-95', '问春何苦匆匆，带风伴雨如驰骤。幽葩细萼，小园低槛，壅培未就。吹尽繁红，占春长久，不如垂柳。算春常不老，人愁春老，愁只是、人间有。
春恨十常八九。忍轻孤、芳醪经口。那知自是，桃花结子，不因春瘦。世上功名，老来风味，春归时候。纵樽前痛饮，狂歌似旧，情难依旧。', '问春为什么这样匆匆，带着风伴着雨像疾驰一般。幽静的花、细小的萼，小园低栏里，培土还没培好。吹尽了繁花，能长久占住春天的，不如垂柳。算来春永远不会老，是人愁春老，这愁只在人间有。
春恨十次里常有八九次。怎忍心轻易辜负了杯中美酒。哪知道桃花结子，并不是因为春去而消瘦。世上的功名，老来的滋味，都在春归的时候。纵然在杯前痛饮、狂歌如旧，情却难以依旧。', 'public-domain'),
  ('songci300', 94, '忆少年·无穷官柳', 'songci-sc-337', '无穷官柳，无情画舸，无根行客。南山尚相送，只高城人隔。
罨画园林溪绀碧，算重来、尽成陈迹。刘郎鬓如此，况桃花颜色。', '一眼望不到头的官柳，无情地载人远去的画船，无根漂泊的行客。南山还肯相送，只有高高的城墙把人隔开。
历下的园林像彩画，溪水呈青碧色，算起来他日重来，都要变成旧迹。刘郎的鬓发已这样斑白，何况桃花的颜色。', 'public-domain'),
  ('songci300', 95, '洞仙歌·青烟幂处', 'songci-sc-97', '青烟幂处，碧海飞金镜。永夜闲阶卧桂影。露凉时、零乱多少寒螀，神京远，惟有兰桥路近。
水晶帘不下，云母屏开，冷浸佳人淡脂粉。待都将许多明，付与金尊，投晓共、流霞倾尽。更携取、胡床上南楼，看玉做人间，素秋千顷。', '青烟笼罩的地方，碧海里飞出一面金镜。长夜里，空台阶上卧着桂树的影子。露水凉时，多少寒蝉零乱地叫；京城遥远，只有蓝桥的路近。
水晶帘不放下，云母屏打开，清冷浸着佳人淡淡的脂粉。要把这许多光明都交给金杯，到天亮时与流霞一同饮尽。再带着胡床登上南楼，看月色把人间做成玉，素净的秋色铺满千顷。', 'public-domain'),
  ('songci300', 96, '临江仙·忆昔西池池上饮', 'songci-sc-98', '忆昔西池池上饮，年年多少欢娱。别来不寄一行书。寻常相见了，犹道不如初。
安稳锦屏今夜梦，月明好渡江湖。相思休问定何如。情知春去后，管得落花无。', '回想当年在西池池上饮酒，年年有多少欢乐。别后连一行书信也不寄。即使寻常相见，还说不像当初。
今夜锦屏里安睡入梦，月明正好渡过江湖。相思不必问究竟怎样。明知春天去后，还管得了落花吗。', 'public-domain'),
  ('songci300', 97, '惜分飞·泪湿阑干花著露', 'songci-sc-99', '泪湿阑干花著露，愁到眉峰碧聚。此恨平分取，更无言语空相觑。
断雨残云无意绪，寂寞朝朝暮暮。今夜山深处，断魂分付潮回去。', '泪水打湿栏杆，花瓣上挂着露珠；愁到极处，眉毛像碧峰聚拢。这恨两人平分，再没有话说，只是空对着看。
断雨残云，毫无意绪，寂寞朝朝暮暮。今夜在山深处，把断了魂交给潮水带回去。', 'public-domain'),
  ('songci300', 98, '菩萨蛮·赤阑桥尽香街直', 'songci-sc-100', '赤阑桥尽香街直，笼街细柳娇无力。金碧上青空，花晴帘影红。
黄衫飞白马，日日青楼下。醉眼不逢人，午香吹暗尘。', '红栏杆的桥尽头，飘香的街道笔直；笼着街道的细柳娇柔无力。金碧楼台伸向青空，花开天晴，帘影泛红。
穿黄衫的人骑着白马飞驰，天天在青楼下。醉眼朦胧看不见人，午间的香气吹起暗尘。', 'public-domain'),
  ('songci300', 99, '谒金门·花满市', 'songci-sc-101', '花满市，月侵衣。小院回廊春寂寂。画帘风软燕归时，人在绿窗初睡起。
看花却是今年好，忆着去年人老。人生只合扬州死，禅智山光好墓田。', '花满街市，月色侵衣。小院回廊里春意寂寂。画帘外风软，正是燕子归来的时候；人在绿窗下刚刚睡起。
看花还是今年好，回想去年，人已老了一岁。人生只该老死在扬州——禅智寺的山光就是好墓地。', 'public-domain'),
  ('songci300', 100, '苏幕遮·燎沉香', 'songci-sc-338', '燎沉香，消溽暑。鸟雀呼晴，侵晓窥檐语。叶上初阳干宿雨。水面清圆，一一风荷举。
故乡遥，何日去？家住吴门，久作长安旅。五月渔郎相忆否？小楫轻舟，梦入芙蓉浦。', '点燃沉香，消去潮湿的暑气。鸟雀呼唤晴天，拂晓时在檐下探头啁啾。朝阳晒干了荷叶上隔夜的雨珠，水面清亮圆润，一枝枝风中的荷花高高擎起。
故乡遥远，哪天才能回去？家在吴门，却长久作客汴京。五月的渔郎还记不记得我？我梦见自己划着小桨轻舟，荡进荷花深处。', 'public-domain'),
  ('songci300', 101, '卜算子·我住长江头', 'songci-sc-103', '我住长江头，君住长江尾。日日思君不见君，共饮长江水。
此水几时休？此恨何时已？只愿君心似我心，定不负相思意。', '我住在长江的源头，你住在长江的末尾。天天想你却见不到你，好在共饮一江之水。
这水什么时候流尽？这恨什么时候了结？只愿你的心像我的心，就绝不辜负这份相思。', 'public-domain'),
  ('songci300', 102, '兰陵王·柳阴直', 'songci-sc-104', '柳阴直，烟里丝丝弄碧。隋堤上、曾见几番，拂水飘绵送行色。登临望故国，谁识京华倦客？长亭路，年去岁来，应折柔条过千尺。
闲寻旧踪迹，又酒趁哀弦，灯照离席。梨花榆火催寒食。愁一箭风快，半篙波暖，回头迢递便数驿，望人在天北。
凄恻，恨堆积！渐别浦萦回，津堠岑寂，斜阳冉冉春无极。念月榭携手，露桥闻笛。沉思前事，似梦里，泪暗滴。', '柳荫笔直，烟雾中丝丝柳条摆弄碧色。在隋堤上，曾见过多少次它拂着水面、飘着柳絮送人远行。登高远望故国，谁能理解我这京城倦客？长亭路上，年去年来，折下的柳条该有千尺了。
闲来寻觅旧日踪迹，又趁着哀弦饮酒，灯火照着离别的酒席。梨花与榆火催促寒食到来。愁那一帆风顺、一篙水暖，回头就已过了几个驿站，望见的人远在天北。
凄恻，恨堆积！送别的江口曲折回环，渡口冷冷清清，斜阳缓缓移动，春色无边。回想月下楼台携手、露桥听笛。沉思往事，像在梦里，眼泪暗暗滴落。', 'public-domain'),
  ('songci300', 103, '瑞龙吟·章台路', 'songci-sc-105', '章台路，还见褪粉梅梢，试花桃树。愔愔坊陌人家，定巢燕子，归来旧处。
黯凝伫，因念个人痴小，乍窥门户。侵晨浅约宫黄，障风映袖，盈盈笑语。
前度刘郎重到，访邻寻里，同时歌舞。惟有旧家秋娘，声价如故。吟笺赋笔，犹记燕台句。知谁伴、名园露饮，东城闲步。事与孤鸿去。探春尽是，伤离意绪。官柳低金缕。归骑晚、纤纤池塘飞雨。断肠院落，一帘风絮。', '章台路上，又看见梅梢褪了粉、桃树初绽花。街坊里人家安静，归巢的燕子回到旧处。
我黯然凝立，想起她当初痴小，刚在门边偷看。清早淡淡地抹着宫黄，用袖子挡风，盈盈地笑着说话。
前度刘郎重来，访邻寻里，当年一同歌舞的人。只有旧家的秋娘，声价还如从前。吟诗作赋，还记得那些燕台诗句。可知谁陪我在名园露下饮酒、在东城闲步。往事已随孤雁远去。探春所见，尽是伤离的情绪。官柳低垂着金丝般的柳条。暮色中骑马归来，池塘上飘着纤细的雨。断肠的院落，一帘风絮。', 'public-domain'),
  ('songci300', 104, '风流子·新绿小池塘', 'songci-sc-106', '新绿小池塘，风帘动、碎影舞斜阳。羡金屋去来，旧时巢燕；土花缭绕，前度莓墙。绣阁里、凤帏深几许？听得理丝簧。欲说又休，虑乖芳信；未歌先噎，愁近清觞。
遥知新妆了，开朱户、应自待月西厢。最苦梦魂，今宵不到伊行。问甚时说与，佳音密耗，寄将秦镜，偷换韩香。天便教人，霎时厮见何妨！', '小池塘一片新绿，风吹帘动，碎影在斜阳里舞。羡慕那金屋中来去的旧巢燕，羡慕那绕着旧日莓墙的苔花。绣阁里，凤帐深到什么程度？只听得她调理乐器。想说话又停住，怕误了佳音；还没唱就先哽住，愁绪贴近清酒。
远远想她新妆已就，打开朱门，该在西厢待月。最苦的是梦魂今夜也到不了她身边。问什么时候才能把好消息密告她，送去秦镜、偷换韩香。老天既然让人相见，哪怕只是片刻又何妨！', 'public-domain'),
  ('songci300', 105, '渡江云·晴岚低楚甸', 'songci-sc-107', '晴岚低楚甸，暖回雁翼，阵势起平沙。骤惊春在眼，借问何时，委曲到山家。涂香晕色，盛粉饰、争作妍华。千万丝、陌头杨柳，渐渐可藏鸦。
堪嗟。清江东注，画舸西流，指长安日下。愁宴阑、风翻旗尾，潮溅乌纱。今宵正对初弦月，傍水驿、深舣蒹葭。沉恨处，时时自剔灯花。', '晴日山气低笼楚地郊野，暖气回到雁翼上，雁阵从平沙飞起。猛然惊觉春已在眼前，请问它什么时候，曲曲折折地到了山里人家。涂抹香色、浓施粉黛，争着开出妍丽的花。陌头千万缕杨柳丝，渐渐密得可以藏住乌鸦。
堪叹。清江东流，画船西行，指向日下的长安。愁的是宴散时，风吹翻旗尾，潮水溅湿乌纱。今夜正对着初弦月，靠着水边驿舍，把船深深泊在芦苇丛里。在深恨的地方，时时自己剔着灯花。', 'public-domain'),
  ('songci300', 106, '应天长·条风布暖', 'songci-sc-108', '条风布暖，霏雾弄晴，池塘遍满春色。正是夜堂无月，沉沉暗寒食。梁间燕，前社客。似笑我、闭门愁寂。乱花过，隔院芸香，满地狼籍。
长记那回时，邂逅相逢，郊外驻油壁。又见汉宫传烛，飞烟五侯宅。青青草，迷路陌。强载酒、细寻前迹。市桥远，柳下人家，犹自相识。', '东风布暖，薄雾弄晴，池塘里满是春色。正是夜堂无月，沉沉地过了寒食。梁间的燕子，是前社来的旧客，好像在笑我闭门愁寂。落花飞过，隔着院子传来芸香，满地狼藉。
常记得那一回，偶然相逢，在郊外停下车。又见汉宫传烛，飞烟飘到五侯宅。青青春草，把路都迷了。勉强载着酒，细细寻找旧迹。市桥遥远，柳树下的人家，还认得我。', 'public-domain'),
  ('songci300', 107, '还京乐·禁烟近', 'songci-sc-109', '禁烟近，触处浮香秀色相料理。正泥花时候，奈何客里，光阴虚费。望箭波无际。迎风漾日黄云委。任去远，中有万点，相思清泪。
到长淮底。过当时楼下，殷勤为说，春来羁旅况味。堪嗟误约乖期，向天涯、自看桃李。想而今、应恨墨盈笺，愁妆照水。怎得青鸾翼，飞归教见憔悴。', '寒食将近，到处是浮动的香气和秀色互相映衬。正是缠着花的时候，怎奈客居他乡，把光阴白白浪费。望着箭一般的水波无边无际。迎风漾日，黄云低垂。任凭它流去多远，水中有万点，是我相思的清泪。
流到长淮底。经过当年那座楼下，殷勤地替我诉说，春天里羁旅的滋味。可叹误了约期，只能在天涯自己看桃李。想她如今，该是恨字写满信笺，愁妆照着水面。怎么才能有青鸾的翅膀，飞回去让她看见我的憔悴。', 'public-domain'),
  ('songci300', 108, '解连环·怨怀无托', 'songci-sc-110', '怨怀无托，嗟情人断绝，信音辽邈。纵妙手、能解连环，似风散雨收，雾轻云薄。燕子楼空，暗尘锁、一床弦索。想移根换叶，尽是旧时，手种红药。
汀洲渐生杜若。料舟依岸曲，人在天角。谩记得、当日音书，把闲语闲言，待总烧却。水驿春回，望寄我、江南梅萼。拚今生、对花对酒，为伊泪落。', '怨怀无处寄托，可叹情人断绝，音信遥远。纵有妙手能解开连环，也像风散雨收、雾轻云薄。燕子楼已空，暗尘锁住一床琴弦。想那草木移根换叶，都是旧时她亲手种的红芍药。
汀洲上渐渐长出杜若。料想船停泊在弯曲的岸边，人远在天角。白白记得当日的书信，把那些闲言闲语，打算统统烧掉。水边驿站春回，盼望寄我一枝江南梅萼。拼了这辈子，对花对酒，为她落泪。', 'public-domain'),
  ('songci300', 109, '夜游宫·叶下斜阳照水', 'songci-sc-111', '叶下斜阳照水，卷轻浪、沉沉千里。桥上酸风射眸子。立多时，看黄昏，灯火市。
古屋寒窗底，听几片、井桐飞坠。不恋单衾再三起。有谁知，为萧娘，书一纸。', '树下的斜阳照在水面，卷起轻浪，沉沉地流去千里。桥上的冷风刺着眼睛。站了很久，看黄昏里灯火满街市。
回到古屋寒窗下，听井边梧桐叶一片片飞落。不留恋单薄的被子，再三起身。有谁知道，我是为了她，为一纸书信。', 'public-domain'),
  ('songci300', 110, '菩萨蛮·银河宛转三千曲', 'songci-sc-112', '银河宛转三千曲，浴凫飞鹭澄波绿。何处是归舟？夕阳江上楼。
天憎梅浪发，故下封枝雪。深院卷帘看，应怜江上寒。', '银河般的水流弯弯曲曲三千道，野鸭戏水、白鹭飞起，澄波碧绿。哪里是归舟？夕阳照着江上楼。
上天恨梅花开得太恣意，故意下雪封住枝头。她深院里卷帘远看，该会怜惜江上的寒冷。', 'public-domain'),
  ('songci300', 111, '虞美人·疏篱曲径田家小', 'songci-sc-113', '疏篱曲径田家小，云树开清晓。天寒山色有无中。野外一声钟起、送孤蓬。
添衣策马寻亭堠，愁抱惟宜酒。菰蒲睡鸭占陂塘。纵被行人惊散、又成双。', '疏篱曲径，田家很小；云树间天已破晓。天寒，山色若隐若现。野外一声钟响，送走孤舟。
添件衣服骑马去找驿站，满怀愁绪只适合喝酒。茭白蒲草丛中，睡鸭占着池塘；纵然被行人惊散，转眼又成双。', 'public-domain'),
  ('songci300', 112, '点绛唇·辽鹤归来', 'songci-sc-114', '辽鹤归来，故乡多少伤心地。寸书不寄，鱼浪空千里。
凭仗桃根，说与凄凉意。愁无际，旧时衣袂，犹有东门泪。', '辽鹤归来，故乡有多少伤心的旧地。一寸书信也不寄，鱼浪白白千里。
只能依靠桃根，替我诉说凄凉之意。愁绪无边，旧时的衣袖上，还有东门洒下的泪。', 'public-domain'),
  ('songci300', 113, '齐天乐·绿芜凋尽台城路', 'songci-sc-115', '绿芜凋尽台城路，殊乡又逢秋晚。暮雨生寒，鸣蛩劝织，深阁时闻裁剪。云窗静掩，叹重拂罗裀，顿疏花簟。尚有綀囊，露萤清夜照书卷。
荆江留滞最久，故人相望处，离思何限。渭水西风，长安乱叶，空忆诗情宛转。凭高眺远。正玉液新篘，蟹螯初荐。醉倒山翁，但愁斜照敛。', '台城路上绿草凋尽，异乡又逢秋晚。暮雨带来寒意，蟋蟀鸣叫像催人织布，深阁里不时听见裁剪声。云窗静静掩着，可叹重新拂拭罗褥，转眼又疏远了花席。还有粗布囊，装着露水萤火，在清夜照我读书。
在荆江滞留最久，故人相望的地方，离思无穷。渭水西风，长安乱叶，白白回忆那宛转的诗情。登高远眺，正是新酒初滤、蟹螯初上的时候。我要像山简那样醉倒，只愁斜阳收敛了光。', 'public-domain'),
  ('songci300', 114, '琐窗寒·暗柳啼鸦', 'songci-sc-116', '暗柳啼鸦，单衣伫立，小帘朱户。桐花半亩，静锁一庭愁雨。洒空阶、夜阑未休，故人剪烛西窗语。似楚江暝宿，风灯零乱，少年羁旅。
迟暮。嬉游处。正店舍无烟，禁城百五。旗亭唤酒，付与高阳俦侣。想东园、桃李自春，小唇秀靥今在否？到归时、定有残英，待客携尊俎。', '暗柳上乌鸦啼叫，我穿着单衣久立，面前是小帘朱户。半亩桐花，静静地锁住一庭愁雨。雨洒在空台阶上，到夜深还没停，我和故人剪烛在西窗下说话。像在楚江夜宿，风灯零乱，那是少年的羁旅。
已到迟暮之年。回想游乐的地方。正是店舍无烟、京城过寒食的时候。在旗亭唤酒，交给高阳酒徒那样的伙伴。想东园的桃李自在地开着春色，那小巧的嘴唇、秀美的酒窝如今还在吗？等我回去时，一定还有残花，等着我带着酒菜去赏。', 'public-domain'),
  ('songci300', 115, '过秦楼·水浴清蟾', 'songci-sc-117', '水浴清蟾，叶喧凉吹，巷陌马声初断。闲依露井，笑扑流萤，惹破画罗轻扇。人静夜久凭阑，愁不归眠，立残更箭。叹年华一瞬，人今千里，梦沉书远。
空见说、鬓怯琼梳，容销金镜，渐懒趁时匀染。梅风地溽，虹雨苔滋，一架舞红都变。谁信无聊为伊，才减江淹，情伤荀倩。但明河影下，还看稀星数点。', '月光在水里洗过，树叶被凉风吹得喧响，街巷里的马蹄声刚刚断绝。她闲来靠着露井，笑着扑打流萤，把画罗轻扇都弄破了。夜深人静，我倚着栏杆，愁得不想回去睡，站到更漏将尽。可叹年华只是一瞬，人如今相隔千里，梦沉书远。
只听说她两鬓怕用玉梳，容颜在镜中消瘦，渐渐懒得按时梳妆。梅雨时节地上潮湿，虹雨后青苔滋长，一架红花都变了样。谁信我这样无聊是为了她，才思比江淹还减，情深如荀奉倩。只是银河影下，还看着几点稀疏的星。', 'public-domain'),
  ('songci300', 116, '花犯·粉墙低', 'songci-sc-118', '粉墙低，梅花照眼，依然旧风味。露痕轻缀，疑净洗铅华，无限佳丽。去年胜赏曾孤倚，冰盘同燕喜。更可惜、雪中高树，香篝熏素被。
今年对花最匆匆，相逢似有恨，依依愁悴。吟望久，青苔上、旋看飞坠。相将见、脆丸荐酒，人正在、空江烟浪里。但梦想、一枝潇洒，黄昏斜照水。', '粉墙低矮，梅花照眼，依旧是旧日的风味。露痕轻轻缀着，像洗净了脂粉，无限佳丽。去年尽兴赏花时曾独自倚树，与冰盘一同欢宴。更可惜雪中的高树，香笼熏着素被。
今年对花最是匆匆，相逢似乎带着恨意，依依地愁瘦了。吟望久了，青苔上不时看见花瓣飞坠。不久将见梅子脆丸佐酒，而我正在空江烟浪里。只能梦想那一枝潇洒的梅花，在黄昏里斜照水面。', 'public-domain'),
  ('songci300', 117, '大酺·对宿烟收', 'songci-sc-119', '对宿烟收，春禽静，飞雨时鸣高屋。墙头青玉旆，洗铅霜都尽，嫩梢相触。润逼琴丝，寒侵枕障，虫网吹粘帘竹。邮亭无人处，听檐声不断，困眠初熟。奈愁极频惊，梦轻难记，自怜幽独。
行人归意速，最先念、流潦妨车毂。怎奈向、兰成憔悴，卫玠清羸，等闲时、易伤心目。未怪平阳客，双泪落、笛中哀曲。况萧索、青芜国。红糁铺地，门外荆桃如菽。夜游共谁秉烛？', '眼看夜雾收去，春禽静了，飞雨不时敲打高屋。墙头的青竹像玉旗，霜粉都已洗尽，嫩梢互相触碰。潮气逼近琴弦，寒气侵入枕屏，虫网被风吹得粘在帘竹上。邮亭里无人，听檐下雨声不断，困倦中刚睡熟。无奈愁到极处频频惊醒，梦轻难记，自怜幽独。
行人归心急切，最先想到的是积水会阻了车轮。怎奈像我这样憔悴清瘦，寻常时候也容易伤心。难怪平阳客听笛中哀曲而双泪落。何况眼前萧索，一片青芜。红花铺地，门外的樱桃已结成豆大的果子。夜里要与谁秉烛同游？', 'public-domain'),
  ('songci300', 118, '解语花·风销焰蜡', 'songci-sc-120', '风销焰蜡，露浥红莲，花市光相射。桂华流瓦，纤云散、耿耿素娥欲下。衣裳淡雅，看楚女、纤腰一把。箫鼓喧，人影参差，满路飘香麝。
因念都城放夜，望千门如昼，嬉笑游冶。钿车罗帕，相逢处、自有暗尘随马。年光是也，唯只见、旧情衰谢。清漏移，飞盖归来，从舞休歌罢。', '风吹销了烛焰，露水沾湿红莲灯，灯市里光华交射。月光流过屋瓦，纤云散去，明亮的嫦娥仿佛要下来。衣裳淡雅，看那楚地女子，纤腰一握。箫鼓喧腾，人影参差，满路飘着麝香。
于是想起京城放夜的夜晚，望千门灯火如昼，人们嬉笑游乐。钿车罗帕，相逢的地方自有车马扬起的暗尘。年光还是这样，只是旧日的情意衰谢了。漏声移转，我乘车归去，任凭舞歇歌罢。', 'public-domain'),
  ('songci300', 119, '蝶恋花·月皎惊乌栖不定', 'songci-sc-121', '月皎惊乌栖不定，更漏将阑，轳辘牵金井。唤起两眸清炯炯，泪花落枕红绵冷。
执手霜风吹鬓影，去意徊徨，别语愁难听。楼上阑干横斗柄，露寒人远鸡相应。', '月色皎洁，惊得乌鸦栖息不定；更漏将尽，井上辘轳在响。唤她起身，两只眼睛清亮有神，泪花落在枕上，红绵都冷了。
握着手，霜风吹动鬓影；要走又迟疑，离别的话愁得听不下去。楼上栏杆外横着北斗的斗柄，露冷人远，鸡声相互应和。', 'public-domain'),
  ('songci300', 120, '西河·佳丽地', 'songci-sc-122', '佳丽地，南朝盛事谁记？山围故国绕清江，髻鬟对起。怒涛寂寞打孤城，风樯遥度天际。
断崖树，犹倒倚。莫愁艇子曾系。空余旧迹郁苍苍，雾沉半垒。夜深月过女墙来，伤心东望淮水。
酒旗戏鼓甚处市？想依稀、王谢邻里。燕子不知何世，向寻常巷陌人家，相对如说兴亡，斜阳里。', '这佳丽之地，南朝的盛事还有谁记得？青山环绕故都，绿水绕城，两岸山峰像发髻相对。怒涛寂寞地拍打孤城，风帆远远驶过天际。
断崖上的老树，还倒倚着。莫愁女的船曾在这里系过。只留下苍苍的旧迹，浓雾沉埋了半座营垒。夜深时月亮越过女墙，伤心得向东望淮水。
酒旗戏鼓，那是什么地方的集市？想来依稀是王谢两家的邻里。燕子不知是什么朝代，对着寻常巷陌的人家，相对着像在诉说兴亡，在斜阳里。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 121, '瑞鹤仙·悄郊原带郭', 'songci-sc-123', '悄郊原带郭，行路永、客去车尘漠漠。斜阳映山落，敛余红、犹恋孤城阑角。凌波步弱，过短亭、何用素约。有流莺劝我，重解绣鞍，缓引春酌。
不记归时早暮，上马谁扶，醒眠朱阁。惊飙动幕，扶残醉，绕红药。叹西园、已是花深无地，东风何事又恶？任流光过却，犹喜洞天自乐。', '郊野连着城郭，一片静悄悄；路很长，客去车尘漠漠。斜阳映着山峦落下，收敛余红，还恋着孤城栏杆的一角。她步履轻弱，经过短亭，何必事先约定。有流莺劝我，重新解下绣鞍，慢慢斟春酒。
不记得回来是早是晚，上马时是谁扶的，酒醒时已睡在朱阁。狂风吹动帷幕，我扶着残醉，绕着红芍药走。可叹西园已是花深得没有空地，东风为什么还要作恶？任流光过去吧，还高兴能在这洞天里自乐。', 'public-domain'),
  ('songci300', 122, '浪淘沙慢·晓阴重', 'songci-sc-124', '晓阴重，霜凋岸草，雾隐城堞。南陌脂车待发，东门帐饮乍阕。正拂面、垂杨堪揽结，掩红泪、玉手亲折。念汉浦离鸿去何许？经时信音绝。
情切，望中地远天阔。向露冷风清无人处，耿耿寒漏咽。嗟万事难忘，唯是轻别。翠尊未竭，凭断云、留取西楼残月。
罗带光销纹衾叠。连环解、旧香顿歇。怨歌永、琼壶敲尽缺。恨春去、不与人期，弄夜色，空余满地梨花雪。', '清晨阴云浓重，霜打凋了岸边的草，雾遮住城头。南边路上，上了油的车正待出发；东门外饯行的帐幕刚散。拂面的垂杨正好可以揽住，她掩着红泪，用玉手亲自折柳相赠。想那汉浦的离雁去了哪里？过了这么久音信断绝。
情意恳切，望中地远天阔。在露冷风清、无人之处，寒漏耿耿如咽。可叹万事都能忘，只有轻易的离别难忘。翠杯还没喝干，就凭断云留住西楼残月吧。
罗带的光泽消尽，花纹被褥叠起。连环解开，旧日的香气顿时歇了。怨歌长唱，把玉壶敲得尽是缺口。恨春天离去不与人约定，只弄这夜色，白白留下满地梨花如雪。', 'public-domain'),
  ('songci300', 123, '拜星月慢·夜色催更', 'songci-sc-125', '夜色催更，清尘收露，小曲幽坊月暗。竹槛灯窗，识秋娘庭院。笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。水盼兰情，总平生稀见。
画图中、旧识春风面。谁知道、自到瑶台畔。眷恋雨润云温，苦惊风吹散。念荒寒、寄宿无人馆。重门闭、败壁秋虫叹。怎奈向、一缕相思，隔溪山不断。', '夜色催着更鼓，清尘收去露水，小巷深处月色暗淡。竹栏灯窗下，认得是秋娘的庭院。笑着相逢，仿佛琼枝玉树相依，暖日明霞光灿。水样的眼波、兰样的情意，一生中难得见到。
像在画里见过那春风般的面容。谁知道，自从到了这瑶台畔，贪恋那雨润云温，却被惊风吹散。想我如今在荒寒的无人馆舍寄宿。重门紧闭，破壁下秋虫叹息。怎奈那一缕相思，隔着溪山也断不了。', 'public-domain'),
  ('songci300', 124, '尉迟杯·隋堤路', 'songci-sc-126', '隋堤路，渐日晚、密霭生深树。阴阴淡月笼沙，还宿河桥深处。无情画舸，都不管、烟波隔前浦。等行人、醉拥重衾，载将离恨归去。
因思旧客京华，长偎傍疏林，小槛欢聚。冶叶倡条俱相识，仍惯见、珠歌翠舞。如今向、渔村水驿，夜如岁、焚香独自语。有何人、念我无憀，梦魂凝想鸳侣。', '隋堤路上，天色渐晚，浓雾从深树里生出。淡淡的月色阴暗地笼着沙岸，我还在河桥深处投宿。无情的画船，全不管烟波把前浦隔断。等行人醉拥厚被，就载着离恨归去。
于是想起当年客居京城，常常偎傍疏林，在小栏杆边欢聚。那些冶叶倡条都相识，也惯见珠歌翠舞。如今却在渔村水驿，夜长得像一年，焚着香独自说话。有谁念我这般无聊，梦魂凝想着鸳鸯伴侣。', 'public-domain'),
  ('songci300', 125, '夜飞鹊·河桥送人处', 'songci-sc-339', '河桥送人处，凉夜何其。斜月远堕余辉。铜盘烛泪已流尽，霏霏凉露沾衣。相将散离会，探风前津鼓，树杪参旗。花骢会意，纵扬鞭、亦自行迟。
迢递路回清野，人语渐无闻，空带愁归。何意重经前地，遗钿不见，斜径都迷。兔葵燕麦，向残阳、影与人齐。但徘徊班草，欷歔酹酒，极望天西。', '河桥上送别的地方，清凉的夜到了什么时辰？斜月远远落下，只剩一点余辉。铜盘里的烛泪已经流尽，纷纷凉露沾湿了衣裳。临别的宴席就要散了，听风里渡口的鼓声，看树梢上的参旗星。花马似乎懂得我的心意，即使扬鞭，也走得很慢。
回去的路曲折，经过空旷的原野，送行人的话渐不可闻，只带着愁绪归来。谁料又重经旧地，她遗落的钿饰已找不到，斜路都辨不清了。兔葵燕麦长得很高，在残阳里，影子与人齐高。我只得在草地上徘徊，叹息着洒酒祭奠，极力西望天边。', 'public-domain'),
  ('songci300', 126, '玉楼春·桃溪不作从容住', 'songci-sc-340', '桃溪不作从容住，秋藕绝来无续处。当时相候赤阑桥，今日独寻黄叶路。
烟中列岫青无数，雁背夕阳红欲暮。人如风后入江云，情似雨余黏地絮。', '在桃溪没有能从容地留住，秋藕折断后再没有接续的地方。当年在赤阑桥上相候，如今独自来寻这条黄叶满地的路。
烟里无数青山排列，雁背上驮着夕阳，红得快要入暮。人像被风吹入江面的云，情像雨后黏在地上的柳絮。', 'public-domain'),
  ('songci300', 127, '石州慢·寒水依痕', 'songci-sc-139', '寒水依痕，春意渐回，沙际烟阔。溪梅晴照生香，冷蕊数枝争发。天涯旧恨，试看几许消魂？长亭门外山重叠。不尽眼中青，是愁来时节。
情切。画楼深闭，想见东风，暗销肌雪。辜负枕前云雨，尊前花月。心期切处，更有多少凄凉，殷勤留与归时说。到得却相逢，恰经年离别。', '寒水沿着旧痕，春意渐渐回来，沙滩边烟雾空阔。溪边梅树在晴日照耀下生出香气，几枝冷蕊争着开放。天涯旧恨，试看有多少消魂？长亭门外山峦重叠。眼中无尽的青色，正是愁来的时候。
情意恳切。画楼深闭，想那东风，暗暗消损她雪白的肌肤。辜负了枕前的云雨、杯前的花月。心中盼望最切的地方，还有多少凄凉，殷勤地留着等归来时说。等真能相逢，又恰恰是经年离别之后。', 'public-domain'),
  ('songci300', 128, '贺新郎·梦绕神州路', 'songci-sc-141', '梦绕神州路。怅秋风、连营画角，故宫离黍。底事昆仑倾砥柱，九地黄流乱注？聚万落、千村狐兔。天意从来高难问，况人情、老易悲如许。更南浦，送君去。
凉生岸柳催残暑。耿斜河、疏星淡月，断云微度。万里江山知何处？回首对床夜语。雁不到、书成谁与？目尽青天怀今古，肯儿曹、恩怨相尔汝！举大白，听《金缕》。', '梦里绕着中原地带的道路。惆怅秋风中，连营的号角声，故都长满禾黍。为什么昆仑的砥柱崩塌，九州的黄河水乱流？万落千村聚着狐兔。天意从来高远难以询问，何况人一老就容易这样悲伤。又在这南浦，送你离去。
岸边柳树生出凉意，催促残暑退去。银河明净，疏星淡月，断云缓缓飘过。万里江山，人如今在哪里？回想当年对床夜话。大雁飞不到，信写好了交给谁？望尽青天，心怀今古，岂肯像小儿女那样计较恩怨！举起大杯，听我唱这首《金缕曲》。', 'public-domain'),
  ('songci300', 129, '虞美人·落花已作风前舞', 'songci-sc-142', '落花已作风前舞，又送黄昏雨。晓来庭院半残红，惟有游丝千丈、罥晴空。
殷勤花下同携手，更尽杯中酒。美人不用敛歌眉，我亦多情、无奈酒阑时。', '落花已在风前飞舞，又送走黄昏的雨。清晨庭院里一半是残花，只有千丈游丝挂在晴空。
我们殷勤地在花下携手，把杯中酒喝干。美人不必皱起歌眉，我也是多情的人，只是无奈酒阑人散的时候。', 'public-domain'),
  ('songci300', 130, '点绛唇·新月娟娟', 'songci-sc-143', '新月娟娟，夜寒江静山衔斗。起来搔首，梅影横窗瘦。
好个霜天，闲却传杯手。君知否？乱鸦啼后，归兴浓于酒。', '新月美好，夜寒江静，山峰衔着北斗。起身挠头，梅影横在窗上，清瘦。
好一个霜天，却闲下了传杯的手。你知道吗？乱鸦啼过之后，归乡的兴致比酒还浓。', 'public-domain'),
  ('songci300', 131, '喜迁莺·晓光催角', 'songci-sc-144', '晓光催角。听宿鸟未惊，邻鸡先觉。迤逦烟村，马嘶人起，残月尚穿林薄。泪痕带霜微凝，酒力冲寒犹弱。叹倦客、悄不禁重染，风尘京洛。
追念人别后，心事万重，难觅孤鸿托。翠幌娇深，曲屏香暖，争念岁华飘泊。怨月恨花烦恼，不是不曾经著。者情味、望一成消减，新来还恶。', '晨光催着号角。听宿鸟还没惊动，邻家的鸡先醒了。一路烟雾中的村庄，马嘶人起，残月还挂在林梢。泪痕带着霜微微凝结，酒力挡不住寒气还嫌单薄。可叹倦游的人，悄悄受不住再染上京洛的风尘。
追想别后，心事万重，难以找到孤雁传递。翠帘娇深，曲屏香暖，怎么想得到年华在漂泊中流逝。怨月恨花的烦恼，不是没有经历过。这种情味，指望它能消减一分，近来反而更糟。', 'public-domain'),
  ('songci300', 132, '高阳台·频听银签', 'songci-sc-145', '频听银签，重燃绛蜡，年华衮衮惊心。饯旧迎新，能消几刻光阴？老来可惯通宵饮？待不眠、还怕寒侵。掩清尊，多谢梅花，伴我微吟。
邻娃已试春妆了，更蜂腰簇翠，燕股横金。勾引东风，也知芳思难禁。朱颜那有年年好，逞艳游、赢取如今。恣登临，残雪楼台，迟日园林。', '频频听着更签，重新点上红烛，年华滚滚令人心惊。送旧迎新，能消磨几刻光阴？老了哪还习惯通宵饮酒？想不睡，又怕寒气侵入。放下酒杯，多谢梅花，陪我低声吟咏。
邻家女孩已试过春妆，蜂腰般的发饰簇着翠，燕尾般的金钗横着。她勾引东风，也知道芳心难禁。红颜哪能年年都好，趁艳游赢得如今吧。尽情登临，看残雪的楼台、迟日的园林。', 'public-domain'),
  ('songci300', 133, '汉宫春·潇洒江梅', 'songci-sc-146', '潇洒江梅，向竹梢疏处，横两三枝。东君也不爱惜，雪压霜欺。无情燕子，怕春寒、轻失花期。却是有、年年塞雁，归来曾见开时。
清浅小溪如练，问玉堂何似，茅舍疏篱？伤心故人去后，冷落新诗。微云淡月，对江天、分付他谁？空自忆，清香未减，风流不在人知。', '江边梅花潇洒，在竹梢稀疏处横出两三枝。春神也不爱惜，任它被雪压霜欺。无情的燕子怕春寒，轻易错过了花期。倒是有年年归来的塞雁，见过它开放的时候。
清浅的小溪像白练，问那玉堂比茅舍疏篱如何？伤心的是故人离去后，新诗也冷落了。微云淡月，面对江天，又能交给谁？只能空自回忆；清香未减，风流本不在别人知不知道。', 'public-domain'),
  ('songci300', 134, '临江仙·忆昔午桥桥上饮', 'poems-cz9-23', '忆昔午桥桥上饮，坐中多是豪英。
长沟流月去无声。杏花疏影里，吹笛到天明。
二十余年如一梦，此身虽在堪惊。
闲登小阁看新晴。古今多少事，渔唱起三更。', '回忆当年在午桥桥上饮酒，在座的大多是英雄豪杰。长长的水沟里月影流动，悄无声息。在杏花稀疏的影子里，我们吹笛吹到天亮。二十多年过去了，就像一场梦，此身虽然还在，回想起来却令人心惊。如今闲来登上小阁，看看新晴的景色。古往今来多少兴亡之事，都化作三更时渔人的歌唱。', 'academic'),
  ('songci300', 135, '苏武慢·雁落平沙', 'songci-sc-148', '雁落平沙，烟笼寒水，古垒鸣笳声断。青山隐隐，败叶萧萧，天际暝鸦零乱。楼上黄昏，片帆千里归程，年华将晚。望碧云空暮，佳人何处？梦魂俱远。
忆旧游、邃馆朱扉，小园香径，尚想桃花人面。书盈锦轴，恨满金徽，难写寸心幽怨。两地离愁，一尊芳酒，凄凉危阑倚遍。尽迟留、凭仗西风，吹干泪眼。', '大雁落在平沙，烟雾笼着寒水，古垒的胡笳声断绝。青山隐约，败叶萧萧，天边暮鸦零乱。楼上已是黄昏，一片孤帆千里归程，年华将晚。望碧云笼着空暮，佳人在哪里？梦魂都远了。
回忆旧游，深馆朱门，小园香径，还记得桃花般的面容。书信写满锦轴，怨恨充满琴徽，也难写尽心中幽怨。两地离愁，一尊美酒，凄凉地把危栏倚遍。久久停留，全靠西风，吹干泪眼。', 'public-domain'),
  ('songci300', 136, '柳梢青·数声鶗鴂', 'songci-sc-149', '数声鶗鴂，可怜又是，春归时节。满院东风，海棠铺绣，梨花飘雪。
丁香露泣残枝，算未比、愁肠寸结。自是休文，多情多感，不干风月。', '几声杜鹃啼叫，可怜又是春归的时节。满院东风，海棠铺成锦绣，梨花飘如雪。
丁香在残枝上泣露，算来也比不上我愁肠寸结。本是我像沈约那样多情多感，与风月无关。', 'public-domain'),
  ('songci300', 137, '鹧鸪天·一点残红欲尽时', 'songci-sc-150', '一点残红欲尽时，乍凉秋气满屏帏。梧桐叶上三更雨，叶叶声声是别离。
调宝瑟，拨金猊。那时同唱鹧鸪词。如今风雨西楼夜，不听清歌也泪垂。', '一点残灯将尽的时候，初凉的秋气充满屏帏。梧桐叶上三更的雨，每一叶每一声都是别离。
那时调宝瑟，拨香炉，一同唱《鹧鸪词》。如今风雨西楼之夜，不听清歌也落泪。', 'public-domain'),
  ('songci300', 138, '踏莎行·情似游丝', 'songci-sc-151', '情似游丝，人如飞絮。泪珠阁定空相觑。一溪烟柳万丝垂，无因系得兰舟住。
雁过斜阳，草迷烟渚。如今已是愁无数。明朝且做莫思量，如何过得今宵去？', '情像游丝，人如飞絮。泪珠含住，只是空对着看。一溪烟柳垂下万丝，却没有办法系住兰舟。
大雁飞过斜阳，青草迷住烟渚。如今已是愁无数。明天的事暂且不去想，可今夜怎么捱得过去？', 'public-domain'),
  ('songci300', 139, '帝台春·芳草碧色', 'songci-sc-152', '芳草碧色，萋萋遍南陌。暖絮乱红，也知人、春愁无力。忆得盈盈拾翠侣，共携赏、凤城寒食。到今来，海角逢春，天涯为客。
愁旋释，还似织；泪暗拭，又偷滴。谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。拚则而今已拚了，忘则怎生便忘得。又还问鳞鸿，试重寻消息。', '芳草碧绿，茂盛地长满南边小路。暖絮乱红，也知道人春愁无力。记得那盈盈的拾翠伴侣，一同到京城赏寒食。到如今，在海角逢春，在天涯作客。
愁刚解开，又像织起来；泪暗暗擦去，又偷偷滴下。白白地伫立，把危栏倚遍，直到黄昏，也只是暮云凝着碧色。舍弃既然已经舍弃了，要忘又怎么忘得掉。又去问鱼雁，试着重新打听消息。', 'public-domain'),
  ('songci300', 140, '忆王孙·萋萋芳草忆王孙', 'songci-sc-153', '萋萋芳草忆王孙，柳外楼高空断魂。杜宇声声不忍闻。欲黄昏，雨打梨花深闭门。', '芳草萋萋，思念远行的人；柳外楼高，白白地令人断魂。杜鹃声声，不忍听闻。将近黄昏，雨打着梨花，深深把门关上。', 'public-domain'),
  ('songci300', 141, '三台·见梨花初带夜月', 'songci-sc-154', '见梨花初带夜月，海棠半含朝雨。内苑春、不禁过青门，御沟涨、潜通南浦。东风静、细柳垂金缕。望凤阙、非烟非雾。好时代、朝野多欢，遍九陌、太平箫鼓。
乍莺儿百啭断续，燕子飞来飞去。近绿水、台榭映秋千，斗草聚、双双游女。饧香更、酒冷踏青路。会暗识、夭桃朱户。向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。
正轻寒轻暖漏永，半阴半晴云暮。禁火天、已是试新妆，岁华到、三分佳处。清明看、汉蜡传宫炬。烟散后、云归何处？敛兵卫、阊阖门开，住传宣、又还休务。', '看梨花初带上夜月，海棠半含着朝雨。宫苑的春色禁不住越过宫门，御沟水涨暗暗通到南浦。东风静，细柳垂下金丝。望皇宫，非烟非雾。好时代，朝野多欢，满城都是太平的箫鼓。
黄莺骤然百般啼啭、断断续续，燕子飞来飞去。绿水边台榭映着秋千，斗草的人聚在一处，是一双双游女。饧糖香、酒已冷，就在踏青路上。在夭桃朱门处暗暗相识。傍晚时宝马雕鞍，醉襟上沾着乱花飞絮。
正是轻寒轻暖、漏声悠长，半阴半晴、云色向暮。禁火时节，已经试过新妆，一年的好景到了三分佳处。清明时看宫中传烛，烟散之后云归何处？收起兵卫，宫门大开，停止传宣，又要休沐。', 'public-domain'),
  ('songci300', 142, '二郎神·闷来弹鹊', 'songci-sc-155', '闷来弹鹊，又搅碎、一帘花影。漫试著春衫，还思纤手，熏彻金猊烬冷。动是愁端如何向？但怪得、新来多病。嗟旧日沈腰，如今潘鬓，怎堪临镜？
重省。别时泪湿，罗衣犹凝。料为我厌厌，日高慵起，长托春酲未醒。雁足不来，马蹄难驻，门掩一庭芳景。空伫立，尽日阑干倚遍，昼长人静。', '闷来弹打喜鹊，又搅碎了一帘花影。随意试穿春衫，又想起那纤纤素手，香炉里的火已冷。动不动就是愁的由头，怎么办？只怪近来多病。可叹旧日像沈约那样瘦，如今又添潘岳的白发，怎么受得住照镜？
重新回想。分别时泪湿的罗衣，至今还有痕迹。料她为我恹恹无绪，日头高了还懒得起床，总推说春酒未醒。雁足不来，马蹄难留，门掩着一庭芳景。白白伫立，整日把栏杆倚遍，昼长人静。', 'public-domain'),
  ('songci300', 143, '江神子慢·玉台挂秋月', 'songci-sc-156', '玉台挂秋月，铅素浅、梅花傅香雪。冰姿洁。金莲衬、小小凌波罗袜。雨初歇。楼外孤鸿声渐远，远山外、行人音信绝。此恨对语犹难，那堪更寄书说。
教人红消翠减，觉衣宽金缕，都为轻别。太情切。消魂处、画角黄昏时节。声呜咽。落尽庭花春去也，银蟾迥、无情圆又缺。恨伊不似余香，惹鸳鸯结。', '玉台上挂着秋月，她脂粉淡薄，像梅花敷着香雪。冰姿洁净。金莲鞋衬着小小的凌波罗袜。雨刚停。楼外孤雁声渐渐远去，远山之外，行人的音信断绝。这份恨面对面说都难，哪堪再写信去说。
叫人红消翠减，觉得金缕衣都宽了，都因为轻易的离别。太情切。消魂的地方，是黄昏画角响起时。声音呜咽。庭花落尽，春天去了；明月高远，无情地圆了又缺。恨他不像我身上余香，能结成鸳鸯。', 'public-domain'),
  ('songci300', 144, '蓦山溪·洗妆真态', 'songci-sc-157', '洗妆真态，不作铅华御。竹外一枝斜，想佳人、天寒日暮。黄昏院落，无处著清香，风细细，雪垂垂，何况江头路。
月边疏影，梦到消魂处。结子欲黄时，又须作、廉纤小雨。孤芳一世，供断有情愁，消瘦损，东阳也，试问花知否？', '洗去妆饰的本真态度，不用脂粉来修饰。竹外一枝斜出，想那佳人，在天寒日暮的时候。黄昏的院落，清香无处安放；风细细，雪垂垂，何况江头的路上。
月边的疏影，梦到消魂的地方。等结子将要黄时，又该下起纤细的小雨。孤芳一世，供尽了有情人的愁，人瘦损如沈约，试问花知道吗？', 'public-domain'),
  ('songci300', 145, '贺新郎·篆缕销金鼎', 'songci-sc-158', '篆缕销金鼎。醉沉沉、庭阴转午，画堂人静。芳草王孙知何处？惟有杨花糁径。渐玉枕、腾腾春醒。帘外残红春已透，镇无聊、殢酒厌厌病。云鬓乱，未忺整。
江南旧事休重省。遍天涯、寻消问息，断鸿难倩。月满西楼凭阑久，依旧归期未定。又只恐、瓶沉金井。嘶骑不来银烛暗，枉教人、立尽梧桐影。谁伴我，对鸾镜。', '香炉里的篆烟消散。醉意沉沉，庭中树荫转过午后，画堂里人声寂静。芳草萋萋，那远行的人在哪里？只有杨花散在小径上。玉枕上渐渐从春睡中醒来。帘外残红，春天已过；整日无聊，被酒困着，恹恹成病。云鬓散乱，也懒得整理。
江南的旧事不要再回想。走遍天涯寻消息，孤雁也难以托付。月满西楼，我倚栏很久，归期依旧未定。又只怕像瓶沉金井，音信全无。嘶鸣的马不来，银烛已暗，白白教人站到梧桐影尽。谁来陪我，面对鸾镜？', 'public-domain'),
  ('songci300', 146, '烛影摇红·霭霭春空', 'songci-sc-159', '霭霭春空，画楼森耸凌云渚。紫薇登览最关情，绝妙夸能赋。惆怅相思迟暮，记当日、朱阑共语。塞鸿难问，岸柳何穷，别愁纷絮。
催促年光，旧来流水知何处？断肠何必更残阳，极目伤平楚。晚霁波声带雨。悄无人、舟横野渡。数峰江上，芳草天涯，参差烟树。', '春空云气弥漫，画楼高耸直入云中的洲渚。登楼览景最牵动感情，前人绝妙的赋作值得称夸。惆怅相思已到迟暮，记得当日同在朱栏边说话。塞雁难问，岸柳无穷，别愁像纷乱的柳絮。
年光被催促，旧日的流水如今在哪里？断肠何必再对着残阳，极目望去，平野令人伤心。晚晴后波声带着雨意。悄无人影，孤舟横在野渡。江上几座山峰，天涯一片芳草，参差的烟树。', 'public-domain'),
  ('songci300', 147, '薄幸·青楼春晚', 'songci-sc-160', '青楼春晚，昼寂寂、梳匀又懒。乍听得、鸦啼莺弄，惹起新愁无限。记年时、偷掷春心，花间隔雾遥相见。便角枕题诗，宝钗贳酒，共醉青苔深院。
怎忘得、回廊下，携手处、花明月满。如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。却谁拘管？尽无言、闲品秦筝，泪满参差雁。腰支渐小，心与杨花共远。', '青楼里春天已晚，白天寂静，梳好妆又懒懒的。忽然听见乌鸦啼、黄莺叫，惹起无限新愁。记得那年，偷偷掷出春心，隔着花丛的雾远远相见。于是角枕上题诗，用宝钗换酒，一同醉在青苔深院。
怎么忘得掉回廊下携手的地方，那时花明月满。如今只有暮雨，蜂愁蝶恨，小窗闲对着舒展的芭蕉。又有谁来管我？只是默默无言地闲弹秦筝，泪落满参差的雁柱。腰肢渐细，心与杨花一同远去。', 'public-domain'),
  ('songci300', 148, '透碧宵·舣兰舟', 'songci-sc-161', '舣兰舟，十分端然俯清流。玉人娇困，宝钗慵整，绣阁还羞。轻寒轻暖，雨膏烟腻，画舸频游。正春浓、花艳香稠。渐分飞双燕，愁红敛翠，恨别悠悠。
念酒徒云散，花时孤负，往事怎追游？断云低、孤雁远，空目断、碧云楼。自怜春晚，情怀不似，旧日风流。但赢得多愁，多病多痛，双鬓先秋。', '兰舟靠岸，十分端正地俯看清流。玉人娇困，宝钗慵懒地不去整理，绣阁里还有些羞意。天气轻寒轻暖，雨润烟浓，画船频频出游。正是春浓花艳香稠的时候。渐渐双燕分飞，愁红敛翠，恨那别离悠悠。
想酒友如云散，花期被辜负，往事怎么去追寻？断云低垂，孤雁远去，白白望断碧云楼。自怜春天已晚，情怀不似旧日的风流。只赢得许多愁，多病多痛，双鬓先白了。', 'public-domain'),
  ('songci300', 149, '南浦·风悲画角', 'songci-sc-162', '风悲画角，听单于、三弄落谯门。投宿骎骎征骑，飞雪满孤村。酒市渐阑灯火，正敲窗、乱叶舞纷纷。送数声惊雁，乍离烟水，嘹唳度寒云。
好在半胧淡月，到如今、无处不消魂。故国梅花归梦，愁损绿罗裙。为问暗香闲艳，也相思、万点付啼痕。算翠屏应是，两眉余恨倚黄昏。', '风中画角悲鸣，听《单于》三弄从谯门落下。投宿的征骑匆匆赶路，飞雪落满孤村。酒市的灯火渐渐阑珊，正是乱叶敲窗、纷纷飞舞的时候。送走几声惊雁，它们刚离开烟水，嘹唳着飞过寒云。
半朦胧的淡月还好，到如今无处不令人消魂。故国的梅花入归梦，愁坏了她绿罗裙。试问那暗香闲艳，是否也在相思，万点落成啼痕。算来翠屏里的人应是两眉含着余恨，倚到黄昏。', 'public-domain'),
  ('songci300', 150, '满江红·怒发冲冠', 'songci-sc-288', '怒发冲冠，凭栏处、潇潇雨歇。抬望眼、仰天长啸，壮怀激烈。三十功名尘与土，八千里路云和月。莫等闲、白了少年头，空悲切。
靖康耻，犹未雪；臣子恨，何时灭。驾长车、踏破贺兰山缺。壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头、收拾旧山河，朝天阙。', '愤怒得头发直竖顶起帽子，独自凭栏，一场急雨刚刚停歇。抬起眼望向远方，仰天长啸，满腔报国之心激烈涌动。三十年的功名如同尘土，八千里的征程唯有云月相伴。不要虚度年华，等到少年白头，徒然悲伤。
靖康年间的耻辱，还未洗雪；做臣子的遗恨，何时才能消除。驾着战车，踏破贺兰山的隘口。壮志满怀，饿了就吃敌人的肉，谈笑间渴了就饮匈奴的血。等到重新收复旧日山河，再向朝廷报捷。', 'public-domain'),
  ('songci300', 151, '烛影摇红·双阙中天', 'songci-sc-164', '双阙中天，凤楼十二春寒浅。去年元夜奉宸游，曾侍瑶池宴。玉殿珠帘尽卷。拥群仙、蓬壶阆苑。五云深处，万烛光中，揭天丝管。
驰隙流年，恍如一瞬星霜换。今宵谁念泣孤臣，回首长安远。可是尘缘未断？谩惆怅、华胥梦短。满怀幽恨，数点寒灯，几声归雁。', '双阙耸立天际，十二座凤楼间春寒尚浅。去年元宵夜随驾出游，曾侍瑶池之宴。玉殿上珠帘尽卷，拥着群仙，如在蓬壶阆苑。五色云深处，万烛光中，丝管之声震天。
流年如白驹过隙，恍惚一瞬星霜就换了。今夜谁念我这泣泪的孤臣？回首长安已远。难道是尘缘未断？白白惆怅，华胥梦太短。满怀幽恨，几点寒灯，几声归雁。', 'public-domain'),
  ('songci300', 152, '水龙吟·夜来风雨匆匆', 'songci-sc-165', '夜来风雨匆匆，故园定是花无几。愁多怨极，等闲孤负，一年芳意。柳困桃慵，杏青梅小，对人容易。算好春长在，好花长见，原只是、人憔悴。
回首池南旧事，恨星星、不堪重记。如今但有，看花老眼，伤时清泪。不怕逢花瘦，只愁怕、老来风味。待繁红乱处，留云借月，也须拚醉。', '夜里风雨匆匆，故园的花一定不剩多少了。愁多怨极，轻易辜负了一年芳意。柳困桃惰，杏青梅小，对人都不在意。算来好春长在，好花常开，只是人憔悴了。
回望池南旧事，恨白发星星，不堪再记。如今只有看花的老眼、伤时的清泪。不怕见花憔悴，只愁老来的心境。等到繁红纷乱的时候，留住云借来月，也要拼着一醉。', 'public-domain'),
  ('songci300', 153, '六州歌头·长淮望断', 'songci-sc-166', '长淮望断，关塞莽然平。征尘暗，霜风劲，悄边声。黯销凝。追想当年事，殆天数，非人力；洙泗上，弦歌地，亦膻腥。隔水毡乡，落日牛羊下，区脱纵横。看名王宵猎，骑火一川明。笳鼓悲鸣，遣人惊。
念腰间箭，匣中剑，空埃蠹，竟何成！时易失，心徒壮，岁将零。渺神京。干羽方怀远，静烽燧，且休兵。冠盖使，纷驰骛，若为情！闻道中原遗老，常南望、翠葆霓旌。使行人到此，忠愤气填膺，有泪如倾。', '望断淮河，关塞一片荒草平铺。征尘暗淡，霜风强劲，边地悄无声音。黯然神伤。追想当年的事，大概是天数，不是人力；洙水泗水之上，本是弦歌礼乐之地，如今也沾了膻腥。隔水就是毡帐之乡，落日里牛羊下来，敌人的哨所纵横。看那敌军首领夜间打猎，骑兵的火把照亮一川。胡笳战鼓悲鸣，令人心惊。
想腰间的箭、匣中的剑，白白地积尘生蠹，终究成了什么！时机容易错过，心虽壮，年岁将尽。京城渺远。朝廷正以礼乐怀柔远人，熄灭烽火，暂且休兵。使者车马纷纷奔驰，叫人何以堪受！听说中原的遗民，常常向南盼望皇帝的仪仗。让行人来到这里，忠愤之气填满胸膛，泪如雨下。', 'public-domain'),
  ('songci300', 154, '剑器近·夜来雨', 'songci-sc-170', '夜来雨，赖倩得、东风吹住。海棠正妖娆处，且留取。悄庭户，试细听、莺啼燕语。分明共人愁绪，怕春去。
佳树，翠阴初转午。重帘未卷，乍睡起、寂寞看风絮。偷弹清泪寄烟波，见江头故人，为言憔悴如许。彩笺无数，去却寒暄，到了浑无定据。断肠落日千山暮。', '夜里的雨，幸得东风把它吹住。海棠正妖娆的时候，且留住它。庭院悄悄，试着细听莺啼燕语。分明和人一样有愁绪，怕春天归去。
美好的树，绿荫初转过午后。重帘未卷，刚睡起，寂寞地看风中的柳絮。偷偷弹去清泪寄给烟波，若见到江头的故人，替我说我憔悴成这样。彩笺无数，除去寒暄，到头来全无准信。断肠时落日下千山已暮。', 'public-domain'),
  ('songci300', 155, '安公子·弱柳千丝缕', 'songci-sc-171', '弱柳千丝缕，嫩黄匀遍鸦啼处。寒入罗衣春尚浅，过一番风雨。问燕子来时，绿水桥边路，曾画楼、见个人人否？料静掩云窗，尘满哀弦危柱。
庾信愁如许，为谁都著眉端聚？独立东风弹泪眼，寄烟波东去。念永昼春闲，人倦如何度？闲傍枕、百啭黄鹂语。唤觉来厌厌，残照依然花坞。', '柔弱的柳丝千缕，嫩黄匀在乌鸦啼叫的地方。寒气侵入罗衣，春意还浅，又经过一番风雨。问燕子来时，绿水桥边的路上，可曾在画楼见过那个人？料想她静静掩着云窗，灰尘落满琴柱。
庾信那样的愁有多少，为了谁聚在眉端？独自站在东风里弹去泪眼，托烟波向东带去。想那长长的春日闲人倦，怎么捱过？闲靠着枕头，听黄鹂百啭。被唤醒后恹恹无绪，残照依然照着花坞。', 'public-domain'),
  ('songci300', 156, '瑞鹤仙·郊原初过雨', 'songci-sc-169', '郊原初过雨，见败叶零乱，风定犹舞。斜阳挂深树，映浓愁浅黛，遥山眉妩。来时旧路，尚岩花、娇黄半吐。到而今，唯有溪边流水，见人如故。
无语，邮亭深静，下马还寻，旧曾题处。无聊倦旅，伤离恨，最愁苦。纵收香藏镜，他年重到，人面桃花在否？念沉沉、小阁幽窗，有时梦去。', '郊野刚下过雨，见败叶零乱，风停了还在飞舞。斜阳挂在深树间，映出浓愁般的浅黛，远山像美人的眉。来时的旧路，还有岩上的花娇黄半开。到如今，只有溪边的流水，见了人还如故。
无语。邮亭深静，下马再去寻找旧日题字的地方。无聊的倦旅，伤离恨，最是愁苦。纵然收起香、藏起镜，他年重来时，那人面桃花还在吗？想那沉沉的小阁幽窗，有时在梦里去。', 'public-domain'),
  ('songci300', 157, '瑞鹤仙·脸霞红印枕', 'songci-sc-172', '脸霞红印枕，睡觉来、冠儿还是不整。屏间麝煤冷，但眉峰压翠，泪珠弹粉。堂深昼永，燕交飞、风帘露井。恨无人说与，相思近日，带围宽尽。
重省，残灯朱幌，淡月纱窗，那时风景。阳台路迥，云雨梦，便无准。待归来，先指花梢教看，却把心期细问。问因循过了青春，怎生意稳？', '脸上的红霞印在枕上，睡醒来，冠儿还是不整。屏风间的香墨冷了，只见眉峰压着翠色，泪珠冲下脂粉。堂深昼长，燕子交错飞过风帘露井。恨无人可以诉说：近日相思，衣带都宽尽了。
重新回想，残灯朱帐、淡月纱窗，那时的风景。阳台的路遥远，云雨之梦便无准信。等他回来，先指着花梢让他看，再把心中期望细细追问。问他为什么因循蹉跎过了青春，怎么就能心安？', 'public-domain'),
  ('songci300', 158, '卜算子·驿外断桥边', 'poems-cz8-29', '驿外断桥边，寂寞开无主。
已是黄昏独自愁，更著风和雨。
无意苦争春，一任群芳妒。
零落成泥碾作尘，只有香如故。', '驿站之外的断桥边，梅花寂寞地开放，无人过问。已是黄昏时分，她独自忧愁，又遭到风雨的摧残。她本来无意苦苦争夺春光，任凭百花去嫉妒。即使凋零飘落被碾作尘土，只有那清香依旧如故。', 'school'),
  ('songci300', 159, '钗头凤·红酥手', 'songci-sc-174', '红酥手，黄縢酒，满城春色宫墙柳。东风恶，欢情薄。一怀愁绪，几年离索。错、错、错。
春如旧，人空瘦，泪痕红浥鲛绡透。桃花落，闲池阁。山盟虽在，锦书难托。莫、莫、莫。', '她红润柔嫩的手，捧着黄封酒；满城春色，宫墙边一片柳。东风可恶，欢情太薄。满怀愁绪，几年离索。错、错、错。
春天还如旧，人却白白瘦了；泪痕和着脂粉，把手帕都湿透。桃花落了，池阁空着。山盟虽在，书信难托。莫、莫、莫。', 'public-domain'),
  ('songci300', 160, '水龙吟·闹花深处层楼', 'songci-sc-175', '闹花深处层楼，画帘半卷东风软。春归翠陌，平莎茸嫩，垂杨金浅。迟日催花，淡云阁雨，轻寒轻暖。恨芳菲世界，游人未赏，都付与、莺和燕。
寂寞凭高念远，向南楼、一声归雁。金钗斗草，青丝勒马，风流云散。罗绶分香，翠绡封泪，几多幽怨！正消魂又是，疏烟淡月，子规声断。', '繁花深处的层楼，画帘半卷，东风柔软。春天回到翠绿的路上，平铺的莎草细嫩，垂杨垂下浅金色。迟迟的日光催花，淡云停雨，轻寒轻暖。恨这芳菲世界，游人还未赏看，都交给了黄莺和燕子。
寂寞中登高念远，向南楼听一声归雁。金钗斗草、青丝勒马的日子，都风流云散。罗带分香，翠绡封泪，有多少幽怨！正消魂时又是疏烟淡月，杜鹃声断。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 161, '眼儿媚·酣酣日脚紫烟浮', 'songci-sc-176', '酣酣日脚紫烟浮，妍暖破轻裘。困人天色，醉人花气，午梦扶头。
春慵恰似春塘水，一片縠纹愁。溶溶泄泄，东风无力，欲皱还休。', '暖融的日脚紫烟浮起，晴暖得可以脱下轻裘。困人的天色，醉人的花气，午梦里昏昏沉沉。
春困恰似春塘的水，一片绉纱似的愁。溶溶泄泄，东风无力，要起波纹又停下。', 'public-domain'),
  ('songci300', 162, '霜天晓角·晚晴风歇', 'songci-sc-177', '晚晴风歇，一夜春威折。脉脉花疏天淡，云来去、数枝雪。
胜绝，愁亦绝。此情谁共说。惟有两行低雁，知人倚、画楼月。', '傍晚放晴，风停了，一夜之间春寒的威势被折住。花疏天淡，含情脉脉；云来云去，几枝如雪。
美到极处，愁也到极处。这份情向谁诉说？只有两行低飞的大雁，知道人正倚着画楼看月。', 'public-domain'),
  ('songci300', 163, '贺新郎·绿树听鹈鴂', 'songci-sc-178', '绿树听鹈鴂。更那堪、鹧鸪声住，杜鹃声切。啼到春归无寻处，苦恨芳菲都歇。算未抵、人间离别。马上琵琶关塞黑，更长门、翠辇辞金阙。看燕燕，送归妾。
将军百战身名裂。向河梁、回头万里，故人长绝。易水萧萧西风冷，满座衣冠似雪。正壮士、悲歌未彻。啼鸟还知如许恨，料不啼清泪长啼血。谁共我，醉明月。', '在绿树间听鹈鴂啼叫。更哪堪鹧鸪声刚停，杜鹃又叫得凄切。啼到春天归去无处可寻，苦恨百花都歇了。算来还比不上人间的离别。昭君骑在马上弹琵琶，关塞昏黑；还有陈皇后乘翠辇辞别金阙。看燕子飞，送走远嫁的人。
李陵将军百战之身落得身败名裂。在河梁上回头万里，与故人永诀。易水萧萧，西风冷，满座衣冠白如雪。正是壮士悲歌未终。啼鸟还知道这些恨，料想它不啼清泪而长啼血。谁来陪我，在明月下醉倒。', 'public-domain'),
  ('songci300', 164, '念奴娇·野棠花落', 'songci-sc-179', '野棠花落，又匆匆过了，清明时节。刬地东风欺客梦，一枕云屏寒怯。曲岸持觞，垂杨系马，此地曾轻别。楼空人去，旧游飞燕能说。
闻道绮陌东头，行人曾见，帘底纤纤月。旧恨春江流不断，新恨云山千叠。料得明朝，尊前重见，镜里花难折。也应惊问：近来多少华发？', '野棠花落，又匆匆过了清明时节。无端的东风欺我客梦，枕上对着云屏只觉寒怯。曲岸边举杯，垂杨下系马，就在这里曾经轻易分别。楼空人去，旧游只有飞燕还能说。
听说繁华街市东头，有人曾见过帘下那弯纤纤的月。旧恨像春江流不断，新恨像云山千叠。料想明朝在杯前重见，镜中之花难以折取。她也该惊问：近来添了多少白发？', 'public-domain'),
  ('songci300', 165, '汉宫春·春已归来', 'songci-sc-180', '春已归来，看美人头上，袅袅春幡。无端风雨，未肯收尽余寒。年时燕子，料今宵、梦到西园。浑未办、黄柑荐酒，更传青韭堆盘。
却笑东风从此，便薰梅染柳，更没些闲。闲时又来镜里，转变朱颜。清愁不断，问何人、会解连环？生怕见、花开花落，朝来塞雁先还。', '春天已经回来了，看美人头上，袅袅的春幡。无端的风雨，不肯把余寒收尽。去年的燕子，料想今夜会梦到西园。还全没备好黄柑荐酒，更别说传青韭堆盘。
却笑东风从此就要熏梅染柳，再没有一点空闲。闲下来又到镜子里，把红颜转变。清愁不断，问谁人能解开连环？最怕看见花开花落——清晨塞雁已经先归去了。', 'public-domain'),
  ('songci300', 166, '贺新郎·凤尾龙香拨', 'songci-sc-181', '凤尾龙香拨。自开元、《霓裳》曲罢，几番风月？最苦浔阳江头客，画舸亭亭待发。记出塞、黄云堆雪。马上离愁三万里，望昭阳、宫殿孤鸿没。弦解语，恨难说。
辽阳驿使音尘绝。琐窗寒、轻拢慢捻，泪珠盈睫。推手含情还却手，一抹《梁州》哀彻。千古事、云飞烟灭。贺老定场无消息，想沉香亭北繁华歇。弹到此，为呜咽。', '凤尾形的琵琶槽，龙香柏制的拨子。自从开元年间《霓裳羽衣曲》奏罢，经历了多少番风月？最苦的是浔阳江头那位客人，画船亭亭正待出发。记得昭君出塞时，黄沙如云、积雪成堆。马上的离愁有三万里，遥望昭阳宫殿，只见孤雁没入天际。琵琶弦能说话，这遗恨却难以诉说。
辽阳来的驿使音信断绝。冷清的小窗前，轻轻拢、慢慢捻，泪珠盈满睫毛。推手含情又却手，《梁州》一曲弹得哀伤透彻。千古兴亡事，都如云飞烟灭。贺怀智那样的定场高手已无消息，想来沉香亭北的繁华也已消歇。弹到这里，令人呜咽。', 'public-domain'),
  ('songci300', 167, '水龙吟·楚天千里清秋', 'songci-sc-182', '楚天千里清秋，水随天去秋无际。遥岑远目，献愁供恨，玉簪螺髻。落日楼头，断鸿声里，江南游子。把吴钩看了，阑干拍遍，无人会、登临意。
休说鲈鱼堪脍，尽西风、季鹰归未？求田问舍，怕应羞见，刘郎才气。可惜流年，忧愁风雨，树犹如此！倩何人唤取，红巾翠袖，揾英雄泪！', '楚地天空千里清秋，江水随天而去，秋色无边。远望群山，像在献愁供恨，如玉簪螺髻。落日楼头，孤雁声里，我这江南游子。把吴钩看了又看，把栏杆拍遍，没有人懂得我登临的心意。
不要说鲈鱼可以脍，西风起了，张季鹰归去了没有？买田置屋，怕该羞见刘备那样的才气。可惜流年，忧愁风雨，树都长得这样大了！请谁去唤来红巾翠袖的歌女，替我擦干英雄的泪！', 'public-domain'),
  ('songci300', 168, '摸鱼儿·更能消', 'songci-sc-184', '更能消、几番风雨，匆匆春又归去。惜春长怕花开早，何况落红无数。春且住！见说道、天涯芳草无归路。怨春不语。算只有殷勤，画檐蛛网，尽日惹飞絮。
长门事，准拟佳期又误。蛾眉曾有人妒。千金纵买相如赋，脉脉此情谁诉？君莫舞！君不见、玉环飞燕皆尘土。闲愁最苦。休去倚危阑，斜阳正在，烟柳断肠处。', '还能经得几番风雨，春天又匆匆归去。惜春总怕花开得太早，何况落红无数。春天你且留下！听说天涯芳草，没有归路。怨春不语。算来只有画檐上的蛛网殷勤，整日粘着飞絮。
长门宫的事，本预计好的佳期又被误了。美人总有人嫉妒。纵然花千金买来相如的赋，这脉脉情意向谁诉说？你不要舞！你没看见杨玉环、赵飞燕都成了尘土。闲愁最苦。不要去倚危栏，斜阳正照在烟柳断肠之处。', 'public-domain'),
  ('songci300', 169, '永遇乐·千古江山', 'poems-gz10-08', '千古江山，英雄无觅，孙仲谋处。
舞榭歌台，风流总被，雨打风吹去。
斜阳草树，寻常巷陌，人道寄奴曾住。
想当年，金戈铁马，气吞万里如虎。
元嘉草草，封狼居胥，赢得仓皇北顾。
四十三年，望中犹记，烽火扬州路。
可堪回首，佛狸祠下，一片神鸦社鼓。
凭谁问：廉颇老矣，尚能饭否？', '千古以来的江山依旧，却再也找不到孙权那样的英雄了。当年的歌舞楼台，那些风流业绩，都被雨打风吹得无影无踪。夕阳照着衰草杂树，那些普通的街巷，人们说刘裕曾经在这里住过。想当年，他金戈铁马，气势如虎，吞掉了万里江山。元嘉年间草率出兵，想建立像封狼居胥那样的功业，却落得仓皇败退、回头北望。四十三年过去了，望中还记得当年扬州路上烽火连天的情景。怎么忍心回头看呢，佛狸祠下，一片神鸦的叫声和社日的鼓声。靠谁来问：廉颇老了，饭量还好吗？', 'academic'),
  ('songci300', 170, '木兰花·年年跃马长安市', 'songci-sc-212', '年年跃马长安市，客舍似家家似寄。青钱换酒日无何，红烛呼卢宵不寐。
易挑锦妇机中字，难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪！', '年年跃马在长安街市，客舍像家、家倒像寄居。青钱换酒，天天无事；红烛下呼卢赌博，通宵不睡。
容易挑出织锦妇人的回文诗，难得明白美人心中的事。男儿在西北还有神州故土，不要在滴水的西桥边落泪！', 'public-domain'),
  ('songci300', 171, '青玉案·凌波不过横塘路', 'songci-sc-129', '凌波不过横塘路，但目送、芳尘去。锦瑟华年谁与度？月桥花院，琐窗朱户，只有春知处。
飞云冉冉蘅皋暮，彩笔新题断肠句。试问闲愁都几许？一川烟草，满城风絮，梅子黄时雨。', '她轻盈的脚步不过横塘路，我只能目送她带着芳香的尘土远去。锦瑟般的年华与谁共度？月桥花院，雕窗朱户，只有春天知道她的去处。
飞云缓缓，长满香草的水边已近黄昏，我提彩笔新写下断肠的句子。试问我的闲愁有多少？就像一川烟草、满城风絮、梅子黄时的细雨。', 'public-domain'),
  ('songci300', 172, '薄幸·淡妆多态', 'songci-sc-131', '淡妆多态，更的的、频回眄睐。便认得、琴心先许，欲绾合欢双带。记画堂、风月逢迎，轻颦浅笑娇无奈。向睡鸭炉边，翔鸳屏里，羞把香罗暗解。
自过了、烧灯后，都不见、踏青挑菜。几回凭双燕，叮咛深意，往来却恨重帘碍。约何时再？正春浓酒困，人闲昼永无聊赖。厌厌睡起，犹有花梢日在。', '她淡妆多态，又频频回头顾盼。便知道她已先许下琴心，想结起合欢的双带。记得在画堂里风月相迎，她轻蹙双眉、浅浅一笑，娇得无可奈何。在睡鸭炉边、翔鸳屏风里，羞怯地暗暗解下香罗。
自从灯节过后，都不见踏青挑菜的约会。几次托双燕，叮咛深意，往来却恨重重帘幕阻隔。约好何时再见？正当春浓酒困，人闲昼长，无聊赖。懒懒地睡起，花梢上还挂着日影。', 'public-domain'),
  ('songci300', 173, '浣溪沙·楼角初销一缕霞', 'songci-sc-132', '楼角初销一缕霞，淡黄杨柳暗栖鸦。玉人和笑摘梅花。
笑捻粉香归洞户，更垂帘幕护窗纱。东风寒似夜来些。', '楼角的最后一缕霞光刚刚消散，淡黄杨柳里暗栖着乌鸦。玉人含笑去摘梅花。
她笑着捻着粉香回到内室，又垂下帘幕护住窗纱。东风比昨夜还要冷一些。', 'public-domain'),
  ('songci300', 174, '石州慢·薄雨收寒', 'songci-sc-133', '薄雨收寒，斜照弄晴，春意空阔。长亭柳色才黄，远客一枝先折。烟横水际，映带几点归鸦，东风销尽龙沙雪。还记出关来，恰而今时节。
将发，画楼芳酒，红泪清歌，顿成轻别。已是经年，杳杳音尘多绝。欲知方寸，共有几许清愁？芭蕉不展丁香结。枉望断天涯，两厌厌风月。', '小雨收去寒意，斜阳弄晴，春意空阔。长亭的柳色刚黄，远客已先折了一枝。烟雾横在水边，映带几点归鸦，东风把塞外的雪都消尽了。还记得出关来时，正是如今这个时节。
将要出发时，画楼上芳香的美酒、她带泪的清歌，顿时成了轻易的离别。已经过了一年，音信多已断绝。要知道我心里有多少清愁？就像芭蕉不展、丁香结蕾。白白望断天涯，两人都在风月里恹恹无绪。', 'public-domain'),
  ('songci300', 175, '天门谣·牛渚天门险', 'songci-sc-135', '牛渚天门险，限南北、七雄豪占。清雾敛，与闲人登览。
待月上潮平波滟滟，塞管轻吹新阿滥。风满槛，历历数、西州更点。', '牛渚天门形势险要，隔开南北，七国豪杰都曾占据。清雾收敛，让闲人登临观赏。
等到月出潮平，波光滟滟，塞管轻吹新曲《阿滥堆》。风满栏杆，清晰地数着西州的更点。', 'public-domain'),
  ('songci300', 176, '天香·烟络横林', 'songci-sc-136', '烟络横林，山沉远照，迤逦黄昏钟鼓。烛映帘栊，蛩催机杼，共苦清秋风露。不眠思妇，齐应和、几声砧杵。惊动天涯倦宦，骎骎岁华行暮。
当年酒狂自负，谓东君、以春相付。流浪征骖北道，客樯南浦。幽恨无人晤语。赖明月、曾知旧游处。好伴云来，还将梦去。', '烟雾缠绕横林，远山沉入夕照，黄昏的钟鼓声连绵不断。烛光映着帘栊，蟋蟀催人纺织，一同受着清秋风露之苦。不眠的思妇，几声砧杵齐相应和。惊动了天涯倦宦，岁月匆匆将暮。
当年以酒狂自负，以为春神会把春天交给我。如今却流浪在北道征鞍、南浦客舟。幽恨无人可以面谈。幸赖明月曾知旧游之处。好伴着云来，再把梦带去。', 'public-domain'),
  ('songci300', 177, '望湘人·厌莺声到枕', 'songci-sc-137', '厌莺声到枕，花气动帘，醉魂愁梦相半。被惜余薰，带惊剩眼，几许伤春春晚。泪竹痕鲜，佩兰香老，湘天浓暖。记小江、风月佳时，屡约非烟游伴。
须信鸾弦易断，奈云和再鼓，曲中人远。认罗袜无踪，旧处弄波清浅。青翰棹舣，白苹洲畔。尽目临皋飞观。不解寄、一字相思，幸有归来双燕。', '厌听莺声传到枕边，花香拂动帘子，醉魂与愁梦各占一半。怜惜被上残留的香气，惊见腰带宽出许多孔，多少伤春之情，春天已晚。湘妃竹的泪痕还新，佩兰的香气已老，湘天浓暖。记得在江边风月最好的时候，多次约她同游。
要知道鸾弦容易断，奈何重新鼓瑟，曲中人已远。认那罗袜的踪迹已无，旧日她戏水的清浅之处。乘着青翰船靠岸，停在白苹洲边。极目望那临皋的高楼。不会寄一个字来诉相思，幸有一双归燕。', 'public-domain'),
  ('songci300', 178, '绿头鸭·玉人家', 'songci-sc-138', '玉人家，画楼珠箔临津。托微风、彩箫流怨，断肠马上曾闻。宴堂开、艳妆丛里，调琴思、认歌颦。麝蜡烟浓，玉莲漏短，更衣不待酒初醺。绣屏掩、枕鸳相就，香气渐暾暾。回廊影，疏钟淡月，几许消魂？
翠钗分、银笺封泪，舞鞋从此生尘。任兰舟、载将离恨，转南浦、背西曛。记取明年，蔷薇谢后，佳期应未误行云。凤城远、楚梅香嫩，先寄一枝春。青门外，只凭芳草，寻访郎君。', '玉人家住画楼，珠帘临着渡口。托微风送去彩箫的哀怨，那断肠的曲子在马上曾听过。宴堂开时，艳妆丛中，她调琴的情思、唱歌时皱眉的样子我都认得。麝香蜡烛烟浓，玉莲漏滴得短，还没等酒上脸就换了衣裳。绣屏掩上，鸳鸯枕相就，香气渐渐暖浓。回廊的影子、疏钟与淡月，有多少消魂？
翠钗分作两半，银笺封着泪，舞鞋从此生了尘。任凭兰舟载着离恨，转过南浦，背向西沉的落日。记住明年蔷薇谢后，佳期该不会误了行云之约。京城遥远，楚地的梅花香嫩，先寄一枝春去。青门外，只凭芳草，来寻找郎君。', 'public-domain'),
  ('songci300', 179, '点绛唇·燕雁无心', 'songci-sc-185', '燕雁无心，太湖西畔随云去。数峰清苦，商略黄昏雨。
第四桥边，拟共天随住。今何许？凭阑怀古，残柳参差舞。', '燕地的雁无心停留，在太湖西畔随云飞去。几座山峰清苦，正商量着黄昏的雨。
第四桥边，本想与陆天随同住。如今在哪里？倚栏怀古，只见残柳参差舞动。', 'public-domain'),
  ('songci300', 180, '鹧鸪天·肥水东流无尽期', 'songci-sc-186', '肥水东流无尽期，当初不合种相思。梦中未比丹青见，暗里忽惊山鸟啼。
春未绿，鬓先丝。人间别久不成悲。谁教岁岁红莲夜，两处沉吟各自知。', '肥水向东流去没有尽期，当初不该种下相思。梦里相见还不如画像分明，暗中忽然被山鸟啼声惊醒。
春草还没绿，两鬓先白了。人间离别久了也就悲哀不起来。是谁让年年元宵灯夜，两人在两地各自沉吟，只有自己知道。', 'public-domain'),
  ('songci300', 181, '踏莎行·燕燕轻盈', 'songci-sc-187', '燕燕轻盈，莺莺娇软，分明又向华胥见。夜长争得薄情知？春初早被相思染。
别后书辞，别时针线，离魂暗逐郎行远。淮南皓月冷千山，冥冥归去无人管。', '像燕子一样轻盈，像黄莺一样娇软，分明又在梦里相见。夜长怎么让薄情的人知道？春天刚开始就已被相思染上。
别后的书信，别时的针线，离魂暗暗随着郎的行踪远去。淮南的皓月冷照千山，她幽幽地归去，无人照管。', 'public-domain'),
  ('songci300', 182, '齐天乐·庾郎先自吟愁赋', 'songci-sc-188', '庾郎先自吟愁赋，凄凄更闻私语。露湿铜铺，苔侵石井，都是曾听伊处。哀音似诉。正思妇无眠，起寻机杼。曲曲屏山，夜凉独自甚情绪？
西窗又吹暗雨。为谁频断续，相和砧杵？候馆迎秋，离宫吊月，别有伤心无数。豳诗漫与。笑篱落呼灯，世间儿女。写入琴丝，一声声更苦。', '庾信先自吟起愁赋，凄凄地又听见蟋蟀私语。露水湿了铜铺首，青苔侵上石井，都是曾听它鸣叫的地方。哀音像在诉说。正是思妇无法入睡，起身去找机杼。曲曲屏风，夜凉里独自是什么情绪？
西窗又被暗雨吹打。它为谁频频断续，与砧杵相应和？候馆迎秋，离宫吊月，另有无数伤心。豳诗随意写成。可笑篱落间呼灯捉蟋蟀，那是世间的儿女。把它写入琴弦，一声声更苦。', 'public-domain'),
  ('songci300', 183, '琵琶仙·双桨来时', 'songci-sc-189', '双桨来时，有人似、旧曲桃根桃叶。歌扇轻约飞花，蛾眉正奇绝。春渐远、汀洲自绿，更添了、几声啼鴂。十里扬州，三生杜牧，前事休说！
又还是、宫烛分烟，奈愁里、匆匆换时节。都把一襟芳思，与空阶榆荚。千万缕、藏鸦细柳，为玉尊、起舞回雪。想见西出阳关，故人初别。', '双桨划来，船上有人像旧曲里的桃根桃叶。歌扇轻轻约住飞花，蛾眉正奇绝。春天渐渐远了，汀洲自绿，又添了几声杜鹃啼。十里扬州，三生杜牧，前事不必再说！
又还是宫中传烛分烟的时候，怎奈在愁里匆匆换了时节。把一襟芳思，都交给了空阶上的榆荚。千万缕可以藏鸦的细柳，为玉杯起舞，像回风旋雪。想见西出阳关时，故人初别的情景。', 'public-domain'),
  ('songci300', 184, '八归·芳莲坠粉', 'songci-sc-190', '芳莲坠粉，疏桐吹绿，庭院暗雨乍歇。无端抱影销魂处，还见筱墙萤暗，藓阶蛩切。送客重寻西去路，问水面、琵琶谁拨？最可惜、一片江山，总付与啼鴂。
长恨相从未款，而今何事，又对西风离别？渚寒烟淡，棹移人远，缥缈行舟如叶。想文君望久，倚竹愁生步罗袜。归来后、翠尊双饮，下了珠帘，玲珑闲看月。', '芳莲坠落粉瓣，疏桐吹着绿叶，庭院里暗雨刚停。无端抱着影子消魂的地方，又看见竹墙上萤火暗淡，苔阶上蟋蟀声凄切。送客重寻西去的路，问水面上是谁在拨琵琶？最可惜一片江山，都交给了杜鹃啼。
长恨相跟随从不能尽意，如今又为什么，对着西风离别？洲渚寒、烟雾淡，船移人远，缥缈的行舟像一片叶。想她久望，倚着竹子发愁，罗袜生尘。归来后，双饮翠杯，放下珠帘，悠闲地看玲珑的月。', 'public-domain'),
  ('songci300', 185, '念奴娇·闹红一舸', 'songci-sc-191', '闹红一舸，记来时、尝与鸳鸯为侣。三十六陂人未到，水佩风裳无数。翠叶吹凉，玉容消酒，更洒菰蒲雨。嫣然摇动，冷香飞上诗句。
日暮，青盖亭亭，情人不见，争忍凌波去？只恐舞衣寒易落，愁入西风南浦。高柳垂阴，老鱼吹浪，留我花间住。田田多少，几回沙际归路。', '在喧闹的荷花中乘一舸，记得来时曾与鸳鸯为伴。三十六处池塘人迹未到，无数荷叶如水的佩、风的裳。翠叶吹出凉意，娇容消去酒意，又洒下一阵菰蒲的雨。它嫣然摇动，冷香飞上我的诗句。
日暮，青色的荷叶亭亭而立，情人不见，怎忍心凌波而去？只恐舞衣遇寒容易零落，愁绪随着西风飘向南浦。高柳垂下绿荫，老鱼吹起波浪，留我在花间住下。田田的荷叶有多少，几次在沙岸边找归路。', 'public-domain'),
  ('songci300', 186, '扬州慢·淮左名都', 'poems-gz11-19', '淮左名都，竹西佳处，解鞍少驻初程。
过春风十里，尽荠麦青青。
自胡马窥江去后，废池乔木，犹厌言兵。
渐黄昏，清角吹寒，都在空城。
杜郎俊赏，算而今重到须惊。
纵豆蔻词工，青楼梦好，难赋深情。
二十四桥仍在，波心荡，冷月无声。
念桥边红药，年年知为谁生？', '扬州是淮河东边著名的都会，在竹西亭这美好的去处，我解下马鞍稍作停留。走过当年春风十里的繁华街道，如今却长满了青青的荠菜和野麦。自从金兵进犯长江流域撤走以后，废弃的池塘、高大的树木，至今还厌恶谈论战争。渐渐到了黄昏，清冷的号角声在寒冷中吹响，回荡在这座空城里。杜牧曾经那样善于游赏，料想他如今重游此地也一定会感到吃惊。纵然他写「豆蔻」的词句精工，写「青楼」的美梦美好，也难以表达此刻深沉的感情。二十四桥依然还在，水波荡漾，冷月无声。遥想桥边的红芍药，年复一年，不知道是为谁开放？', 'academic'),
  ('songci300', 187, '长亭怨慢·渐吹尽', 'songci-sc-193', '渐吹尽、枝头香絮，是处人家，绿深门户。远浦萦回，暮帆零乱向何许？阅人多矣，谁得似、长亭树？树若有情时，不会得、青青如此！
日暮，望高城不见，只见乱山无数。韦郎去也，怎忘得、玉环分付：第一是、早早归来，怕红萼、无人为主。算空有并刀，难剪离愁千缕。', '枝头的香絮渐渐吹尽，到处人家，绿荫深掩门户。远处江浦萦回，暮色中船帆零乱，要驶向哪里？长亭的树见过的人多了，谁能比得上它？树若是有情，就不会这样青青！
日暮，望不见高城，只见乱山无数。韦郎一去，怎么忘得了她的嘱托：第一是早早归来，怕红花无人做主。算来空有利剪，也难剪断千缕离愁。', 'public-domain'),
  ('songci300', 188, '淡黄柳·空城晓角', 'songci-sc-194', '空城晓角，吹入垂杨陌。马上单衣寒恻恻。看尽鹅黄嫩绿，都是江南旧相识。
正岑寂，明朝又寒食。强携酒、小桥宅。怕梨花落尽成秋色。燕燕飞来，问春何在，唯有池塘自碧。', '空城清晨的号角声，吹进垂杨覆盖的街路。马上单衣，寒意恻恻。看尽鹅黄嫩绿，都是江南旧相识。
正是岑寂，明天又是寒食。勉强带着酒，到她小桥边的住处。怕梨花落尽，就成了秋色。燕子飞来，问春天在哪里——只有池塘自碧。', 'public-domain'),
  ('songci300', 189, '暗香·旧时月色', 'songci-sc-195', '旧时月色，算几番照我，梅边吹笛？唤起玉人，不管清寒与攀摘。何逊而今渐老，都忘却、春风词笔。但怪得、竹外疏花，香冷入瑶席。
江国，正寂寂。叹寄与路遥，夜雪初积。翠尊易泣，红萼无言耿相忆。长记曾携手处，千树压、西湖寒碧。又片片、吹尽也，几时见得？', '旧时的月色，算来几次照着我，在梅边吹笛？唤起玉人，不管清寒也要攀折。何逊如今渐渐老了，都忘了春风的词笔。只怪竹外那几枝疏花，冷香飘入瑶席。
江南水乡，正是寂寂。可叹路远难寄，夜雪初积。翠杯容易惹泪，红萼无言，耿耿相忆。常记得曾携手的地方，千树梅花压着西湖的寒碧。又一片片吹尽了，什么时候才能再见？', 'public-domain'),
  ('songci300', 190, '疏影·苔枝缀玉', 'songci-sc-196', '苔枝缀玉，有翠禽小小，枝上同宿。客里相逢，篱角黄昏，无言自倚修竹。昭君不惯胡沙远，但暗忆、江南江北。想佩环、月夜归来，化作此花幽独。
犹记深宫旧事，那人正睡里，飞近蛾绿。莫似春风，不管盈盈，早与安排金屋。还教一片随波去，又却怨、玉龙哀曲。等恁时、重觅幽香，已入小窗横幅。', '苔痕斑驳的枝上缀着玉一般的花，有小翠鸟在枝上同宿。客途中相逢，篱角黄昏，它无言地倚着修竹。昭君不惯胡地的风沙遥远，只暗暗思念江南江北。想她佩环叮咚、月夜归来，化作这枝幽独的花。
还记得深宫旧事，那人正在睡梦中，梅花飞近她的蛾眉。不要像春风那样，不管它盈盈可爱，早该为它安排金屋。还教一片随波流去，却又怨玉笛的哀曲。等到那时再觅幽香，它已进了小窗上的横幅画里。', 'public-domain'),
  ('songci300', 191, '翠楼吟·月冷龙沙', 'songci-sc-197', '月冷龙沙，尘清虎落，今年汉酺初赐。新翻胡部曲，听毡幕、元戎歌吹。层楼高峙。看槛曲萦红，檐牙飞翠。人姝丽，粉香吹下，夜寒风细。
此地，宜有词仙，拥素云黄鹤，与君游戏。玉梯凝望久，叹芳草、萋萋千里。天涯情味。仗酒祓清愁，花销英气。西山外，晚来还卷，一帘秋霁。', '月色冷照着龙沙，尘埃扫清在虎落，今年朝廷初次赐酺。新翻的胡部乐曲，从毡幕里传出元戎的歌吹。层楼高高耸立。看栏杆回曲萦着红色，檐牙飞着翠色。人儿美丽，粉香从楼上吹下，夜寒风细。
这地方，该有词仙，拥着素云黄鹤，与你同游。在玉梯上凝望久了，可叹芳草萋萋千里。天涯的滋味。只能靠酒来除清愁，靠花来销磨英气。西山之外，傍晚时又卷起一帘秋晴。', 'public-domain'),
  ('songci300', 192, '小重山·柳暗花明春事深', 'songci-sc-198', '柳暗花明春事深，小阑红芍药、已抽簪。雨余风软碎鸣禽，迟迟日，犹带一分阴。
往事莫沉吟，身闲时序好、且登临。旧游无处不堪寻，无寻处、惟有少年心。', '柳暗花明，春事已深；小栏杆边的红芍药已经抽出簪一样的花苞。雨后风软，鸣禽声碎；日头迟迟，还带着一分阴。
往事不要沉吟；身闲时序又好，且去登临。旧游之处没有一处不能寻访，寻不到的，只有那颗少年心。', 'public-domain'),
  ('songci300', 193, '唐多令·芦叶满汀洲', 'songci-sc-199', '芦叶满汀洲，寒沙带浅流。二十年重过南楼。柳下系船犹未稳，能几日、又中秋。
黄鹤断矶头，故人曾到否？旧江山浑是新愁。欲买桂花同载酒，终不似、少年游。', '芦叶长满汀洲，寒沙带着浅流。二十年后重过南楼。柳下系船还没系稳，能过几天，又到中秋。
黄鹤矶头，故人来过没有？旧日江山全是新愁。想买桂花、载着酒同游，终究不像少年时那样了。', 'public-domain'),
  ('songci300', 194, '木兰花·春风只在园西畔', 'songci-sc-200', '春风只在园西畔，荠菜花繁蝴蝶乱。冰池晴绿照还空，香径落红吹已断。
意长翻恨游丝短，尽日相思罗带缓。宝奁明月不欺人，明日归来君试看。', '春风只在园子西边，荠菜花开得繁盛，蝴蝶纷乱。冰池晴日的绿光映照还是空的，香径上的落花已被吹尽。
情意深长反倒恨游丝太短，整日相思，罗带都松了。梳妆镜的明月不骗人，明天你归来时试着看看。', 'public-domain'),
  ('songci300', 195, '风入松·一春长费买花钱', 'songci-sc-201', '一春长费买花钱，日日醉湖边。玉骢惯识西湖路，骄嘶过、沽酒楼前。红杏香中箫鼓，绿杨影里秋千。
暖风十里丽人天，花压鬓云偏。画船载取春归去，余情付、湖水湖烟。明日重扶残醉，来寻陌上花钿。', '一春常花买花的钱，天天醉在西湖边。玉骢马惯识西湖的路，骄嘶着走过卖酒楼前。红杏香中有箫鼓，绿杨影里有秋千。
暖风十里，是丽人的天气；花压得鬓发偏斜。画船载着春天归去，余情交给湖水湖烟。明天再扶着残醉，来寻路上的花钿。', 'public-domain'),
  ('songci300', 196, '满庭芳·月洗高梧', 'songci-sc-202', '月洗高梧，露漙幽草，宝钗楼外秋深。土花沿翠，萤火坠墙阴。静听寒声断续，微韵转、凄咽悲沉。争求侣，殷勤劝织，促破晓机心。
儿时，曾记得，呼灯灌穴，敛步随音。任满身花影，犹自追寻。携向华堂戏斗，亭台小、笼巧妆金。今休说，从渠床下，凉夜伴孤吟。', '月光冲洗着高梧，露水沾满幽草，宝钗楼外秋意已深。苔藓沿着翠色生长，萤火坠在墙阴。静听那寒声断续，微韵转成凄咽悲沉。它急于求偶，殷勤地像劝人纺织，催破了拂晓时的机杼心。
儿时曾记得，呼着灯、灌水入穴，收着脚步跟着声音。任凭满身都是花影，还要追寻。把它带到华堂里戏斗，亭台小，笼子精巧、妆饰如金。如今不必说了，任凭它在床下，凉夜里伴我独吟。', 'public-domain'),
  ('songci300', 197, '绮罗香·做冷欺花', 'songci-sc-203', '做冷欺花，将烟困柳，千里偷催春暮。尽日冥迷，愁里欲飞还住。惊粉重、蝶宿西园，喜泥润、燕归南浦。最妨它、佳约风流，钿车不到杜陵路。
沉沉江上望极，还被春潮晚急，难寻官渡。隐约遥峰，和泪谢娘眉妩。临断岸、新绿生时，是落红、带愁流处。记当日、门掩梨花，剪灯深夜语。', '它化作寒意欺负花朵，化作烟雾困住柳树，在千里间偷偷催促春暮。整日迷蒙，像在愁里要飞又停下。惊觉花粉变重，蝴蝶宿在西园；喜见泥土湿润，燕子回到南浦。最妨碍的是风流佳约，钿车到不了杜陵路。
沉沉江上极目远望，又被春潮晚来汹涌，难以找到官渡。隐约的远峰，像和着泪水的美人眉。临着断岸，新绿生出的时候，正是落红带着愁流去的地方。记得当日门掩梨花，剪灯深夜说话。', 'public-domain'),
  ('songci300', 198, '双双燕·过春社了', 'songci-sc-204', '过春社了，度帘幕中间，去年尘冷。差池欲住，试入旧巢相并。还相雕梁藻井，又软语商量不定。飘然快拂花梢，翠尾分开红影。
芳径，芹泥雨润。爱贴地争飞，竞夸轻俊。红楼归晚，看足柳昏花暝。应自栖香正稳，便忘了、天涯芳信。愁损翠黛双蛾，日日画栏独凭。', '春社过了，它们穿过帘幕之间，去年的巢已积了冷尘。翅膀参差想停下，试着进入旧巢相并。又端详雕梁藻井，软语商量不定。忽然飘然拂过花梢，翠尾分开红影。
芳香的小径，芹泥被雨润湿。它们爱贴地争飞，竞相夸耀轻捷俊俏。回红楼时已晚，看够了柳暗花昏。该是在香巢里睡稳了，便忘了天涯的书信。愁坏了那双翠眉，天天独自倚着画栏。', 'public-domain'),
  ('songci300', 199, '东风第一枝·巧沁兰心', 'songci-sc-205', '巧沁兰心，偷黏草甲，东风欲障新暖。谩凝碧瓦难留，信知暮寒较浅。行天入镜，做弄出、轻松纤软。料故园、不卷重帘，误了乍来双燕。
青未了、柳回白眼，红欲断、杏开素面。旧游忆著山阴，厚盟遂妨上苑。寒炉重暖，便放慢、春衫针线。恐凤靴、挑菜归来，万一灞桥相见。', '它巧妙地沁入兰心，偷偷黏上草芽，像要把东风的新暖挡住。白白凝在碧瓦上难以久留，的确知道暮寒还浅。在空中行、入镜般的水面，做出轻松纤软的样子。料想故园不卷重帘，误了刚来的双燕。
青色还没完，柳树就翻起白眼；红色将断，杏花开出素面。想起山阴的旧游，深约因此耽误了上苑之行。寒炉重新烧暖，便放慢了做春衫的针线。恐怕她穿着凤靴挑菜归来，万一在灞桥相见。', 'public-domain'),
  ('songci300', 200, '喜迁莺·月波疑滴', 'songci-sc-206', '月波疑滴，望玉壶天近，了无尘隔。翠眼圈花，冰丝织练，黄道宝光相直。自怜诗酒瘦，难应接、许多春色。最无赖，是随香趁烛，曾伴狂客。
踪迹，漫记忆，老了杜郎，忍听东风笛。柳院灯疏，梅厅雪在，谁与细倾春碧？旧情拘未定，犹自学、当年游历。怕万一，误玉人、夜寒帘隙。', '月波像要滴下，望那玉壶般的天空近在眼前，一点尘埃也没有。翠色的灯圈、冰丝织成的绢，与黄道宝光相照。自怜诗酒消磨得人瘦，难以应接这许多春色。最无赖的是随着香、趁着烛，曾经陪伴狂客。
踪迹，空自记忆，杜郎已老，怎忍听东风的笛声。柳院灯光疏落，梅厅还有积雪，谁来为我细斟春酒？旧情拘束未定，还在学当年的游历。怕万一误了玉人，在夜寒的帘缝间等待。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 201, '三姝媚·烟光摇缥瓦', 'songci-sc-207', '烟光摇缥瓦，望晴檐多风，柳花如洒。锦瑟横床，想泪痕尘影，凤弦常下。倦出犀帷，频梦见、王孙骄马。讳道相思，偷理绡裙，自惊腰衩。
惆怅南楼遥夜。记翠箔张灯，枕肩歌罢。又入铜驼，遍旧家门巷，首询声价。可惜东风，将恨与、闲花俱谢。记取崔徽模样，归来暗写。', '烟光在青瓦上摇动，望晴日屋檐多风，柳花像洒下来。锦瑟横在床上，想那泪痕尘影，弦柱常常卸下。她懒得出犀帐，频频梦见王孙的骄马。讳言相思，偷偷整理绡裙，自己惊觉腰身瘦了。
惆怅南楼的遥夜。记得翠帘张灯，枕肩歌罢。又来到铜驼街，走遍旧日的门巷，先打听她的声价。可惜东风，把恨与闲花一起吹谢。记住崔徽的模样，回来后暗暗描画。', 'public-domain'),
  ('songci300', 202, '秋霁·江水苍苍', 'songci-sc-208', '江水苍苍，望倦柳愁荷，共感秋色。废阁先凉，古帘空暮，雁程最嫌风力。故园信息，爱渠入眼南山碧。念上国，谁是、脍鲈江汉未归客？
还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。露蛩悲、清灯冷屋，翻书愁上鬓毛白。年少俊游浑断得。但可怜处，无奈冉冉魂惊，采香南浦，剪梅烟驿。', '江水苍茫，望那倦柳愁荷，一同感到秋色。废阁先凉，旧帘空垂到暮色，雁飞的路最怕风力。故园的消息，爱它入眼的南山碧色。想京城里，谁是那想脍鲈鱼却未能归江汉的客？
又到岁晚，瘦骨临风，夜里听秋声，吹动一片岑寂。露中蟋蟀悲鸣，清灯冷屋，翻书时愁得鬓毛都白了。年少的俊游全然断绝。只有可怜之处，无奈心魂冉冉惊动，在南浦采香，在烟驿剪梅。', 'public-domain'),
  ('songci300', 203, '夜合花·柳锁莺魂', 'songci-sc-209', '柳锁莺魂，花翻蝶梦，自知愁染潘郎。轻衫未揽，犹将泪点偷藏。念前事，怯流光，早春窥、酥雨池塘。向消凝里，梅开半面，情满徐妆。
风丝一寸柔肠，曾在歌边惹恨，烛底萦香。芳机瑞锦，如何未织鸳鸯？人扶醉，月依墙，是当初、谁敢疏狂！把闲言语，花房夜久，各自思量。', '柳锁住黄莺的魂，花翻起蝴蝶的梦，自己知道愁已染上潘岳那样的白发。轻衫还没穿好，还把泪点偷偷藏起。想从前的事，怕流光，早春窥看酥雨后的池塘。在消凝之中，梅花开了半面，情意满是徐妃的半妆。
风丝一寸柔肠，曾经在歌边惹恨，在烛底萦香。芳机的瑞锦，怎么还没织出鸳鸯？有人扶醉，月亮靠着墙；当初谁敢这样疏狂！把那些闲言碎语，留在花房夜深时，各自思量。', 'public-domain'),
  ('songci300', 204, '玉蝴蝶·晚雨未摧宫树', 'songci-sc-210', '晚雨未摧宫树，可怜闲叶，犹抱凉蝉。短景归秋，吟思又接愁边。漏初长、梦魂难禁，人渐老、风月俱寒。想幽欢，土花庭甃，虫网阑干。
无端，啼蛄搅夜，恨随团扇，苦近秋莲。一笛当楼，谢娘悬泪立风前。故园晚、强留诗酒，新雁远、不致寒暄。隔苍烟、楚香罗袖，谁伴婵娟。', '晚雨没有打坏宫树，可怜那片闲叶，还抱着凉蝉。日短入秋，吟思又接到愁边。漏声初长，梦魂难禁；人渐老，风月都冷。想那幽欢之处，台阶生苔，栏杆结网。
无端，蝼蛄啼叫搅乱长夜；恨随着团扇，苦挨着秋莲。一声笛响当楼，谢娘含泪立在风前。故园天晚，勉强留着诗酒；新雁飞远，不带寒暄。隔着苍烟，楚香罗袖，谁来陪伴这婵娟。', 'public-domain'),
  ('songci300', 205, '贺新郎·湛湛长空黑', 'songci-sc-211', '湛湛长空黑。更那堪、斜风细雨，乱愁如织。老眼平生空四海，赖有高楼百尺。看浩荡、千崖秋色。白发书生神州泪，尽凄凉、不向牛山滴。追往事，去无迹。
少年自负凌云笔。到而今、春华落尽，满怀萧瑟。常恨世人新意少，爱说南朝狂客。把破帽、年年拈出。若对黄花孤负酒，怕黄花、也笑人岑寂。鸿北去，日西匿。', '长空一片深黑。更哪堪斜风细雨，乱愁像织。我这双老眼平生空看四海，赖有百尺高楼。看那浩荡的千崖秋色。白发书生为神州落泪，尽管凄凉，也不像齐景公那样在牛山滴泪。追想往事，去无踪迹。
少年时自负凌云之笔。到如今春花落尽，满怀萧瑟。常恨世人新意太少，爱说南朝的狂客，把破帽年年拈出来说。若对着菊花辜负了酒，怕菊花也要笑人寂寞。鸿雁北去，太阳西落。', 'public-domain'),
  ('songci300', 206, '湘春夜月·近清明', 'songci-sc-232', '近清明，翠禽枝上消魂。可惜一片清歌，都付与黄昏。欲共柳花低诉，怕柳花轻薄，不解伤春。念楚乡旅宿，柔情别绪，谁与温存？
空樽夜泣，青山不语，残月当门。翠玉楼前，惟是有、一波湘水，摇荡湘云。天长梦短，问甚时、重见桃根？这次第，算人间没个并刀，剪断心上愁痕。', '将近清明，翠鸟在枝上叫得令人消魂。可惜一片清越的歌声，都交给了黄昏。想对着柳花低声诉说，又怕柳花轻薄，不懂伤春。想我在楚乡旅宿，柔情别绪，谁来温存？
空杯在夜里像在哭泣，青山不语，残月当门。翠玉楼前，只有一波湘水，摇荡着湘云。天长梦短，问什么时候能重见桃根？这般情景，算来人间没有一把并州剪刀，能剪断心上的愁痕。', 'public-domain'),
  ('songci300', 207, '大有·戏马台前', 'songci-sc-233', '戏马台前，采花篱下，问岁华、还是重九。恰归来、南山翠色依旧。帘栊昨夜听风雨，都不似、登临时候。一片宋玉情怀，十分卫郎清瘦。
红萸佩，空对酒。砧杵动微寒，暗欺罗袖。秋已无多，早是败荷衰柳。强整帽檐敧侧，曾经向、天涯搔首。几回忆、故国莼鲈，霜前雁后。', '在戏马台前，采花于篱下，问岁华，又到重九。恰好归来，南山翠色依旧。帘栊外昨夜听风雨，都不像登临时的天气。一片宋玉般的悲秋情怀，十分卫玠般的清瘦。
红萸佩在身上，只能空对酒。砧杵声催来微寒，暗暗欺着罗袖。秋色已不多，早是败荷衰柳。勉强整理歪斜的帽檐，曾经在天涯搔首。几次回想故国的莼羹鲈鱼，在霜前雁后。', 'public-domain'),
  ('songci300', 208, '玉楼春·戏林推', 'songci-sc-341', '年年跃马长安市，客舍似家家似寄。青钱换酒日无何，红烛呼卢宵不寐。
易挑锦妇机中字，难得玉人心下事。男儿西北有神州，莫滴水西桥畔泪。', '年年骑马奔走在京城，客舍当作家里，家里反成了寄居之处。用青铜钱换酒，天天无事可做；红烛下呼卢赌博，通夜不睡。
叫妻子在机上织锦寄字是容易的，要猜透歌女心里的念头却难。男儿志在西北的神州大地，别在水西桥边为儿女之情落泪。', 'public-domain'),
  ('songci300', 209, '霜叶飞·断烟离绪', 'songci-sc-215', '断烟离绪，关心事，斜阳红隐霜树。半壶秋水荐黄花，香噀西风雨。纵玉勒、轻飞迅羽，凄凉谁吊荒台古？记醉踏南屏，彩扇咽寒蝉，倦梦不知蛮素。
聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。小蟾斜影转东篱，夜冷残蛩语。早白发、缘愁万缕。惊飙从卷乌纱去。漫细将、茱萸看，但约明年，翠微高处。', '断烟中一片离绪，最关心的事，是斜阳的红光隐在霜树里。半壶秋水供着黄花，香气喷向秋风秋雨。纵然策马轻飞如迅羽，凄凉中谁来凭吊荒台古迹？记得醉踏南屏，彩扇声中寒蝉凄咽，倦梦不知小蛮、樊素。
姑且对着旧节传杯，尘封的信笺、生蠹的笔管，断了的词稿经年懒得再赋。小月斜影转过东篱，夜冷中残蟋蟀在叫。早已白了头，都因万缕愁。狂风且卷走乌纱帽。慢慢细看茱萸，只约定明年，在青山高处。', 'public-domain'),
  ('songci300', 210, '宴清都·绣幄鸳鸯柱', 'songci-sc-216', '绣幄鸳鸯柱，红情密、腻云低护秦树。芳根兼倚，花梢钿合，锦屏人妒。东风睡足交枝，正梦枕、瑶钗燕股。障滟蜡、满照欢丛，嫠蟾冷落羞度。
人间万感幽单，华清惯浴，春盎风露。连鬟并暖，同心共结，向承恩处。凭谁为歌长恨？暗殿锁、秋灯夜语。叙旧期、不负春盟，红朝翠暮。', '绣帐上鸳鸯交柱，红情密处，浓云低低护着海棠。香根相依，花梢如钿盒相合，锦屏里的人见了也嫉妒。东风里睡足，枝条相交，正像枕上梦着瑶钗燕股。挡住滟滟的蜡烛，照着满丛的欢意，孤月冷落羞于照过。
人间万种感慨都落在孤独上；华清池惯于沐浴，春意盎然的春风露水。双鬟并暖，同心共结，在那承恩的地方。靠谁来唱《长恨歌》？暗殿锁着，秋灯下夜语。叙述旧日的期约，不辜负春天的盟誓，红朝翠暮。', 'public-domain'),
  ('songci300', 211, '齐天乐·烟波桃叶西陵路', 'songci-sc-217', '烟波桃叶西陵路，十年断魂潮尾。古柳重攀，轻鸥聚别，陈迹危亭独倚。凉飔乍起，渺烟碛飞帆，暮山横翠。但有江花，共临秋镜照憔悴。
华堂烛暗送客，眼波回盼处，芳艳流水。素骨凝冰，柔葱蘸雪，犹忆分瓜深意。清尊未洗，梦不湿行云，漫沾残泪。可惜秋宵，乱蛩疏雨里。', '烟波中桃叶渡、西陵路，十年来魂断在潮尾。古柳再次攀折，轻鸥聚散，旧迹里独倚危亭。凉风忽起，烟碛上远帆缥缈，暮山横着翠色。只有江花，一同临着秋镜照我的憔悴。
华堂烛暗送客，她眼波回盼的地方，芳艳如流水。素骨凝冰，柔指蘸雪，还记得分瓜时的深意。清酒杯还没洗，梦不能湿行云，只白沾残泪。可惜这秋宵，在乱蟋蟀和疏雨里。', 'public-domain'),
  ('songci300', 212, '花犯·小娉婷', 'songci-sc-218', '小娉婷，清铅素靥，蜂黄暗偷晕。翠翘敧鬓。昨夜冷中庭，月下相认。睡浓更苦凄风紧。惊回心未稳。送晓色、一壶葱茜，才知花梦准。
湘娥化作此幽芳，凌波路，古岸云沙遗恨。临砌影，寒香乱、冻梅藏韵。熏炉畔、旋移傍枕，还又见、玉人垂绀鬓。料唤赏、清华池馆，台杯须满引。', '小小的娉婷身影，清淡铅素的脸颊，暗暗透出一晕蜂黄。翠翘斜插鬓边。昨夜清冷的庭中，在月下相认。睡得正浓更苦于凄风紧吹，惊回后心神未稳。送来晓色，一壶葱茜，才知道花梦是真的。
是湘娥化作这幽芳，行凌波之路，古岸云沙留下遗恨。临着台阶的影子，寒香纷乱，像冻梅藏着韵味。在熏炉边，随即移到枕旁，又看见玉人垂下青黑的鬓发。料想会唤人同赏，在这清华的池馆里，台上的杯子须满满地饮。', 'public-domain'),
  ('songci300', 213, '浣溪沙·门隔花深梦旧游', 'songci-sc-219', '门隔花深梦旧游，夕阳无语燕归愁。玉纤香动小帘钩。
落絮无声春堕泪，行云有影月含羞。东风临夜冷于秋。', '门隔着深花，梦里回到旧游之处；夕阳无语，燕子归去带着愁。她的纤手带着香气，拨动小帘钩。
落絮无声，是春天在落泪；行云有影，是月儿含羞。东风入夜，比秋天还冷。', 'public-domain'),
  ('songci300', 214, '点绛唇·卷尽愁云', 'songci-sc-220', '卷尽愁云，素娥临夜新梳洗。暗尘不起，酥润凌波地。
辇路重来，仿佛灯前事。情如水，小楼熏被，春梦笙歌里。', '愁云卷尽，嫦娥在夜里刚梳洗过。暗尘不起，地面酥润，是她凌波走过的地方。
重来御街，仿佛还是灯前旧事。情意如水；小楼里熏着被子，春梦在笙歌里。', 'public-domain'),
  ('songci300', 215, '祝英台近·剪红情', 'songci-sc-221', '剪红情，裁绿意，花信上钗股。残日东风，不放岁华去。有人添烛西窗，不眠侵晓，笑声转、新年莺语。
旧尊俎。玉纤曾擘黄柑，柔香系幽素。归梦湖边，还迷镜中路。可怜千点吴霜，寒销不尽，又相对、落梅如雨。', '剪出红情，裁出绿意，花信插上钗股。残日东风，不肯放岁华归去。有人在西窗添烛，不睡到天明，笑声转为新年的莺语。
旧日的酒席。她的纤手曾剖开黄柑，柔香系着幽素。归梦到湖边，还迷在镜般的路上。可怜千点吴地的霜，寒气销不尽，又相对看着落梅如雨。', 'public-domain'),
  ('songci300', 216, '风入松·听风听雨过清明', 'songci-sc-222', '听风听雨过清明，愁草瘗花铭。楼前绿暗分携路，一丝柳、一寸柔情。料峭春寒中酒，交加晓梦啼莺。
西园日日扫林亭，依旧赏新晴。黄蜂频扑秋千索，有当时、纤手香凝。惆怅双鸳不到，幽阶一夜苔生。', '听着风、听着雨过了清明，愁闷中写下葬花的铭文。楼前绿荫暗暗，是分手时的路；一丝柳条，就是一寸柔情。料峭春寒里喝醉了酒，交加的晓梦被黄莺啼醒。
西园天天打扫林亭，依旧去赏新晴。黄蜂频频扑着秋千索，那里有她当时纤手留下的香。惆怅那双鸳鸯鞋不再来，幽静的台阶一夜就生了青苔。', 'public-domain'),
  ('songci300', 217, '莺啼序·残寒正欺病酒', 'songci-sc-223', '残寒正欺病酒，掩沉香绣户。燕来晚、飞入西城，似说春事迟暮。画船载、清明过却，晴烟冉冉吴宫树。念羁情、游荡随风，化为轻絮。
十载西湖，傍柳系马，趁娇尘软雾。溯红渐、招入仙溪，锦儿偷寄幽素。倚银屏、春宽梦窄，断红湿、歌纨金缕。暝堤空，轻把斜阳，总还鸥鹭。
幽兰旋老，杜若还生，水乡尚寄旅。别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。青楼仿佛，临分败壁题诗，泪墨惨淡尘土。
危亭望极，草色天涯，叹鬓侵半苎。暗点检、离痕欢唾，尚染鲛绡，亸凤迷归，破鸾慵舞。殷勤待写，书中长恨，蓝霞辽海沉过雁，漫相思、弹入哀筝柱。伤心千里江南，怨曲重招，断魂在否？', '残寒正欺负病酒的人，我掩上沉香木的绣户。燕子来得晚，飞入西城，像在说春事已近迟暮。画船载着，清明已经过去了；晴烟冉冉，笼着吴宫的树。想那羁旅之情，随风游荡，化作轻絮。
十年前在西湖，傍着柳树系马，趁着娇尘软雾。沿着花丛渐渐被招入仙溪，锦儿偷偷送来幽情。靠着银屏，春夜宽而梦短；断红打湿了歌扇金缕衣。暮色中堤上空空，轻轻把斜阳都还给了鸥鹭。
幽兰转眼就老，杜若又生，我还在水乡寄旅。别后访遍六桥也没有消息，往事已去，花也凋萎；葬玉埋香，经过几番风雨。长波嫉妒她的眼波，远山羞于比她的眉黛。渔灯分影，曾在春江夜宿，记得当时短桨划向桃根渡。青楼仿佛还在，临别时在败壁上题诗，泪墨惨淡，已落满尘土。
在高亭上极目远望，草色直到天涯，可叹鬓边已白了一半。暗暗点检旧物：离别的泪痕、欢笑的唾痕，还染在鲛绡上；凤钗斜垂，鸾镜残破懒得再舞。想殷勤写书，写尽长恨，可蓝天大海雁信沉没；只能白白相思，弹入哀筝的弦柱。伤心啊，千里江南；重唱怨曲招魂，那断了的魂还在吗？', 'public-domain'),
  ('songci300', 218, '惜黄花慢·送客吴皋', 'songci-sc-224', '送客吴皋，正试霜夜冷，枫落长桥。望天不尽，背城渐杳，离亭黯黯，恨水迢迢。翠香零落红衣老，暮愁锁、残柳眉梢。念瘦腰，沈郎旧日，曾系兰桡。
仙人凤咽琼箫，怅断魂送远，《九辩》难招。醉鬟留盼，小窗剪烛，歌云载恨，飞上银霄。素秋不解随船去，败红趁、一叶寒涛。梦翠翘，怨鸿料过南谯。', '在吴地水边送客，正逢霜降夜冷，枫叶落在长桥。望天望不尽，背城渐渐渺茫；离亭黯然，恨水迢迢。翠香零落，荷花老去，暮愁锁在残柳的眉梢。想那瘦腰的沈约，旧日曾在这里系过兰舟。
仙人吹着凤鸣般的琼箫，惆怅断魂送远，《九辩》也难招回。醉中的她留着盼顾，小窗剪烛，歌声载着恨飞上银霄。素秋不懂得随船离去，败红趁着一叶寒涛。梦见翠翘，怨鸿料想已飞过南谯。', 'public-domain'),
  ('songci300', 219, '高阳台·宫粉雕痕', 'songci-sc-225', '宫粉雕痕，仙云堕影，无人野水荒湾。古石埋香，金沙锁骨连环。南楼不恨吹横笛，恨晓风、千里关山。半飘零，庭上黄昏，月冷阑干。
寿阳空理愁鸾，问谁调玉髓，暗补香瘢？细雨归鸿，孤山无限春寒。离魂难倩招清些，梦缟衣、解佩溪边。最愁人，啼鸟晴明，叶底青圆。', '宫粉留下雕痕，仙云堕下影子，无人的野水荒湾。古石埋着香，金沙如锁骨连环。南楼不恨横笛吹起，只恨晓风吹过千里关山。一半飘零，庭上黄昏，月冷栏杆。
寿阳公主白白对着鸾镜发愁，问谁来调玉髓，暗补那香瘢？细雨中归鸿飞过，孤山无限春寒。离魂难以招回，梦见缟衣人解佩在溪边。最愁人的是，晴明时啼鸟鸣叫，叶底已结出青青圆果。', 'public-domain'),
  ('songci300', 220, '三姝媚·湖山经醉惯', 'songci-sc-226', '湖山经醉惯。渍春衫、啼痕酒痕无限。又客长安，叹断襟零袂，涴尘谁浣？紫曲门荒，沿败井、风摇青蔓。对语东邻，犹是曾巢，谢堂双燕。
春梦人间须断。但怪得当年，梦缘能短。绣屋秦筝，傍海棠偏爱，夜深开宴。舞歇歌沉，花未减、红颜先变。伫久河桥欲去，斜阳泪满。', '湖山间我醉惯了。春衫上渍着啼痕酒痕，无边无际。又客居京城，可叹衣襟破断、衣袖零落，沾了尘谁替我洗？紫曲的门已荒，沿着败井，风摇着青蔓。东邻的燕子相互对语，还是当年在谢家堂上筑过巢的那一双。
人间的春梦终究要断。只怪当年梦缘太短。绣屋里的秦筝，偏偏爱在海棠边，夜深设宴。舞歇歌沉，花还没减，红颜先变了。在河桥上久立将要离去，斜阳里泪满衣襟。', 'public-domain'),
  ('songci300', 221, '八声甘州·渺空烟四远', 'songci-sc-227', '渺空烟四远，是何年、青天坠长星？幻苍崖云树，名娃金屋，残霸宫城。箭径酸风射眼，腻水染花腥。时靸双鸳响，廊叶秋声。', '空旷的烟霭伸向四方，是哪一年，青天坠下这颗长星？化作苍崖云树、名娃金屋，残霸的宫城。箭径上冷风刺眼，腻水把花都染上腥气。还不时传来双鸳鞋的声响，是廊上落叶的秋声。', 'public-domain'),
  ('songci300', 222, '踏莎行·润玉笼绡', 'songci-sc-228', '润玉笼绡，檀樱倚扇。绣圈犹带脂香浅。榴心空叠舞裙红，艾枝应压愁鬟乱。
午梦千山，窗阴一箭。香瘢新褪红丝腕。隔江人在雨声中，晚风菰叶生秋怨。', '润玉般的手腕笼着绡纱，檀红的樱桃小口靠着扇子。绣圈上还带着浅淡的脂香。石榴花心白白叠成舞裙的红，艾枝该压住了愁乱的鬓发。
午梦里越过千山，窗下光阴只在一箭之间。红丝线般的手腕上香瘢刚褪。隔着江的人在雨声里，晚风吹着菰叶，生出秋怨。', 'public-domain'),
  ('songci300', 223, '瑞鹤仙·晴丝牵绪乱', 'songci-sc-229', '晴丝牵绪乱。对沧江斜日，花飞人远。垂杨暗吴苑，正旗亭烟冷，河桥风暖。兰情蕙盼，惹相思、春根酒畔。又争知、吟骨萦销，渐把旧衫重剪。
凄断。流红千浪，缺月孤楼，总难留燕。歌尘凝扇。待凭信，拌分钿。试挑灯欲写，还依不忍，笺幅偷和泪卷。寄残云、剩雨蓬莱，也应梦见。', '晴丝牵得心绪纷乱。对着沧江斜日，花飞人远。垂杨暗暗遮住吴苑，正是旗亭烟冷、河桥风暖。兰样的情、蕙样的眼，惹起相思，在春根酒边。她又怎知，我因吟咏消瘦，渐渐要把旧衫重新裁剪。
凄断。流红千重浪，缺月照着孤楼，总难留住燕子。歌尘凝在扇上。想凭书信，拼着分钿。试着挑亮灯要写，还是依恋不忍，偷偷把笺纸和泪卷起。寄到残云剩雨的蓬莱，她也该梦见。', 'public-domain'),
  ('songci300', 224, '夜游宫·人去西楼雁杳', 'songci-sc-231', '人去西楼雁杳，叙别梦、扬州一觉。云澹星疏楚山晓。听啼乌，立河桥，话未了。
雨外蛩声早，细织就、霜丝多少？说与萧娘未知道。向长安，对秋灯，几人老？', '人已离开西楼，雁信渺茫；叙别之梦，像扬州一觉。云淡星疏，楚山泛晓。听乌鸦啼叫，立在河桥上，话还没说完。
雨外的蟋蟀叫得早，细细织成了多少霜丝般的白发？说给她听，她还不知道。向着长安，对着秋灯，有多少人就这样老了？', 'public-domain'),
  ('songci300', 225, '兰陵王·送春去', 'songci-sc-234', '送春去，春去人间无路。秋千外、芳草连天，谁遣风沙暗南浦？依依甚意绪？漫忆海门飞絮。乱鸦过，斗转城荒，不见来时试灯处。
春去，最谁苦？但箭雁沉边，梁燕无主，杜鹃声里长门暮。想玉树凋土，泪盘如露。咸阳送客屡回顾，斜日未能度。
春去，尚来否？正江令恨别，庾信愁赋，苏堤尽日风和雨。叹神游故国，花记前度。人生流落，顾孺子，共夜语。', '送春天归去，春天走后人间没有归路。秋千外芳草连天，是谁让风沙遮暗了南浦？依依不舍是什么意绪？空自回忆海门飞絮。乱鸦飞过，北斗转动、城池荒废，看不见来时试灯的地方。
春天走了，谁最苦？只有边地沉落的箭雁、无主的梁燕，杜鹃声里长门已暮。想那玉树凋零入土，承露盘上的泪像露水。像咸阳送客一再回头，斜阳也迟迟不肯落下。
春天走了，还会回来吗？正是江总恨别、庾信写愁赋的时候，苏堤整日风和雨。可叹神游故国，花还记得前度。人生流落，只能看着孩子，一同夜话。', 'public-domain'),
  ('songci300', 226, '高阳台·照野旌旗', 'songci-sc-235', '照野旌旗，朝天车马，平沙万里天低。宝带金章，尊前茸帽风敧。秦关汴水经行地，想登临、都付新诗。纵英游，叠鼓清笳，骏马名姬。
酒酣应对燕山雪，正冰河月冻，晓陇云飞。投老残年，江南谁念方回？东风渐绿西湖柳，雁已还、人未南归。最关情，折尽梅花，难寄相思。', '旌旗照遍原野，朝天的车马，平沙万里，天幕低垂。宝带金章，杯前茸帽被风吹斜。秦关汴水是你经过的地方，想登临之处都化作了新诗。纵情英游，叠鼓清笳，骏马名姬。
酒酣时面对燕山的雪，正是冰河月冻、晓陇云飞的时候。垂老的残年，江南有谁念我？东风渐渐染绿西湖的柳，大雁已经回来，人却未南归。最牵动心肠的是，梅花折尽了，相思也难寄。', 'public-domain'),
  ('songci300', 227, '瑶华·朱钿宝玦', 'songci-sc-236', '朱钿宝玦，天上飞琼，比人间春别。江南江北，曾未见、漫拟梨云梅雪。淮山春晚，问谁识、芳心高洁？消几番、花落花开，老了玉关豪杰。
金壶剪送琼枝，看一骑红尘，香度瑶阙。韶华正好，应自喜、初识长安蜂蝶。杜郎老矣，想旧事、花须能说。记少年、一梦扬州，二十四桥明月。', '红钿宝玦，天上飞下的琼花，与人间的春色不同。江南江北，未曾见过，只能空比作梨云梅雪。淮山春暮，问谁能懂得它芳心的高洁？经过几番花开花落，玉关的豪杰也老了。
用金壶剪送琼枝，看一骑红尘，香气度入瑶阙。韶华正好，该自喜初次认识长安的蜂蝶。杜郎已老，想旧事，花应该还能说。记得少年时一梦扬州，二十四桥的明月。', 'public-domain'),
  ('songci300', 228, '玉京秋·烟水阔', 'songci-sc-237', '烟水阔。高林弄残照，晚蜩凄切。碧砧度韵，银床飘叶。衣湿桐阴露冷，采凉花、时赋秋雪。叹轻别，一襟幽事，砌蛩能说。
客思吟商还怯。怨歌长、琼壶暗缺。翠扇恩疏，红衣香褪，翻成消歇。玉骨西风，恨最恨、闲却新凉时节。楚箫咽，谁寄西楼淡月。', '烟水空阔。高林摆弄着残照，晚蝉叫声凄切。碧绿的捣衣声传来韵味，井栏上飘下落叶。桐荫里露冷水湿衣裳，采着凉花，不时咏叹秋雪。可叹轻易离别，一襟幽事，只有台阶下的蟋蟀能说。
客愁吟起商调还觉胆怯。怨歌悠长，玉壶暗暗敲缺。翠扇的恩情疏了，红衣的香气褪了，反而成了消歇。玉骨迎着西风，最恨的是白白荒废了新凉的时节。楚箫呜咽，谁寄西楼那淡月。', 'public-domain'),
  ('songci300', 229, '曲游春·禁苑东风外', 'songci-sc-238', '禁苑东风外，飏暖丝晴絮，春思如织。燕约莺期，恼芳情偏在，翠深红隙。漠漠香尘隔。沸十里、乱弦丛笛。看画船、尽入西泠，闲却半湖春色。
柳陌，新烟凝碧。映帘底宫眉，堤上游勒。轻暝笼寒，怕梨云梦冷，杏香愁幂。歌管酬寒食。奈蝶怨、良宵岑寂。正满湖、碎月摇花，怎生去得？', '宫苑东风之外，暖风扬起游丝晴絮，春思像织。燕子黄莺的约会，恼人的芳情偏偏在翠绿深处、红花缝里。漠漠香尘隔断。十里内沸腾着乱弦丛笛。看画船都驶入西泠，把半湖春色空了出来。
柳陌上，新烟凝着碧色。映着帘下的宫样眉，堤上游人的马络头。轻暮笼着寒意，怕梨云梦冷、杏香愁浓。歌管酬答寒食。怎奈蝴蝶怨良宵岑寂。正当满湖碎月摇花，怎么舍得离去？', 'public-domain'),
  ('songci300', 230, '花犯·楚江湄', 'songci-sc-239', '楚江湄，湘娥乍见，无言洒清泪。淡然春意。空独倚东风，芳思谁寄？凌波路冷秋无际，香云随步起。谩记得、汉宫仙掌，亭亭明月底。
冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。春思远，谁叹赏、国香风味？相将共、岁寒伴侣，小窗净、沉烟熏翠袂。幽梦觉，涓涓清露，一枝灯影里。', '楚江边上，湘妃忽然相见，无言地洒下清泪。淡然的春意。空自独倚东风，芳心寄给谁？凌波之路清冷，秋意无边；香云随着脚步升起。白白记得汉宫的仙掌，亭亭立在明月底下。
冰弦写怨更多情，骚人的恨，白白赋写芳兰幽芷。春思遥远，谁来叹赏这国色的风味？要结为岁寒的伴侣，小窗洁净，沉香熏着翠袖。幽梦醒来，涓涓清露，一枝花在灯影里。', 'public-domain'),
  ('songci300', 231, '瑞鹤仙·绀烟迷雁迹', 'songci-sc-240', '绀烟迷雁迹，渐碎鼓零钟，街喧初息。风檠背寒壁。放冰蜍飞到，丝丝帘隙。琼瑰暗泣。念乡关、霜芜似织。漫将身、化鹤归来，忘却旧游端的。
欢极。蓬壶蕖浸，花院梨溶，醉连春夕。柯云罢弈。樱桃在，梦难觅。劝清光，乍可幽窗相伴，休照红楼夜笛。怕人间、换谱伊凉，素娥未识。', '青红烟霭遮住雁的踪迹，渐渐鼓声碎、钟声零落，街市喧闹刚停。风灯背靠寒壁。让冰蟾般的月亮飞进来，一丝丝穿过帘缝。美玉暗暗哭泣。想乡关那边，霜后的荒草像织。空自化作仙鹤归来，却忘了旧游的究竟。
欢乐到极处。蓬壶的荷花浸泡，花院的梨花开溶，醉连着春夜。斧柄烂了棋也下完。樱桃还在，梦却难寻。劝月光，宁可只在幽窗前相伴，不要照那红楼夜笛。怕人间换了伊凉曲谱，嫦娥不认得。', 'public-domain'),
  ('songci300', 232, '天香·孤峤蟠烟', 'songci-sc-241', '孤峤蟠烟，层涛蜕月，骊宫夜采铅水。汛远槎风，梦深薇露，化作断魂心字。红瓷候火，还乍识、冰环玉指。一缕萦帘翠影，依稀海天云气。
几回殢娇半醉。剪春灯、夜寒花碎。更好故溪飞雪，小窗深闭。荀令如今顿老，总忘却、尊前旧风味。谩惜余薰，空篝素被。', '孤岛上烟雾盘旋，层层波涛退出月光，骊宫夜里采来铅水。远汛的槎风，深梦里蔷薇露水，化做断魂的心字香。红瓷守着火候，才初次认识冰环玉指。一缕香萦绕帘上的翠影，依稀是海天的云气。
几回她娇困半醉，剪着春灯，夜寒里灯花碎落。更好的是故溪飞雪，小窗深深关闭。荀令如今忽然老了，都忘了杯前旧日的风味。白白怜惜余香，空着香笼和素被。', 'public-domain'),
  ('songci300', 233, '眉妩·渐新痕悬柳', 'songci-sc-242', '渐新痕悬柳，淡彩穿花，依约破初暝。便有团圆意，深深拜，相逢谁在香径？画眉未稳，料素娥、犹带离恨。最堪爱、一曲银钩小，宝帘挂秋冷。
千古盈亏休问，叹慢磨玉斧，难补金镜。太液池犹在，凄凉处、何人重赋清景？故山夜永，试待他、窥户端正。看云外山河，还老尽、桂花影。', '新的月痕渐渐挂在柳上，淡淡的光彩穿过花间，隐约划破初暗的暮色。既有团圆的意味，就深深下拜——可相逢时谁在香径？眉还未画稳，料想嫦娥还带着离恨。最可爱的是那一弯小小的银钩，宝帘挂在秋寒里。
千古的盈亏不必问，可叹白白磨着玉斧，也难补圆金镜。太液池还在，凄凉之处，谁来重写清景？故山的夜长，且等它从门窗端正地照进来。看那云外的山河，桂花影也老尽了。', 'public-domain'),
  ('songci300', 234, '齐天乐·一襟余恨宫魂断', 'songci-sc-243', '一襟余恨宫魂断，年年翠阴庭树。乍咽凉柯，还移暗叶，重把离愁深诉。西窗过雨。怪瑶佩流空，玉筝调柱。镜暗妆残，为谁娇鬓尚如许？
铜仙铅泪似洗，叹携盘去远，难贮零露。病翼惊秋，枯形阅世，消得斜阳几度？余音更苦。甚独抱清商，顿成凄楚？谩想薰风，柳丝千万缕。', '一襟余恨，宫魂已断，年年栖在庭树的翠阴里。忽而在凉枝上呜咽，忽而移到暗叶间，重新把离愁深深倾诉。西窗下过雨。奇怪那玉佩在空中流过、玉筝在调柱。镜已暗、妆已残，她为谁还把鬓发弄得这样娇美？
铜人的铅泪像洗过一样，可叹它被携盘带走远了，难以贮存点滴露水。病翅惊秋，枯形阅世，还能经得几度斜阳？余音更苦。为什么独抱清商之调，顿时变得凄楚？白白想起和暖的风，那千万缕柳丝。', 'public-domain'),
  ('songci300', 235, '长亭怨慢·泛孤艇', 'songci-sc-244', '泛孤艇、东皋过遍。尚记当日，绿阴门掩。屐齿莓阶，酒痕罗袖事何限。欲寻前迹，空惆怅、成秋苑。自约赏花人，别后总、风流云散。
水远。怎知流水外，却是乱山尤远。天涯梦短，想忘了、绮疏雕槛。望不尽、冉冉斜阳，抚乔木、年华将晚。但数点红英，犹识西园凄婉。', '泛着孤舟，把东皋走遍。还记得当日，绿荫下门扉掩着。木屐的齿印在苔阶上，酒痕在罗袖上，旧事有多少。想寻找前迹，只落得惆怅，已成了秋天的园苑。当年相约赏花的人，别后总是风流云散。
水远。怎知流水之外，还有乱山更远。天涯梦短，想她已忘了那雕花门窗。望不尽冉冉斜阳，抚着乔木，年华将晚。只有几点红花，还记得西园的凄婉。', 'public-domain'),
  ('songci300', 236, '高阳台·接叶巢莺', 'songci-sc-245', '接叶巢莺，平波卷絮，断桥斜日归船。能几番游？看花又是明年。东风且伴蔷薇住，到蔷薇、春已堪怜。更凄然，万绿西泠，一抹荒烟。
当年燕子知何处？但苔深韦曲，草暗斜川。见说新愁，如今也到鸥边。无心再续笙歌梦，掩重门、浅醉闲眠。莫开帘，怕见飞花，怕听啼鹃。', '密叶里黄莺筑巢，平波卷着柳絮，断桥斜阳下归来的是船。还能游几番？再看花又要等明年。东风且伴着蔷薇留住吧，到蔷薇开时，春天已值得怜惜。更凄然的是，万绿丛中的西泠，只有一抹荒烟。
当年的燕子知道在哪里？只有韦曲苔深，斜川草暗。听说新愁，如今也到了鸥鸟身边。无心再续笙歌的梦，掩上重门，浅醉闲眠。不要开帘——怕见飞花，怕听杜鹃。', 'public-domain'),
  ('songci300', 237, '解连环·楚江空晚', 'songci-sc-247', '楚江空晚，怅离群万里，恍然惊散。自顾影、欲下寒塘，正沙净草枯，水平天远。写不成书，只寄得、相思一点。料因循误了，残毡拥雪，故人心眼。
谁怜旅愁荏苒？谩长门夜悄，锦筝弹怨。想伴侣、犹宿芦花，也曾念春前，去程应转。暮雨相呼，怕蓦地、玉关重见。未羞他、双燕归来，画帘半卷。', '楚江空阔天晚，惆怅离群万里，恍然惊散。自顾身影，想落下寒塘，正是沙净草枯、水平天远。写不成书信，只能寄去一点相思。料想因循耽误了，像苏武残毡拥雪那样，辜负故人的心眼。
谁怜旅愁荏苒？空自对着长门夜静，锦筝弹怨。想同伴还宿在芦花里，也曾想过春前就该转回程。暮雨中互相呼唤，怕忽然在玉关重见。那时也不羞于看那双燕归來，画帘半卷。', 'public-domain'),
  ('songci300', 238, '疏影·碧圆自洁', 'songci-sc-248', '碧圆自洁，向浅洲远渚，亭亭清绝。犹有遗簪，不展秋心，能卷几多炎热？鸳鸯密语同倾盖，且莫与、浣纱人说。恐怨歌、忽断花风，碎却翠云千叠。
回首当年汉舞，怕飞去、谩皱留仙裙摺。恋恋青衫，犹染枯香，还叹鬓丝飘雪。盘心清露如铅水，又一夜、西风吹折。喜静看、匹练秋光，倒泻半湖明月。', '碧圆的荷叶自然清洁，向着浅洲远渚，亭亭清绝。还有像遗落的玉簪，不肯展开秋心，能卷住多少炎热？鸳鸯密语，如同倾盖相交，且不要对浣纱人说。怕怨歌忽被花风吹断，碎了千叠翠云。
回想当年汉宫的舞，怕它飞去，白白皱起留仙裙的褶。恋恋的青衫，还染着枯香，又叹鬓发如飘雪。盘心的清露像铅水，又一夜被西风吹折。喜的是静静看那匹练般的秋光，倒泻出半湖明月。', 'public-domain'),
  ('songci300', 239, '声声慢·寻寻觅觅', 'poems-gz10-09', '寻寻觅觅，冷冷清清，凄凄惨惨戚戚。
乍暖还寒时候，最难将息。
三杯两盏淡酒，怎敌他、晚来风急！
雁过也，正伤心，却是旧时相识。
满地黄花堆积，憔悴损，如今有谁堪摘？
守着窗儿，独自怎生得黑！
梧桐更兼细雨，到黄昏、点点滴滴。
这次第，怎一个愁字了得！', '苦苦地寻找寻觅，四处冷冷清清，心中凄凄惨惨悲悲戚戚。天气忽暖忽冷的时候，最难调养身体。三杯两盏淡酒，怎么能抵挡傍晚的急风！大雁飞过，正令人伤心，却原来是旧时相识。满地菊花堆积，我如此憔悴，如今有谁还能采摘？守着窗子，独自一个人怎么才能挨到天黑！梧桐树又加上细雨，到黄昏时分，点点滴滴。这情景，一个愁字怎么能说得尽！', 'academic'),
  ('songci300', 240, '念奴娇·萧条庭院', 'songci-sc-250', '萧条庭院，又斜风细雨，重门须闭。宠柳娇花寒食近，种种恼人天气。险韵诗成，扶头酒醒，别是闲滋味。征鸿过尽，万千心事难寄。
楼上几日春寒，帘垂四面，玉阑干慵倚。被冷香消新梦觉，不许愁人不起。清露晨流，新桐初引，多少游春意！日高烟敛，更看今日晴未？', '庭院萧条，又是斜风细雨，重门该关上了。宠柳娇花，寒食将近，种种恼人的天气。险韵的诗写成，扶头的酒醒来，另有一番闲滋味。征鸿过尽，万千心事难以寄去。
楼上几日春寒，四面垂帘，玉栏杆也懒得去倚。被子冷了、香气消了，新梦醒来，不许愁人不起身。清露在晨光里流，新桐刚抽芽，有多少游春的意兴！太阳升高、雾气收敛，再看看今天晴不晴？', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('songci300', 241, '永遇乐·落日熔金', 'songci-sc-251', '落日熔金，暮云合璧，人在何处？染柳烟浓，吹梅笛怨，春意知几许？元宵佳节，融和天气，次第岂无风雨？来相召、香车宝马，谢他酒朋诗侣。
中州盛日，闺门多暇，记得偏重三五。铺翠冠儿，捻金雪柳，簇带争济楚。如今憔悴，风鬟霜鬓，怕见夜间出去。不如向、帘儿底下，听人笑语。', '落日像熔化的金子，暮云如合拢的璧玉，人在哪里？柳色被浓烟染过，笛声吹着《梅花落》的怨曲，春意能有多少？元宵佳节，天气融和，难道就不会有风雨？有人用香车宝马来相邀，我谢绝了酒朋诗侣。
中州盛时的日子，闺中多有闲暇，记得特别看重正月十五。铺翠的冠儿、捻金的雪柳，簇带争着齐整。如今憔悴，风鬟霜鬓，怕在夜里出去。不如守在帘子底下，听别人笑语。', 'public-domain'),
  ('songci300', 242, '一剪梅·红藕香残玉簟秋', 'songci-sc-252', '红藕香残玉簟秋。轻解罗裳，独上兰舟。云中谁寄锦书来？雁字回时，月满西楼。
花自飘零水自流。一种相思，两处闲愁。此情无计可消除，才下眉头，却上心头。', '红藕香残，玉席生凉，已是秋天。轻轻解开罗裳，独自登上兰舟。云中谁寄书信来？雁字归来时，月满西楼。
花自飘零，水自流去。同一种相思，分成两处的闲愁。这份情没有办法消除，刚下了眉头，又上了心头。', 'public-domain'),
  ('songci300', 243, '醉花阴·薄雾浓云愁永昼', 'songci-sc-253', '薄雾浓云愁永昼，瑞脑消金兽。佳节又重阳，玉枕纱厨，半夜凉初透。
东篱把酒黄昏后，有暗香盈袖。莫道不销魂，帘卷西风，人比黄花瘦。', '薄雾浓云，整日发愁；龙脑香在铜兽香炉里渐渐烧尽。又到重阳佳节，玉枕纱帐，半夜里凉意初透。
黄昏后在东篱下举杯，有暗香盈袖。不要说不会消魂——西风卷起帘子，人比菊花还瘦。', 'public-domain'),
  ('songci300', 244, '凤凰台上忆吹箫·香冷金猊', 'songci-sc-254', '香冷金猊，被翻红浪，起来慵自梳头。任宝奁尘满，日上帘钩。生怕离怀别苦，多少事、欲说还休。新来瘦，非干病酒，不是悲秋。
休休！这回去也，千万遍阳关，也则难留。念武陵人远，烟锁秦楼。惟有楼前流水，应念我、终日凝眸。凝眸处，从今又添，一段新愁。', '香炉里的香冷了，锦被翻起红浪，起身后懒懒地不想梳头。任凭宝奁积满灰尘，太阳升上帘钩。最怕离怀别苦，多少事想说又停住。近来瘦了，不是因为病酒，也不是悲秋。
算了算了！这一去，唱千万遍《阳关》，也还是留不住。想那武陵人已远，烟雾锁住秦楼。只有楼前的流水，应该念我终日凝望。凝望的地方，从今又添了一段新愁。', 'public-domain'),
  ('songci300', 245, '武陵春·风住尘香花已尽', 'songci-sc-255', '风住尘香花已尽，日晚倦梳头。物是人非事事休，欲语泪先流。
闻说双溪春尚好，也拟泛轻舟。只恐双溪舴艋舟，载不动许多愁。', '风停了，尘土里带着花香，花已落尽；日头已高，还懒得梳头。景物依旧而人事全非，事事都完了；想说话，泪先流下来。
听说双溪的春色还好，也打算去泛轻舟。只怕双溪那小小的舴艋舟，载不动我这么多愁。', 'public-domain'),
  ('songci300', 246, '点绛唇·蹴罢秋千', 'songci-sc-342', '蹴罢秋千，起来慵整纤纤手。露浓花瘦，薄汗轻衣透。
见客入来，袜刬金钗溜。和羞走，倚门回首，却把青梅嗅。', '荡完秋千，起身懒得揉一揉纤细的手。露水浓、花儿瘦，一层薄汗湿透了轻衣。
忽然见有客人进来，她慌忙提袜而走，金钗滑落。含羞跑开，又在门边回头张望，假装嗅着手里的青梅。', 'public-domain'),
  ('songci300', 247, '醉落魄·波上春风', 'songci-sc-266', '波上春风，画船明月人归后。画楼闲倚东风久。芳草王孙，知他甚时又。
绿杨影里，海棠亭畔，红杏梢头。拟歌先敛，欲笑还颦，最断人肠。', '水波上吹着春风，画船明月中人已归去之后。久在画楼上闲倚着东风。芳草萋萋，远行的王孙，不知他什么时候才回。
绿杨的影里，海棠亭畔，红杏的枝头。想要歌唱先敛住神情，想要笑又皱起眉头，最是断人肝肠。', 'public-domain'),
  ('songci300', 248, '菩萨蛮·风柔日薄春犹早', 'songci-sc-267', '风柔日薄春犹早，夹衫乍著心情好。睡起觉微寒，梅花鬓上残。
故乡何处是？忘了除非醉。沉水卧时烧，香消酒未消。', '风轻柔，日光淡薄，春天还早，刚换上夹衫，心情很好。睡醒觉得有些微寒，鬓边的梅花已经残了。
故乡在什么地方？要忘记除非醉倒。睡时点起了沉香，如今香已烧尽，酒意还没消。', 'public-domain'),
  ('songci300', 249, '忆秦娥·临高阁', 'songci-sc-268', '临高阁，乱山平野烟光薄。烟光薄，栖鸦归后，暮天闻角。
断香残酒情怀恶，西风催衬梧桐落。梧桐落，又还秋色，又还寂寞。', '登上高阁，乱山平野之上烟气淡薄。烟气淡薄，归巢的乌鸦落下之后，暮色里传来号角声。
残香剩酒，心情很坏，西风催促着梧桐落叶。梧桐落叶，又是秋色，又是寂寞。', 'public-domain'),
  ('songci300', 250, '孤雁儿·藤床纸帐朝眠起', 'songci-sc-269', '藤床纸帐朝眠起，说不尽无佳思。沉香断续玉炉寒，伴我情怀如水。笛声三弄，梅心惊破，多少春情意。
小风疏雨萧萧地，又催下千行泪。吹箫人去玉楼空，肠断与谁同倚。一枝折得，人间天上，没个人堪寄。', '藤床纸帐里早晨睡醒起来，说不尽没有好心情。沉香断断续续，玉炉已冷，陪伴着我如水的情怀。笛声吹起《梅花三弄》，把梅心都惊破了，牵动多少春天的情意。
小风疏雨萧萧地落，又催下千行眼泪。吹箫的人去了，玉楼空着，肝肠寸断又与谁同倚？折得一枝梅花，人间天上，却没有人可以寄。', 'public-domain');
