  ('songci300', 23, '木兰花·东城渐觉风光好', '[["縠皱波纹","如绉纱般的波纹"],["客棹","客船"],["绿杨烟外","绿柳笼罩在烟雾中"],["春意闹","春意浓盛"],["浮生","飘浮短暂的一生"],["肯爱","岂惜"],["晚照","夕阳余晖"]]'),
