  ('songci300', 33, '曲玉管·陇首云飞', '[["陇首","陇山之巅，泛指高地"],["凭阑","倚着栏杆"],["关河","关塞与河流，指旅途"],["萧索","冷落萧条"],["凝眸","注视"],["杳杳","遥远幽深的样子"],["神京","京城"],["锦字","指书信"],["断雁","失群的雁"],["汀洲","水中平地"],["幽欢","幽会的欢乐"],["消黯","黯然神伤"]]'),
  ('songci300', 36, '采莲令·月华收', '[["月华","月光"],["曙","天刚亮"],["西征客","向西远行的人"],["翠娥","指美人"],["临歧","面临岔路，指分别"],["轧轧","开门的声音"],["朱户","红色的门"],["争忍","怎忍"],["兰舟","木兰木造的船，美称"],["方寸","指心"],["脉脉","含情不语的样子"],["重城","层层城郭"]]'),
